INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13513, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自觉", "is_correct": true, "explanation": "“自觉”指自己主动去做，与“垃圾分类要靠大家”的语境相符。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能作为大家共同去做的事，句子读不通。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：“汽油”是燃料，与垃圾分类的参与方式无关。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”指外出游览，不能作为垃圾分类所靠的力量，句子读不通。"}], "explanations": {"自觉": "“自觉”指自己主动去做，与“垃圾分类要靠大家”的语境相符。", "钢琴": "语义：“钢琴”是乐器，不能作为大家共同去做的事，句子读不通。", "汽油": "语义：“汽油”是燃料，与垃圾分类的参与方式无关。", "旅游": "语义：“旅游”指外出游览，不能作为垃圾分类所靠的力量，句子读不通。"}, "sentence_index": 6, "correct_answer": "自觉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他拥有很多自觉，买了好几套房子。", "explanation": "这里应该用〈财富〉。自觉指主动去做的认识，不是可以用来买房的财产。"}, {"text": "她的自觉很好，能看清远处。", "explanation": "这里应该用〈视力〉。自觉是觉悟，不指眼睛看东西的能力。"}, {"text": "他的自觉很响亮，全班都听见了。", "explanation": "这里应该用〈声音〉。自觉指觉悟，不指声音的大小。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13513, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一颗很强的自觉。", "corrected_sentence": "他有一种很强的自觉。", "error_description": "「自觉」前应用量词「种」，「颗」用于圆粒状的东西，不能修饰抽象的觉悟。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13513, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一条学习的自觉。", "corrected_sentence": "她有一种学习的自觉。", "error_description": "量词错误：“条”用于细长之物，不能修饰抽象的自觉，应说“一种”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd3881f99-e783-405c-b8d6-4b2c103f6b3f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生长着树木的土地，通常指森林或树木覆盖的区域。", "primary_collocate": null, "pronunciation": "lín dì", "ipa": "lin˧˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "林地", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这片林地里有很多松树。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "村子后面有一大片林地。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府决定保护这里的林地。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "林地里的空气特别新鲜。", "target_word": "林地", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这块林地已经有五十年的历史了。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们在林地边上搭了一个帐篷。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有人把林地改成了农田，鸟都少了。", "target_word": "林地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，林地里开满了野花。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天走进林地，脚下全是落叶。", "target_word": "林地", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片林地", "label": "量词"}, {"form": "一块林地", "label": "量词"}, {"form": "林地面积", "label": "复合"}], "register": "中性", "sense_fingerprint": "林地|长着树木的土地，森林或树木覆盖的区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确答案：生长着树木的土地。"}, {"text": "领地", "is_correct": false, "explanation": "lǐng（第三声）与 lín（第二声）韵母与声调都不同，意思是领土、势力范围。"}, {"text": "林立", "is_correct": false, "explanation": "lì 与 dì 声母不同（l / d），意思是像树林一样密集地竖立，如高楼林立。"}, {"text": "灵地", "is_correct": false, "explanation": "声调相同，韵母不同（in / ing），灵地意思是风水或灵验的地方，如圣地。"}], "explanations": {"林地": "正确答案：生长着树木的土地。", "领地": "lǐng（第三声）与 lín（第二声）韵母与声调都不同，意思是领土、势力范围。", "林立": "lì 与 dì 声母不同（l / d），意思是像树林一样密集地竖立，如高楼林立。", "灵地": "声调相同，韵母不同（in / ing），灵地意思是风水或灵验的地方，如圣地。"}, "sentence_index": null, "correct_answer": "林地"}, "level_3": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确：“每一片消失的林地”指成片的林地，与土壤退化、生物多样性下跌的生态语境相符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂不是生长树木的土地，放在这一语境中与土壤退化、生物多样性无关联。"}, {"text": "城市", "is_correct": false, "explanation": "搭配：“每一片”不能修饰城市，应说“每一座城市”；且城市消失不会直接关联土壤退化。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆与生态退化没有关系，“消失的图书馆”无法关联土壤退化等生态问题。"}], "explanations": {"林地": "正确：“每一片消失的林地”指成片的林地，与土壤退化、生物多样性下跌的生态语境相符。", "工厂": "语义：工厂不是生长树木的土地，放在这一语境中与土壤退化、生物多样性无关联。", "城市": "搭配：“每一片”不能修饰城市，应说“每一座城市”；且城市消失不会直接关联土壤退化。", "图书馆": "语义：图书馆与生态退化没有关系，“消失的图书馆”无法关联土壤退化等生态问题。"}, "sentence_index": 0, "correct_answer": "林地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山脚下买了一条林地。", "explanation": "这里应该用〈片〉或〈块〉。林地是成片的土地，“条”用于细长的东西，不能修饰林地。"}, {"text": "我家后面有一只林地，很安静。", "explanation": "这里应该用〈片〉。“只”用于动物等，不能用来计量土地。"}, {"text": "村子后面有一颗林地，大家都很喜欢。", "explanation": "这里应该用〈片〉。“颗”用于颗粒、星星等小而圆的东西，林地是大片土地，不能用“颗”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林地", "is_correct": true, "explanation": "正确：林边的空地适合搭帐篷，“在林地边上搭一个帐篷”语义合理。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是室内场所，不会在教室边上搭帐篷，句中语境是户外。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架是室内家具，不能在它边上搭帐篷，与户外搭帐篷的语境不符。"}, {"text": "办公室", "is_correct": false, "explanation": "搭配：搭帐篷的地点应为空地，“办公室”不能与“边上搭一个帐篷”搭配。"}], "explanations": {"林地": "正确：林边的空地适合搭帐篷，“在林地边上搭一个帐篷”语义合理。", "教室": "语义：教室是室内场所，不会在教室边上搭帐篷，句中语境是户外。", "书架": "语义：书架是室内家具，不能在它边上搭帐篷，与户外搭帐篷的语境不符。", "办公室": "搭配：搭帐篷的地点应为空地，“办公室”不能与“边上搭一个帐篷”搭配。"}, "sentence_index": 6, "correct_answer": "林地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村口有一棵林地，夏天特别凉快。", "explanation": "这里应该用〈片〉。“棵”用于单株的树，林地是一大片土地，不能用“棵”计量。"}, {"text": "他家后院有一扇林地。", "explanation": "这里应该用〈片〉。“扇”用于门窗等，林地不能用“扇”计量。"}, {"text": "院子旁边有一盏林地，孩子们常来玩。", "explanation": "这里应该用〈片〉。“盏”用于灯，林地是大片土地，不能用“盏”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山坡上有一条林地。", "corrected_sentence": "山坡上有一片林地。", "error_description": "量词错误：“林地”是成片的土地，应说“一片林地”，不能说“一条林地”。“条”用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13514, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们在一根林地里采蘑菇。", "corrected_sentence": "孩子们在一片林地里采蘑菇。", "error_description": "量词错误：“林地”是成片的土地，应说“一片林地”，不能说“一根林地”。“根”用于细长的东西，如一根绳子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
