INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "土壤退化是指土壤质量下降，导致其生产能力降低或生态功能减弱的过程。", "primary_collocate": null, "pronunciation": "tǔ rǎng tuì huà", "ipa": "tʰu˨˩˦ ɻɑŋ˨˩˦ tʰweɪ˥˩ xwa˥˩", "syllable_count": 4, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "土壤退化", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "土壤退化会让粮食减产。", "target_word": "土壤退化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "过度使用化肥会造成土壤退化。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "专家正在研究土壤退化的原因。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个地区的土壤退化越来越严重。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "种树可以减缓土壤退化。", "target_word": "土壤退化", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "土壤退化使农民的收入减少了。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了防止土壤退化，农民开始轮流种不同的作物。", "target_word": "土壤退化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱和大风也会加重土壤退化。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他写了一篇关于土壤退化的文章。", "target_word": "土壤退化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤退化问题", "label": "复合"}], "register": "书面", "sense_fingerprint": "土壤退化|土壤质量下降、生产能力和生态功能减弱的过程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "土壤退化", "is_correct": true, "explanation": "正确：“关联着土壤退化”与“水源枯竭”“生物多样性下跌”同属生态退化问题，语境相符。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日与土壤、水源和生物多样性无关，不能与“水源枯竭”并列为生态退化的后果。"}, {"text": "方言", "is_correct": false, "explanation": "语义：方言不属于生态要素，无法与“水源枯竭”“生物多样性”并列为生态退化的后果。"}, {"text": "演唱会", "is_correct": false, "explanation": "搭配：“断崖式下跌”说数量或价值，“演唱会”本身不能下跌，也与生态语境不符。"}], "explanations": {"土壤退化": "正确：“关联着土壤退化”与“水源枯竭”“生物多样性下跌”同属生态退化问题，语境相符。", "节日": "语义：节日与土壤、水源和生物多样性无关，不能与“水源枯竭”并列为生态退化的后果。", "方言": "语义：方言不属于生态要素，无法与“水源枯竭”“生物多样性”并列为生态退化的后果。", "演唱会": "搭配：“断崖式下跌”说数量或价值，“演唱会”本身不能下跌，也与生态语境不符。"}, "sentence_index": 0, "correct_answer": "土壤退化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地经过多年的土壤退化，庄稼长得特别好。", "explanation": "这里应该用〈土壤改良〉。“土壤退化”指土壤质量下降，经过它庄稼长不好，不能说长得特别好。"}, {"text": "这口井的土壤退化了，村民只好去山下挑水。", "explanation": "这里应该用〈水源枯竭〉。井里没有水，说的是水源，“土壤退化”只用于土壤质量下降的情况。"}, {"text": "这条河的土壤退化很严重，鱼都死光了。", "explanation": "这里应该用〈水污染〉。河水受污染是水的问题，“土壤退化”只说土壤质量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土壤退化", "is_correct": true, "explanation": "正确：“土壤退化”作主语，导致农民收入减少，与句意相符。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌与农民收入减少没有因果关系，句子不成立。"}, {"text": "童话", "is_correct": false, "explanation": "语义：童话是虚构的故事，与农民收入减少没有因果关系，句子不成立。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴与农民收入减少没有因果关系，句子不成立。"}], "explanations": {"土壤退化": "正确：“土壤退化”作主语，导致农民收入减少，与句意相符。", "诗歌": "语义：诗歌与农民收入减少没有因果关系，句子不成立。", "童话": "语义：童话是虚构的故事，与农民收入减少没有因果关系，句子不成立。", "钢琴": "语义：钢琴与农民收入减少没有因果关系，句子不成立。"}, "sentence_index": 6, "correct_answer": "土壤退化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块地发生土壤退化以后，粮食产量提高了很多。", "explanation": "这里应该用〈土壤改良〉。“土壤退化”指土壤质量下降，会让粮食减产，不会让产量提高。"}, {"text": "他写了一篇关于这座土壤退化的文章。", "explanation": "这里应该用〈种〉。“座”用于山、桥等大型固定的东西，不用于土壤退化这类现象。"}, {"text": "这块地的土壤退化很好，庄稼长得很壮。", "explanation": "这里应该用〈土壤肥力〉。“土壤退化”指土壤变差，不能用“很好”来说它的好坏；说土壤好应用〈土壤肥力〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一片很常见的土壤退化。", "corrected_sentence": "这是一种很常见的土壤退化。", "error_description": "量词错误：“土壤退化”指一种过程，应说“一种”，不能说“一片”。“片”用于面积。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13515, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "农民每年都要面对一座新的土壤退化。", "corrected_sentence": "农民每年都要面对一种新的土壤退化。", "error_description": "量词错误：“土壤退化”指一种过程，应说“一种”，不能说“一座”。“座”用于山、楼等大型固定的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
