INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水源指水流发源的地方，或水供应的来源。", "primary_collocate": null, "pronunciation": "shuǐ yuán", "ipa": "ʂweɪ˨˩˦ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "水源", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河是城市的主要水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里有一处干净的水源。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他们要保护好村子的水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "夏天很热，附近的水源变少了。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们沿着小河找到了水源。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这口井是全村的水源。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "工厂把垃圾倒进河里，会影响水源。", "target_word": "水源", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里找不到水源，人很难活下去。", "target_word": "水源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条河的水源在高山上。", "target_word": "水源", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "处", "label": "量词"}, {"form": "水源地", "label": "复合词"}], "register": "中性", "sense_fingerprint": "河流的发源地，或供水的来源", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "与“枯竭”搭配，指供水的来源，前文说“土壤退化、水源枯竭”。"}, {"text": "水质", "is_correct": false, "explanation": "搭配：“枯竭”用于水源或资源，不说水质枯竭，水质是变差。"}, {"text": "水灾", "is_correct": false, "explanation": "语义：水灾指洪涝灾害，是水过多而非供水减少，不能说“水灾枯竭”。"}, {"text": "水位", "is_correct": false, "explanation": "搭配：水位是下降，不说枯竭，与“枯竭”搭配不当。"}], "explanations": {"水源": "与“枯竭”搭配，指供水的来源，前文说“土壤退化、水源枯竭”。", "水质": "搭配：“枯竭”用于水源或资源，不说水质枯竭，水质是变差。", "水灾": "语义：水灾指洪涝灾害，是水过多而非供水减少，不能说“水灾枯竭”。", "水位": "搭配：水位是下降，不说枯竭，与“枯竭”搭配不当。"}, "sentence_index": 0, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要疏通村子的水源。", "explanation": "这里应该用〈河道〉。疏通说的是河道、水沟，水源是水的来源，不能疏通。"}, {"text": "山脚下有一条水源，村民每天都去取水。", "explanation": "这里应该用〈处〉。水源是地点，计量地点用〈处〉；用来计量河流、道路的量词，不能用在水源上。"}, {"text": "他们把水源装进瓶子里带回家。", "explanation": "这里应该用〈饮用水〉。水源指地方或来源，不能装进瓶子；装进瓶子带回家的是饮用水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水源", "is_correct": true, "explanation": "与“全村的”搭配，指全村依赖的供水来源，符合句意。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是供水的来源，“这口井是全村的水果”不成立。"}, {"text": "水利", "is_correct": false, "explanation": "语义：“水利”指水利工程，不指供水来源，句中说的是一口井。"}, {"text": "水管", "is_correct": false, "explanation": "语义：水管是输水的管道，不是水的来源，“这口井是全村的水管”不成立。"}], "explanations": {"水源": "与“全村的”搭配，指全村依赖的供水来源，符合句意。", "水果": "语义：水果不是供水的来源，“这口井是全村的水果”不成立。", "水利": "语义：“水利”指水利工程，不指供水来源，句中说的是一口井。", "水管": "语义：水管是输水的管道，不是水的来源，“这口井是全村的水管”不成立。"}, "sentence_index": 6, "correct_answer": "水源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的水源在大海里。", "explanation": "这里应该用〈河口〉。河口是河流入海的地方，水源是水开始流出的地方。"}, {"text": "这条河的水源很重，一个人搬不动。", "explanation": "这里应该用〈石头〉之类的物体。水源是地点或来源，不能说重、搬不动。"}, {"text": "这条河的水源跑得很快，比河水还快。", "explanation": "这里应该用〈流速〉。水源是地方，没有快慢；说水流的快慢要用〈流速〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村子后面有一条水源，水很清。", "corrected_sentence": "村子后面有一处水源，水很清。", "error_description": "量词错误：“水源”作地点，量词应用“处”，说“一处水源”；“条”多用于河流、道路，不用于水源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13516, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "镇子东边有一根水源，水很甜。", "corrected_sentence": "镇子东边有一处水源，水很甜。", "error_description": "量词错误：“水源”作地点，应说“一处水源”，不能说“一根水源”。“根”用于细长的东西。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "形容水源断流或资源用尽。", "primary_collocate": null, "pronunciation": "kū jié", "ipa": "kʰu˥ tɕjɛ˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "枯竭", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条河的水已经枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干旱太久，村里的井都枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "石油资源总有一天会枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多矿山的资源已经枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水枯竭后，鱼都死了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下水用得太多，水源会枯竭。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市的煤炭快要枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的天然气还没有枯竭，还能用很多年。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林被砍光后，小溪也枯竭了。", "target_word": "枯竭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枯竭了", "label": "体标"}, {"form": "枯竭过", "label": "体标"}], "register": "中性", "sense_fingerprint": "水源断流或资源用尽", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "枯竭", "is_correct": true, "explanation": "正确：“枯竭”指水源断流，与前文的“土壤退化”“断崖式下跌”构成负面并列。"}, {"text": "充沛", "is_correct": false, "explanation": "语义：“水源充沛”与前文的“土壤退化”和“断崖式下跌”的负面趋势相反，句意矛盾。"}, {"text": "回升", "is_correct": false, "explanation": "语义：“回升”是好转，无法与“土壤退化”“断崖式下跌”并列成同一类负面现象。"}, {"text": "增殖", "is_correct": false, "explanation": "搭配：“增殖”多用于生物或细胞，不说“水源增殖”。"}], "explanations": {"枯竭": "正确：“枯竭”指水源断流，与前文的“土壤退化”“断崖式下跌”构成负面并列。", "充沛": "语义：“水源充沛”与前文的“土壤退化”和“断崖式下跌”的负面趋势相反，句意矛盾。", "回升": "语义：“回升”是好转，无法与“土壤退化”“断崖式下跌”并列成同一类负面现象。", "增殖": "搭配：“增殖”多用于生物或细胞，不说“水源增殖”。"}, "sentence_index": 0, "correct_answer": "枯竭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这款饮料已经枯竭了。", "explanation": "这里应该用〈售罄〉。枯竭指水源或自然资源用尽，饮料卖完应说售罄。"}, {"text": "这种动物已经枯竭了。", "explanation": "这里应该用〈灭绝〉。枯竭多用于水源、矿产等资源，物种消失应说灭绝。"}, {"text": "这盆花因为缺水已经枯竭了。", "explanation": "这里应该用〈枯萎〉。枯竭指水源或资源用尽，植物失水凋谢应说枯萎。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "枯竭", "is_correct": true, "explanation": "正确：“用得太多”的结果是水源“枯竭”，与句中的因果关系一致。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“用得太多”之后水源“增加”，因果关系说不通。"}, {"text": "恢复", "is_correct": false, "explanation": "语义：“用得太多”之后水源不会“恢复”，恢复需要先有损失且停止消耗，句中没有这样的条件。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”多用于果实、精神等，不说“水源饱满”。"}], "explanations": {"枯竭": "正确：“用得太多”的结果是水源“枯竭”，与句中的因果关系一致。", "增加": "语义：“用得太多”之后水源“增加”，因果关系说不通。", "恢复": "语义：“用得太多”之后水源不会“恢复”，恢复需要先有损失且停止消耗，句中没有这样的条件。", "饱满": "搭配：“饱满”多用于果实、精神等，不说“水源饱满”。"}, "sentence_index": 6, "correct_answer": "枯竭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这堆火已经枯竭了。", "explanation": "这里应该用〈熄灭〉。枯竭指水源或资源用尽，火焰熄灭应说熄灭。"}, {"text": "这块冰已经枯竭了。", "explanation": "这里应该用〈融化〉。枯竭不用于固体受热变成液体，冰化开应说融化。"}, {"text": "这片雾已经枯竭了。", "explanation": "这里应该用〈散去〉。枯竭指水源或资源用尽，雾气消散应说散去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片湖的水已经被枯竭了。", "corrected_sentence": "这片湖的水已经枯竭了。", "error_description": "错误在于多加了“被”。“枯竭”是不及物动词，不能构成被动句，应说“湖水已经枯竭了”，不说“被枯竭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13517, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这口井的水慢慢枯竭着了。", "corrected_sentence": "这口井的水慢慢枯竭了。", "error_description": "体标错误：“着”和“了”不能同时用在“枯竭”上，表示动作完成只用“了”，应说“慢慢枯竭了”，不说“枯竭着了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
