INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "陡峭的山崖；也比喻急剧下降或突然中断，如“断崖式下跌”。", "primary_collocate": null, "pronunciation": "duàn yá", "ipa": "tuan˥˩ ja˧˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "断崖", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "前面有一处断崖，我们不能再走了。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山路的尽头是一道很高的断崖。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在断崖边，不敢往下看。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "股价像断崖一样往下掉。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车差点开下断崖。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "断崖下面是一条深深的河。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小心，那边的断崖很危险。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨过后，断崖上的石头掉下来了。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的断崖上有很多鸟窝。", "target_word": "断崖", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一处断崖", "label": "量词"}, {"form": "断崖式", "label": "复合"}, {"form": "斷崖", "label": "繁体"}], "register": "中性", "sense_fingerprint": "陡峭山崖，比喻急剧下降", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断崖", "is_correct": true, "explanation": "正确：“断崖式下跌”指急剧下降，与句中的负面趋势相合。"}, {"text": "缓坡", "is_correct": false, "explanation": "语义：“缓坡”说坡度平缓，与“急剧下跌”的语义相反。"}, {"text": "平原", "is_correct": false, "explanation": "语义：“平原”说地势平坦，不能用来形容急剧下降。"}, {"text": "草坪", "is_correct": false, "explanation": "搭配：“草坪式”没有“下跌”的常用说法，应说“断崖式下跌”。"}], "explanations": {"断崖": "正确：“断崖式下跌”指急剧下降，与句中的负面趋势相合。", "缓坡": "语义：“缓坡”说坡度平缓，与“急剧下跌”的语义相反。", "平原": "语义：“平原”说地势平坦，不能用来形容急剧下降。", "草坪": "搭配：“草坪式”没有“下跌”的常用说法，应说“断崖式下跌”。"}, "sentence_index": 0, "correct_answer": "断崖"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在断崖勒马，及时改正了错误。", "explanation": "这里应该用〈悬崖〉。“悬崖勒马”是固定说法，“断崖”不能用于此固定搭配。"}, {"text": "地震后，墙上裂开了一道断崖。", "explanation": "这里应该用〈裂缝〉。断崖是陡峭的山崖，墙上裂开的缝要说裂缝。"}, {"text": "这里是一片断崖，汽车可以开得很快。", "explanation": "这里应该用〈平地〉。断崖又高又陡，汽车能快开的平坦地方要说平地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断崖", "is_correct": true, "explanation": "正确：“断崖下面是一条深深的河”，断崖位于河的上方，空间关系成立。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不会位于一条深河之上，句意不通。"}, {"text": "台灯", "is_correct": false, "explanation": "语义：台灯是室内器具，不能位于一条深河的上方。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶很小，下面不可能是一条深深的河，句意不通。"}], "explanations": {"断崖": "正确：“断崖下面是一条深深的河”，断崖位于河的上方，空间关系成立。", "书包": "语义：书包不会位于一条深河之上，句意不通。", "台灯": "语义：台灯是室内器具，不能位于一条深河的上方。", "树叶": "语义：树叶很小，下面不可能是一条深深的河，句意不通。"}, "sentence_index": 6, "correct_answer": "断崖"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "河水在断崖里奔腾，声音震耳。", "explanation": "这里应该用〈峡谷〉。断崖指陡峭的崖壁本身，不是能容纳河水奔腾的空间；河水奔腾的谷地要说峡谷。"}, {"text": "这场竞争让他陷入断崖，难以翻身。", "explanation": "这里应该用〈深渊〉。断崖是陡峭的山崖，比喻困境时不能说“陷入断崖”，要说“陷入深渊”。"}, {"text": "断崖从山顶倾泻而下，像一道白练。", "explanation": "这里应该用〈瀑布〉。断崖是静止的山崖，不会倾泻；水从高处流下形成白练要说瀑布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "前方那只断崖又高又陡。", "corrected_sentence": "前方那道断崖又高又陡。", "error_description": "量词错误：断崖是一道山崖，量词应用“道”，说“那道断崖”；“只”多用于动物或成对物品中的一个，不用于断崖。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13518, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们断崖边停下来休息。", "corrected_sentence": "我们在断崖边停下来休息。", "error_description": "“在”漏掉：表示处所要用“在”引出，应说“在断崖边停下”，不能直接说“断崖边停下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上涨", "is_correct": true, "explanation": "正确。“上涨”与“下跌”相反，指价格从低往高变动。"}, {"text": "保持", "is_correct": false, "explanation": "“保持”指维持原状，不表示与价格下跌方向相反的变动。"}, {"text": "出现", "is_correct": false, "explanation": "“出现”指新事物显现，与价格下跌没有反义关系。"}, {"text": "参加", "is_correct": false, "explanation": "“参加”指加入某项活动，与价格变动无关。"}], "correct_answer": "上涨", "explanations": {"上涨": "正确。“上涨”与“下跌”相反，指价格从低往高变动。", "保持": "“保持”指维持原状，不表示与价格下跌方向相反的变动。", "出现": "“出现”指新事物显现，与价格下跌没有反义关系。", "参加": "“参加”指加入某项活动，与价格变动无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上涨", "is_correct": true, "explanation": "正确。“上涨”与“下跌”相反，指价格从低往高变动。"}, {"text": "继续", "is_correct": false, "explanation": "“继续”指接着进行下去，与价格下跌没有反义关系。"}, {"text": "诞生", "is_correct": false, "explanation": "“诞生”指事物开始出现，与价格下跌没有反义关系。"}, {"text": "入睡", "is_correct": false, "explanation": "“入睡”指进入睡眠状态，与价格变动无关。"}], "correct_answer": "上涨", "explanations": {"上涨": "正确。“上涨”与“下跌”相反，指价格从低往高变动。", "继续": "“继续”指接着进行下去，与价格下跌没有反义关系。", "诞生": "“诞生”指事物开始出现，与价格下跌没有反义关系。", "入睡": "“入睡”指进入睡眠状态，与价格变动无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指价格、水平等从高处向低处变动。", "primary_collocate": null, "pronunciation": "xià diē", "ipa": "ɕja˥˩ tje˥", "syllable_count": 2, "sentences": [{"text": "其核心驱动力并非来自上级指令，而是源于一种日益觉醒的生态自觉——人们逐渐意识到，每一片消失的林地都直接关联着土壤退化、水源枯竭与生物多样性的断崖式下跌。", "target_word": "下跌", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今天苹果的价格下跌了。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "股票市场连续三天下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气变冷，菜价突然下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "房价下跌，很多人想买房。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个月牛肉的价格明显下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "去年手机的销量大幅下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司的股价下跌了百分之十。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油价下跌过一次，后来又涨上去了。", "target_word": "下跌", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气好，水果的价格一直在下跌。", "target_word": "下跌", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "下跌了", "label": "体标"}, {"form": "下跌过", "label": "体标"}], "register": "中性", "sense_fingerprint": "下跌|价格、水平等从高处向低处变动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "下跌", "is_correct": true, "explanation": "正确。“断崖式下跌”指急剧下降，与前文“消失”“退化”“枯竭”的语境一致。"}, {"text": "上升", "is_correct": false, "explanation": "语义：“上升”是向上移动，与前文“消失”“退化”“枯竭”所描述的减少趋势相反。"}, {"text": "攀升", "is_correct": false, "explanation": "语义：“攀升”指向高处攀登，与“断崖”的向下意象和前文的损失语境相反。"}, {"text": "高涨", "is_correct": false, "explanation": "搭配：“高涨”多用于情绪、热情或物价，不用于生物多样性等数量的急剧变化。"}], "explanations": {"下跌": "正确。“断崖式下跌”指急剧下降，与前文“消失”“退化”“枯竭”的语境一致。", "上升": "语义：“上升”是向上移动，与前文“消失”“退化”“枯竭”所描述的减少趋势相反。", "攀升": "语义：“攀升”指向高处攀登，与“断崖”的向下意象和前文的损失语境相反。", "高涨": "搭配：“高涨”多用于情绪、热情或物价，不用于生物多样性等数量的急剧变化。"}, "sentence_index": 0, "correct_answer": "下跌"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个月我的体重下跌了三公斤。", "explanation": "这里应该用〈下降〉。下跌多用于价格、股价，体重这类数量的减少要用“下降”。"}, {"text": "这块地的面积下跌了一半。", "explanation": "这里应该用〈缩小〉。下跌用于价格、股价、水平等数值，土地面积的减少要说“缩小”。"}, {"text": "这次改革后，农民的负担下跌了很多。", "explanation": "这里应该用〈减轻〉。下跌用于价格、股价、水平等数值的降低，负担的减轻要用“减轻”，不能说下跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "下跌", "is_correct": true, "explanation": "正确。“大幅下跌”表示销量急剧减少，符合句中的语境。"}, {"text": "断裂", "is_correct": false, "explanation": "搭配：“断裂”用于绳索、骨骼等实体，不说销量大幅断裂。"}, {"text": "攀登", "is_correct": false, "explanation": "语义：“攀登”指向高处爬，与销量的变化无关。"}, {"text": "熄灭", "is_correct": false, "explanation": "语义：“熄灭”指火或光灭掉，不能用于描述销量的变化。"}], "explanations": {"下跌": "正确。“大幅下跌”表示销量急剧减少，符合句中的语境。", "断裂": "搭配：“断裂”用于绳索、骨骼等实体，不说销量大幅断裂。", "攀登": "语义：“攀登”指向高处爬，与销量的变化无关。", "熄灭": "语义：“熄灭”指火或光灭掉，不能用于描述销量的变化。"}, "sentence_index": 6, "correct_answer": "下跌"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个人的脾气下跌了很多，大家都很惊讶。", "explanation": "这里应该用〈缓和〉。下跌只用于价格、水平等数值的降低，性格、脾气的变化要说“缓和”。"}, {"text": "这篇文章的字数下跌了一半。", "explanation": "这里应该用〈减少〉。下跌用于价格、股价、水平等数值的降低，字数的减少要用“减少”，不能说下跌。"}, {"text": "他听到这件事以后，心情突然下跌。", "explanation": "这里应该用〈低落〉。下跌用于价格、数值，情绪的消沉要说“低落”，不说下跌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个星期鸡蛋的价格下跌地很厉害。", "corrected_sentence": "这个星期鸡蛋的价格下跌得很厉害。", "error_description": "补语标记错误：“下跌”后带程度补语，要用结构助词“得”，不能用“地”。“地”用于动词前作状语，如“慢慢地下跌”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13519, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月物价被下跌了不少。", "corrected_sentence": "这个月物价下跌了不少。", "error_description": "被字句错误：“下跌”是不及物动词，不能和“被”构成被动句，应去掉“被”，说“物价下跌了不少”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
