INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指自愿进行社会公共利益服务而不获取任何报酬的人。", "primary_collocate": null, "pronunciation": "zhì yuàn zhě", "ipa": "ʈʂɻ̩⁵¹ ɥɛn⁵¹ ʈʂɤ²¹⁴", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "志愿者", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这位志愿者每个周末都免费去养老院帮忙。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校招募了二十名志愿者，在运动会上帮忙。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者给社区里的老人免费送饭。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，志愿者帮外国客人带路。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想当一名志愿者，去帮助山区的孩子。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "志愿者们穿着红色的衣服站在门口。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做过三年志愿者，很有经验。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的志愿者每天帮病人挂号。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想做志愿者的人请先在网上报名。", "target_word": "志愿者", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "名", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "志愿者们", "label": "复数"}], "register": "中性", "sense_fingerprint": "不为报酬、自愿参加公益服务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "志愿者", "is_correct": true, "explanation": "志愿者：自愿参加服务的人，符合全句植树、巡护、监测的行动主体。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客不会长期轮值巡护林带、记录树苗，与全句的志愿行动不符。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人无法植树、建立监测站，与句中的行动不符。"}, {"text": "宝宝", "is_correct": false, "explanation": "语域：“宝宝们”口语亲昵，与书面的叙述语体不协调。"}], "explanations": {"志愿者": "志愿者：自愿参加服务的人，符合全句植树、巡护、监测的行动主体。", "游客": "语义：游客不会长期轮值巡护林带、记录树苗，与全句的志愿行动不符。", "病人": "语义：病人无法植树、建立监测站，与句中的行动不符。", "宝宝": "语域：“宝宝们”口语亲昵，与书面的叙述语体不协调。"}, "sentence_index": 0, "correct_answer": "志愿者"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的志愿者每月领取工资。", "explanation": "这里应该用〈员工〉。志愿者不取报酬，每月领工资的人要用员工。"}, {"text": "我家请了一个志愿者，每月付工资，负责做饭。", "explanation": "这里应该用〈保姆〉。志愿者不取报酬，有偿雇来做饭的人要用保姆。"}, {"text": "比赛中，志愿者吹哨判罚了犯规的球员。", "explanation": "这里应该用〈裁判〉。志愿者只提供帮助服务，负责判罚的人要说裁判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "志愿者", "is_correct": true, "explanation": "志愿者：穿着统一服装站在门口的人，与句意相符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的物质，不能穿衣服站在门口，句意矛盾。"}, {"text": "门柱", "is_correct": false, "explanation": "语义：门柱是固定的立柱，不能穿衣服站在门口。"}, {"text": "树木", "is_correct": false, "explanation": "语义：树木不会穿衣服站在门口，与句意矛盾。"}], "explanations": {"志愿者": "志愿者：穿着统一服装站在门口的人，与句意相符。", "空气": "语义：空气是无形的物质，不能穿衣服站在门口，句意矛盾。", "门柱": "语义：门柱是固定的立柱，不能穿衣服站在门口。", "树木": "语义：树木不会穿衣服站在门口，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "志愿者"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他作为一名志愿者，必须服役两年。", "explanation": "这里应该用〈义务兵〉。志愿者是自愿参加的，没有强制性；必须服役的人要用义务兵。"}, {"text": "这套房子的志愿者每月向房客收租。", "explanation": "这里应该用〈房东〉。志愿者不以营利为目的，不向他人收费；收租的人要用房东。"}, {"text": "志愿者被迫在田里干活。", "explanation": "这里应该用〈奴隶〉。被迫劳动的人要用奴隶，志愿者是自愿参加的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年在医院当了一条志愿者。", "corrected_sentence": "他去年在医院当了一名志愿者。", "error_description": "量词错误：指人的“志愿者”应用“名”或“位”，“条”用于细长的事物，不能用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13520, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一名志愿者们。", "corrected_sentence": "他是一名志愿者。", "error_description": "“们”只用于复数，前面有“一名”这样的数量词时不能再加“们”，应说“一名志愿者”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
