INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容某件事或某个状态只在一定时期出现，不是全年或一直都有。", "primary_collocate": null, "pronunciation": "jì jié xìng", "ipa": "tɕi˥˩ tɕje˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "季节性", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这份季节性工作只在夏天有。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "草莓是季节性水果，春天才有。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在海边找了一份季节性的工作。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种病有季节性，多在冬天出现。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "旅游业的季节性很强，夏天人多。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "季节性的花只开一两个月。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农民做的是季节性的活儿，冬天没事做。", "target_word": "季节性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖季节性的菜，每个月都不一样。", "target_word": "季节性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "季节性的雨水集中在七八月。", "target_word": "季节性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "季節性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只在某个季节或时期出现的，非全年的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fb8b2f-b472-4aa2-8a65-2e4c070b5208') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "季节性", "is_correct": true, "explanation": "正确。“季节性任务”指只在特定时期进行的任务，与后文“持续性”的对照相合。"}, {"text": "持续性", "is_correct": false, "explanation": "语义：“持续性任务”与后文的“持续性的本地行动”相矛盾，不能与前文的否定构成对照。"}, {"text": "随机性", "is_correct": false, "explanation": "语义：“随机性”指无规律、偶然发生，与句中有计划的巡护、轮值不符。"}, {"text": "夜间性", "is_correct": false, "explanation": "搭配：“夜间性”指发生在夜里，植树并非夜间活动，不说夜间性任务。"}], "explanations": {"季节性": "正确。“季节性任务”指只在特定时期进行的任务，与后文“持续性”的对照相合。", "持续性": "语义：“持续性任务”与后文的“持续性的本地行动”相矛盾，不能与前文的否定构成对照。", "随机性": "语义：“随机性”指无规律、偶然发生，与句中有计划的巡护、轮值不符。", "夜间性": "搭配：“夜间性”指发生在夜里，植树并非夜间活动，不说夜间性任务。"}, "sentence_index": 0, "correct_answer": "季节性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这颗彗星是季节性出现的，大约每七十六年一次。", "explanation": "这里应该用〈周期性〉。季节性指按一年中的季节出现，七十六年一次的现象要说“周期性”。"}, {"text": "这场洪水是季节性的，几十年才遇到一次。", "explanation": "这里应该用〈偶发〉。季节性指按季节反复出现，几十年才一次的现象要说“偶发”。"}, {"text": "这次地震是季节性的，只发生过一次。", "explanation": "这里应该用〈突发〉。季节性指按一定时期反复出现，只发生一次的地震要说“突发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "季节性", "is_correct": true, "explanation": "正确。“季节性的花”指只在一定时期开放的花，与“只开一两个月”相合。"}, {"text": "永久性", "is_correct": false, "explanation": "语义：“永久性”指长久不变，与“只开一两个月”的时限相矛盾。"}, {"text": "常年性", "is_correct": false, "explanation": "语义：“常年性”指全年都有，与“只开一两个月”相矛盾。"}, {"text": "长期性", "is_correct": false, "explanation": "搭配：“长期性”多用于计划、工作，不用来形容花的开放时间。"}], "explanations": {"季节性": "正确。“季节性的花”指只在一定时期开放的花，与“只开一两个月”相合。", "永久性": "语义：“永久性”指长久不变，与“只开一两个月”的时限相矛盾。", "常年性": "语义：“常年性”指全年都有，与“只开一两个月”相矛盾。", "长期性": "搭配：“长期性”多用于计划、工作，不用来形容花的开放时间。"}, "sentence_index": 6, "correct_answer": "季节性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的服务是季节性的，全年都在。", "explanation": "这里应该用〈持续性〉。季节性指只在一定时期出现，全年都在的服务要说“持续性”。"}, {"text": "他每天的学习时间是季节性的。", "explanation": "这里应该用〈固定〉。季节性指只在一定时期出现，每天都固定的学习时间要说“固定”。"}, {"text": "这个学校的课程每天都一样，是季节性安排的。", "explanation": "这里应该用〈固定〉。“季节性”指只在一定时期出现，每天都一样的课程要说“固定”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店季节性强很，冬天几乎不开门。", "corrected_sentence": "这家店季节性很强，冬天几乎不开门。", "error_description": "语序错误：“很”修饰形容词，应放在“强”前，说“季节性很强”，不能说“季节性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13521, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种水果是季节性，只在秋天才有。", "corrected_sentence": "这种水果是季节性的，只在秋天才有。", "error_description": "缺少“的”：“季节性”作谓语说明事物性质时要用“是……的”，应说“是季节性的”，不能说“是季节性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0690ee71-f26d-49ae-bc24-f1f45dfe2d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
