INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13523, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "存活率是指在特定条件下，某个群体中存活个体所占的比例。", "primary_collocate": null, "pronunciation": "cún huó lǜ", "ipa": "tsʰu̯ən˧˥ xu̯ɔ˧˥ ly˥˩", "syllable_count": 3, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "存活率", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年这片树林的树苗存活率很高。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要提高鱼苗存活率，水一定要干净。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花在冬天的存活率只有三成。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们记录小树的存活率。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为天气太热，种子的存活率下降了。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，这种病人的五年存活率不低。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民用新办法提高了苗木存活率。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们比较了两块地的存活率。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟的存活率和食物多少有关系。", "target_word": "存活率", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "特定条件下群体中存活个体所占的比例", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13523, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "存活率", "is_correct": true, "explanation": "“存活率”指群体中活下来的比例，「记录树苗存活率」语义完整，符合句中的记录和树苗语境。"}, {"text": "失业率", "is_correct": false, "explanation": "语义：失业率说的是人的就业状况，树苗不会失业，句中“树苗失业率”无法成立。"}, {"text": "识字率", "is_correct": false, "explanation": "语义：识字率指人会认字的比例，与树苗的生长记录无关。"}, {"text": "出勤率", "is_correct": false, "explanation": "搭配：出勤率用于人员上班或上课，不能用来记录树苗。"}], "explanations": {"存活率": "“存活率”指群体中活下来的比例，「记录树苗存活率」语义完整，符合句中的记录和树苗语境。", "失业率": "语义：失业率说的是人的就业状况，树苗不会失业，句中“树苗失业率”无法成立。", "识字率": "语义：识字率指人会认字的比例，与树苗的生长记录无关。", "出勤率": "搭配：出勤率用于人员上班或上课，不能用来记录树苗。"}, "sentence_index": 0, "correct_answer": "存活率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的存活率是八成。", "explanation": "存活率指群体中活下来的比例，考试不存在“存活”的问题。这里应该用〈及格率〉，表示通过考试的人所占的比例。"}, {"text": "这首歌的存活率很高。", "explanation": "存活率只用于有生命的个体所组成的群体，歌曲不能“存活”。这里应该用〈流传〉来说明歌曲传播得广。"}, {"text": "这一批教材的存活率很高。", "explanation": "教材是无生命的物品，不能讲存活率。这里应该用〈使用率〉来说明教材被用得多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13523, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "存活率", "is_correct": true, "explanation": "“存活率”说的是一段时间内活下来的比例，与“五年”和“病人”的语境相符，「五年存活率不低」语义通顺。"}, {"text": "入学率", "is_correct": false, "explanation": "语义：入学率说的是入学人数的比例，与病人五年间的情况无关。"}, {"text": "就业率", "is_correct": false, "explanation": "搭配：就业率用于劳动人口，不能用来说病人的五年情况。"}, {"text": "出生率", "is_correct": false, "explanation": "语义：出生率指新生儿的比例，与病人的五年生存情况不相关。"}], "explanations": {"存活率": "“存活率”说的是一段时间内活下来的比例，与“五年”和“病人”的语境相符，「五年存活率不低」语义通顺。", "入学率": "语义：入学率说的是入学人数的比例，与病人五年间的情况无关。", "就业率": "搭配：就业率用于劳动人口，不能用来说病人的五年情况。", "出生率": "语义：出生率指新生儿的比例，与病人的五年生存情况不相关。"}, "sentence_index": 6, "correct_answer": "存活率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次投资的存活率很高。", "explanation": "存活率说的是群体中活下来的比例，投资不存在存活。这里应该用〈回报率〉，表示投资带来的收益。"}, {"text": "这个活动的存活率比去年下降了。", "explanation": "活动不是有生命的个体，不能说存活。这里应该用〈参与率〉，表示参加的人所占的比例。"}, {"text": "这款手机的存活率比去年高了。", "explanation": "“存活率”只用于有生命的个体所组成的群体，手机不是生命体，不能说存活。这里应该用〈销量〉来说明卖得多。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13523, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批树苗的存活率很多。", "corrected_sentence": "这批树苗的存活率很高。", "error_description": "搭配错误：「存活率」是比例，要用「高」或「低」来形容，不能说「很多」；应说「存活率很高」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13523, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "换了干净的水，鱼苗的存活率变长了。", "corrected_sentence": "换了干净的水，鱼苗的存活率变高了。", "error_description": "搭配错误：「存活率」是比例，只能说变高或变低，不能说「变长」；应说「存活率变高了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
