INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13526, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "成排的树木，多用于防风沙、水土保持等。", "primary_collocate": null, "pronunciation": "lín dài", "ipa": "lin˧˥ tai˥˩", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "林带", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这条林带可以挡住沙子。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村北有一条长长的林带。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林带能防风，也能保护农田。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们在公路旁种了一条林带。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风很大，但林带后面很安静。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在林带里捉迷藏。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片农田的外面有一条林带。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林带里的树都是去年种的。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了防沙，政府决定再建一条林带。", "target_word": "林带", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条林带", "label": "量词"}, {"form": "防护林带", "label": "复合"}], "register": "中性", "sense_fingerprint": "防风沙保持水土的成排树木", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cb894594-6404-49e9-b276-afb1f1d52d67') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13526, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "林带", "is_correct": true, "explanation": "正确答案：林带，指成排用于防风沙的树木。"}, {"text": "林地", "is_correct": false, "explanation": "dài 与 dì 韵母不同（ai 与 i），意思是林地，指树林覆盖的土地。"}, {"text": "连带", "is_correct": false, "explanation": "lín 与 lián 韵母不同（in 与 ian），意思是连带，指牵连、带动。"}, {"text": "蓝带", "is_correct": false, "explanation": "lín 与 lán 韵母不同（in 与 an），意思是蓝带，指蓝色的腰带。"}], "explanations": {"林带": "正确答案：林带，指成排用于防风沙的树木。", "林地": "dài 与 dì 韵母不同（ai 与 i），意思是林地，指树林覆盖的土地。", "连带": "lín 与 lián 韵母不同（in 与 ian），意思是连带，指牵连、带动。", "蓝带": "lín 与 lán 韵母不同（in 与 an），意思是蓝带，指蓝色的腰带。"}, "sentence_index": null, "correct_answer": "林带"}, "level_3": {"options": [{"text": "林带", "is_correct": true, "explanation": "林带：成排的树木，正是轮值巡护的对象，与全句相符。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪不能被轮值巡护，全句也没有海的语境。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：“巡护”用于守护的区域或设施，不说巡护课本。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞不是需要巡护的对象，与植树、树苗的语境不符。"}], "explanations": {"林带": "林带：成排的树木，正是轮值巡护的对象，与全句相符。", "海浪": "语义：海浪不能被轮值巡护，全句也没有海的语境。", "课本": "搭配：“巡护”用于守护的区域或设施，不说巡护课本。", "雨伞": "语义：雨伞不是需要巡护的对象，与植树、树苗的语境不符。"}, "sentence_index": 0, "correct_answer": "林带"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他腰上系着一条林带。", "explanation": "这里应该用〈皮带〉。林带是成排的树，不是布带子；系在腰上的带子要用皮带。"}, {"text": "她把一条林带系在头发上。", "explanation": "这里应该用〈发带〉。林带是成排的树，不是布条；系在头发上的带子要用发带。"}, {"text": "我们在农田边上种了一座林带。", "explanation": "量词不当：林带可用〈条〉或〈片〉，“座”用于山、桥、楼等大体量的东西，不用于林带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13526, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林带", "is_correct": true, "explanation": "林带：可以让孩子躲藏的成排树木，与捉迷藏的语境相符。"}, {"text": "鱼缸", "is_correct": false, "explanation": "语义：鱼缸是养鱼的小容器，孩子们不能在里面捉迷藏。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是孩子们可以捉迷藏的场所，与林带的语境不符。"}, {"text": "手术室", "is_correct": false, "explanation": "语义：手术室是严禁喧闹的医疗场所，不能用来玩捉迷藏。"}], "explanations": {"林带": "林带：可以让孩子躲藏的成排树木，与捉迷藏的语境相符。", "鱼缸": "语义：鱼缸是养鱼的小容器，孩子们不能在里面捉迷藏。", "冰箱": "语义：冰箱是家用电器，不是孩子们可以捉迷藏的场所，与林带的语境不符。", "手术室": "语义：手术室是严禁喧闹的医疗场所，不能用来玩捉迷藏。"}, "sentence_index": 6, "correct_answer": "林带"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "操场中间是一大片林带，很平整。", "explanation": "这里应该用〈草坪〉。林带是成排的树木，平整的草地要用草坪。"}, {"text": "阳台上摆着几条林带。", "explanation": "这里应该用〈绿植〉。林带指成排的树，不能摆在阳台上；盆里的植物要用绿植。"}, {"text": "她的裙子上缠着一圈林带，很漂亮。", "explanation": "这里应该用〈彩带〉。林带是成排的树，不是布条；缠在裙子上做装饰的带子要用彩带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13526, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "农民在河边种了一个林带，用来防风。", "corrected_sentence": "农民在河边种了一条林带，用来防风。", "error_description": "量词错误：林带呈带状，应说“一条林带”，“个”不适用于林带。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13526, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "去年他们在农田边种了一条林带们。", "corrected_sentence": "去年他们在农田边种了一条林带。", "error_description": "词缀错误：“们”只用于指人的名词，林带是树木，不能加“们”，应说“一条林带”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c6ad7f2-8b6d-4a9e-b41e-a6d764b2bc03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
