INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13532, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "地下水位指地下水面相对于地面的高度，通常用深度来表示。", "primary_collocate": null, "pronunciation": "dì xià shuǐ wèi", "ipa": "ti˥˩ ɕja˥˩ ʂweɪ˨˩ weɪ˥˩", "syllable_count": 4, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "地下水位", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "连续下雨后，这里的地下水位升高了。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为抽了太多的水，这里的地下水位每年都下降。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在田边打了一口井，用来测量地下水位。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海边的地下水位很高，挖一米就出水了。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天很干，河边的地下水位降低了不少。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盖高楼以前，工程师要先检查地下水位。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下水位太高，地下室里总是很潮湿。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "植树可以保护土地，也能让地下水位慢慢回升。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，今年雨水多，地下水位比去年高。", "target_word": "地下水位", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "地下水位·名词·地下水面距地面的高度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13532, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地下水位", "is_correct": true, "explanation": "正确：句中要追踪的是地下水面的高度，即地下水位。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情无法用简易设备测量或追踪，与句中的设备不搭。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“追踪”后面接的应是可以监测的自然变化，“学费”是金钱数额，不能用设备追踪。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是日期或活动，不是可以用设备持续追踪的数值。"}], "explanations": {"地下水位": "正确：句中要追踪的是地下水面的高度，即地下水位。", "心情": "语义：心情无法用简易设备测量或追踪，与句中的设备不搭。", "学费": "搭配：“追踪”后面接的应是可以监测的自然变化，“学费”是金钱数额，不能用设备追踪。", "节日": "语义：节日是日期或活动，不是可以用设备持续追踪的数值。"}, "sentence_index": 0, "correct_answer": "地下水位"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村民每天都用水泵抽取地下水位。", "explanation": "这里应该用〈地下水〉。地下水位是水面的高度，不能被抽取，被抽取的是水本身。"}, {"text": "这口井是村里唯一的地下水位。", "explanation": "这里应该用〈地下水源〉。这口井是供水的来源，水位只是水面的高度，不能充当水源。"}, {"text": "这块地的地下水位很干燥。", "explanation": "这里应该用〈土壤〉。水位是水面的高度，不会干燥或潮湿，说土地干燥应说土壤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13532, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "地下水位", "is_correct": true, "explanation": "正确：盖楼前工程师检查的是地下水面的高度。"}, {"text": "房价", "is_correct": false, "explanation": "语义：工程师检查的是地下的水文条件，房价与此无关，句子不成立。"}, {"text": "考试成绩", "is_correct": false, "explanation": "搭配：“检查”后接的应是可以测量的地下条件，工程师不会在盖楼前检查考试成绩。"}, {"text": "收视率", "is_correct": false, "explanation": "语义：收视率是电视观众的统计数字，与盖楼前的地质检查无关。"}], "explanations": {"地下水位": "正确：盖楼前工程师检查的是地下水面的高度。", "房价": "语义：工程师检查的是地下的水文条件，房价与此无关，句子不成立。", "考试成绩": "搭配：“检查”后接的应是可以测量的地下条件，工程师不会在盖楼前检查考试成绩。", "收视率": "语义：收视率是电视观众的统计数字，与盖楼前的地质检查无关。"}, "sentence_index": 6, "correct_answer": "地下水位"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "杯子里的地下水位降下来了。", "explanation": "这里应该用〈水位〉。杯子里的水在地面以上，不在地下，不能说地下水位。"}, {"text": "湖泊和河流都属于地下水位。", "explanation": "这里应该用〈地表水〉。地下水位是一个高度数值，不是一类水体；湖泊和河流属于地表水。"}, {"text": "工厂的废水让这条河的地下水位变脏了。", "explanation": "这里应该用〈水质〉。水位是高度，不会变脏，说水变脏应说水质变差。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13532, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨季过后，村里的地下水位明显长高了。", "corrected_sentence": "雨季过后，村里的地下水位明显升高了。", "error_description": "搭配错误：「长高」用于人、植物等生长变高；「地下水位」是水面的高度，应与「升高」或「上升」搭配，说成「地下水位明显升高了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13532, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今年夏天雨水少，地下水位的比去年低。", "corrected_sentence": "今年夏天雨水少，地下水位比去年低。", "error_description": "错误：主语“地下水位”后多加了“的”；正确：“地下水位比去年低”。比字句的主语后面不加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
