INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13533, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鸟类是恒温、卵生、体表被覆羽毛、前肢特化为翼、后肢适于行走的脊椎动物。", "primary_collocate": null, "pronunciation": "niǎo lèi", "ipa": "njɑʊ˨˩˦ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这些研究揭示了一个令人警觉的事实：当某一区域的授粉昆虫丰度下降时，不仅植物结实率显著降低，连锁效应还会波及依赖这些植物生存的鸟类、哺乳动物及其他无脊椎动物，从而引发生态系统服务功能的级联式崩溃。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "鸟类的身体上有羽毛。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大多数鸟类都会飞，但企鹅不会。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟类通过产卵繁殖后代。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家发现，鸟类的骨头很轻。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湿地保护区里有两百多种鸟类。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟类的前肢变成了翅膀。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多鸟类每年秋天飞往南方过冬。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "恒温是鸟类的重要特征之一。", "target_word": "鸟类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "鳥類", "label": "繁体"}], "register": "书面", "sense_fingerprint": "鸟类：生物学上恒温卵生、有羽毛和翼的脊椎动物类群", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13533, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "鸟类", "is_correct": true, "explanation": "正确：“鸟类”指各种鸟，“鸟类迁徙轨迹”指鸟群迁徙的路线，与句意相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会迁徙，“石头迁徙轨迹”与句意不符。"}, {"text": "工厂", "is_correct": false, "explanation": "语义：工厂是固定的建筑，不存在迁徙的行为。"}, {"text": "台风", "is_correct": false, "explanation": "搭配：“迁徙”用于动物的季节性移动，台风的移动路径应说“路径”而不是“迁徙轨迹”。"}], "explanations": {"鸟类": "正确：“鸟类”指各种鸟，“鸟类迁徙轨迹”指鸟群迁徙的路线，与句意相符。", "石头": "语义：石头不会迁徙，“石头迁徙轨迹”与句意不符。", "工厂": "语义：工厂是固定的建筑，不存在迁徙的行为。", "台风": "搭配：“迁徙”用于动物的季节性移动，台风的移动路径应说“路径”而不是“迁徙轨迹”。"}, "sentence_index": 0, "correct_answer": "鸟类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "池塘边停着一只鸟类。", "explanation": "这里应该用〈鸟〉。“鸟类”指一大类动物，不能指某一只具体的鸟。"}, {"text": "今天的晚饭是红烧鸟类。", "explanation": "这里应该用〈鸡肉〉之类的具体肉名。“鸟类”是生物学上的动物类群，不能指做成菜的肉。"}, {"text": "这件羽绒服里装满了鸟类。", "explanation": "这里应该用〈羽毛〉或〈羽绒〉。“鸟类”指整个动物类群，不能指鸟身上的羽毛。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13533, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鸟类", "is_correct": true, "explanation": "正确：“鸟类”指各种鸟，符合湿地保护区里“两百多种”的语境。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不属于湿地保护区里的生物种类，“两百多种汽车”与语境不合。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是人造物，不会在湿地保护区里作为“两百多种”的统计对象出现。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：“玩意儿”是口语，语义又过于笼统，与句子的书面、科普语境不合。"}], "explanations": {"鸟类": "正确：“鸟类”指各种鸟，符合湿地保护区里“两百多种”的语境。", "汽车": "语义：汽车不属于湿地保护区里的生物种类，“两百多种汽车”与语境不合。", "家具": "语义：家具是人造物，不会在湿地保护区里作为“两百多种”的统计对象出现。", "玩意儿": "语域：“玩意儿”是口语，语义又过于笼统，与句子的书面、科普语境不合。"}, "sentence_index": 6, "correct_answer": "鸟类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家养的那只小鸟类每天早上都叫。", "explanation": "这里应该用〈鸟〉。“鸟类”是类别名称，不能指自己家养的某一只具体的鸟。"}, {"text": "妈妈去市场买了两斤鸟类。", "explanation": "这里应该用〈鸡肉〉之类的具体名称。“鸟类”是动物类群的名称，不能当作买卖的食品。"}, {"text": "他用鸟类做了一个漂亮的毽子。", "explanation": "这里应该用〈羽毛〉。“鸟类”指动物类群，不是可以拿来做东西的材料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13533, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些鸟类们在冬天会迁徙到南方。", "corrected_sentence": "这些鸟类在冬天会迁徙到南方。", "error_description": "错误：“鸟类”本身已表示一类动物，后面不能再加“们”，写成“鸟类们”。正确：“这些鸟类”。“这些”已表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13533, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只鸟类很少见。", "corrected_sentence": "这种鸟类很少见。", "error_description": "错误：“只”用于单个动物，“鸟类”是类别名称，应该用“种”，写成“这只鸟类”。正确：“这种鸟类”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指生物为了寻找更好的生活环境或食物，从一个地区转移到另一个地区的现象。", "primary_collocate": null, "pronunciation": "qiān xǐ", "ipa": "tɕʰjɛn˥ ɕi˨˩", "syllable_count": 2, "sentences": [{"text": "志愿者们不再将植树视为季节性任务，而是一种持续性的本地行动，他们记录树苗存活率，轮值巡护林带，甚至建立了民间监测站，用简易设备追踪地下水位与鸟类迁徙轨迹。", "target_word": "迁徙", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "每年秋天，大雁会向南迁徙。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，很多鸟儿从北方迁徙到南方。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "非洲的角马为了找水和草，每年都要长途迁徙。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鲸鱼迁徙的时候，会游几千公里。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气变冷了，燕子开始迁徙。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家用小仪器记录鸟儿迁徙的路线。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湿地是候鸟迁徙时休息的地方。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水干了，鱼群只好迁徙到别的地方。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蝴蝶每年都要迁徙几千公里，去温暖的地方过冬。", "target_word": "迁徙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "迁徙了", "label": "体标"}, {"form": "迁徙过", "label": "体标"}, {"form": "迁徙路线", "label": "复合"}, {"form": "遷徙", "label": "繁体"}], "register": "书面", "sense_fingerprint": "迁徙·动词·生物为觅食或换环境而转移到另一地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16383963-1406-40ee-9a87-a2a0f98c8c72') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "迁徙", "is_correct": true, "explanation": "正确：迁徙（qiān xǐ）指生物为觅食或避寒而转移到另一地区。"}, {"text": "谦虚", "is_correct": false, "explanation": "谦虚（qiān xū）与迁徙（qiān xǐ）第二个音节韵母不同（xū 与 xǐ），意思是谦逊、不自满。"}, {"text": "千禧", "is_correct": false, "explanation": "千禧（qiān xī）与迁徙（qiān xǐ）第一个音节相同，第二个音节声调不同（xī 与 xǐ），意思是新的千年。"}, {"text": "牵系", "is_correct": false, "explanation": "牵系（qiān xì）与迁徙（qiān xǐ）第一个音节相同，第二个音节声调不同（xì 与 xǐ），意思是牵挂、联系。"}], "explanations": {"迁徙": "正确：迁徙（qiān xǐ）指生物为觅食或避寒而转移到另一地区。", "谦虚": "谦虚（qiān xū）与迁徙（qiān xǐ）第二个音节韵母不同（xū 与 xǐ），意思是谦逊、不自满。", "千禧": "千禧（qiān xī）与迁徙（qiān xǐ）第一个音节相同，第二个音节声调不同（xī 与 xǐ），意思是新的千年。", "牵系": "牵系（qiān xì）与迁徙（qiān xǐ）第一个音节相同，第二个音节声调不同（xì 与 xǐ），意思是牵挂、联系。"}, "sentence_index": null, "correct_answer": "迁徙"}, "level_3": {"options": [{"text": "迁徙", "is_correct": true, "explanation": "正确：句中“鸟类……轨迹”指鸟类迁移的路线，应用迁徙。"}, {"text": "繁殖", "is_correct": false, "explanation": "语义：繁殖指生育后代，与句中追踪的移动路线无关。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“轨迹”指移动的路径，“喂养”是人对动物的照料，不能修饰轨迹。"}, {"text": "孵化", "is_correct": false, "explanation": "语义：孵化指卵变成幼体，与轨迹所指的移动含义不符。"}], "explanations": {"迁徙": "正确：句中“鸟类……轨迹”指鸟类迁移的路线，应用迁徙。", "繁殖": "语义：繁殖指生育后代，与句中追踪的移动路线无关。", "喂养": "搭配：“轨迹”指移动的路径，“喂养”是人对动物的照料，不能修饰轨迹。", "孵化": "语义：孵化指卵变成幼体，与轨迹所指的移动含义不符。"}, "sentence_index": 0, "correct_answer": "迁徙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这箱书昨天迁徙到了二楼。", "explanation": "这里应该用〈搬〉。迁徙指生物为觅食或避寒而成群转移，箱子里的书不是生物，应说搬到二楼。"}, {"text": "暑假我和同学迁徙到海南玩了一周。", "explanation": "这里应该用〈旅行〉。迁徙是动物为觅食或避寒而转移，人的短途出游不能说迁徙。"}, {"text": "这辆汽车昨天迁徙到了停车场。", "explanation": "这里应该用〈开〉。迁徙指生物为觅食或换环境而成群转移，汽车不是生物，应说开到了停车场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "迁徙", "is_correct": true, "explanation": "正确：句中记录的是鸟儿移动的路线，应用迁徙。"}, {"text": "产卵", "is_correct": false, "explanation": "语义：产卵是雌鸟生蛋，与记录的路线不相关。"}, {"text": "冬眠", "is_correct": false, "explanation": "语义：冬眠是静止不动地睡过冬天，不会形成路线。"}, {"text": "换毛", "is_correct": false, "explanation": "搭配：“路线”只能与移动相关的行为搭配，“换毛”不能形成路线。"}], "explanations": {"迁徙": "正确：句中记录的是鸟儿移动的路线，应用迁徙。", "产卵": "语义：产卵是雌鸟生蛋，与记录的路线不相关。", "冬眠": "语义：冬眠是静止不动地睡过冬天，不会形成路线。", "换毛": "搭配：“路线”只能与移动相关的行为搭配，“换毛”不能形成路线。"}, "sentence_index": 6, "correct_answer": "迁徙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "火车每天迁徙到南方。", "explanation": "这里应该用〈开往〉。迁徙指生物为生存而转移到别的地区，火车不是生物，它的行驶不能说迁徙。"}, {"text": "木头顺着河水迁徙到了下游。", "explanation": "这里应该用〈漂流〉。迁徙指生物为生存而转移，木头被水冲走应说漂流。"}, {"text": "云层迁徙到了山的另一边。", "explanation": "这里应该用〈飘〉。迁徙只用于生物，云层的移动应说飘过去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "冬天到了，很多大雁都被迁徙到南方去了。", "corrected_sentence": "冬天到了，很多大雁都迁徙到南方去了。", "error_description": "被字句错误：迁徙是大雁自己的行为，不能用「被」表示被动；应去掉「被」，说「都迁徙到南方去了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13534, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "秋天一到，燕子就迁徙了到南方。", "corrected_sentence": "秋天一到，燕子就迁徙到了南方。", "error_description": "错误：“迁徙了到南方”；正确：“迁徙到了南方”。“了”表示动作已完成，应放在结果补语“到”之后，不能放在“到”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f1e019d-d1e6-4d31-984e-2d2116845a07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
