INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13537, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指一种以实践、互动、交流为主的短期学习活动或小组，参与者共同完成某个任务或课题。", "primary_collocate": null, "pronunciation": "gōng zuò fāng", "ipa": "kʊŋ˥ tsuɔ˥˩ faŋ˥", "syllable_count": 3, "sentences": [{"text": "通过定期举办生态工作坊与跨村交流会，志愿服务成为社区建设的黏合剂。", "target_word": "工作坊", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "周末我报名参加了一个手工工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个工作坊只有三天。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作坊里的人一起做了一张海报。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆明天有写作工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在工作坊里，大家边做边聊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她给学生办了一场摄影工作坊。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次工作坊让我学会了做面包。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加工作坊的人要自己带电脑。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作坊结束时，每组都展示了作品。", "target_word": "工作坊", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "场", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "写作工作坊", "label": "复合"}], "register": "中性", "sense_fingerprint": "以实践互动为主的短期学习活动或小组", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115b89f7-bdbd-4625-a077-7b8981880a73') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13537, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作坊", "is_correct": true, "explanation": "正确：“工作坊”是以实践、互动为主的短期活动，可以“举办”。"}, {"text": "工作服", "is_correct": false, "explanation": "语义：“工作服”是衣物，不是活动，不能被举办。"}, {"text": "农药", "is_correct": false, "explanation": "语义：“农药”是化学制剂，不能被举办，也与“生态”的语境冲突。"}, {"text": "食堂", "is_correct": false, "explanation": "搭配：“举办”不与“食堂”搭配，食堂不是活动。"}], "explanations": {"工作坊": "正确：“工作坊”是以实践、互动为主的短期活动，可以“举办”。", "工作服": "语义：“工作服”是衣物，不是活动，不能被举办。", "农药": "语义：“农药”是化学制剂，不能被举办，也与“生态”的语境冲突。", "食堂": "搭配：“举办”不与“食堂”搭配，食堂不是活动。"}, "sentence_index": 0, "correct_answer": "工作坊"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家工厂的工作坊每天生产一千辆汽车。", "explanation": "这里应该用〈车间〉。“工作坊”是短期的学习交流活动，不是工厂里大规模生产的地方。"}, {"text": "我每天早上喝一杯工作坊。", "explanation": "这里应该用〈咖啡〉之类的饮料。“工作坊”是活动，不能喝。"}, {"text": "我把工作坊放进了书包。", "explanation": "这里应该用〈材料〉。“工作坊”是活动，不是可以装进书包的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13537, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作坊", "is_correct": true, "explanation": "正确：“办了一场摄影工作坊”中，“工作坊”与“办”搭配，表示组织的活动。"}, {"text": "讲义", "is_correct": false, "explanation": "语义：“讲义”是讲课用的材料，不是可以办的活动。"}, {"text": "相册", "is_correct": false, "explanation": "搭配：“办”不与“相册”搭配，相册是制作的，不是举办的。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是绘画材料，不能被办或举办。"}], "explanations": {"工作坊": "正确：“办了一场摄影工作坊”中，“工作坊”与“办”搭配，表示组织的活动。", "讲义": "语义：“讲义”是讲课用的材料，不是可以办的活动。", "相册": "搭配：“办”不与“相册”搭配，相册是制作的，不是举办的。", "颜料": "语义：“颜料”是绘画材料，不能被办或举办。"}, "sentence_index": 6, "correct_answer": "工作坊"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师每天在工作坊里给学生考试，考完就放学。", "explanation": "这里应该用〈考场〉。“工作坊”是以实践、互动为主的学习活动，不是考试的场所。"}, {"text": "我们今天吃了一个工作坊。", "explanation": "这里应该用〈面包〉之类可以吃的东西。“工作坊”是活动，不能吃。"}, {"text": "这个工作坊是我们班的班主任。", "explanation": "这里应该用〈老师〉之类指人的词。“工作坊”指活动，不能当作人来用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13537, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周都去一条陶艺工作坊。", "corrected_sentence": "我们每周都去一个陶艺工作坊。", "error_description": "错误在量词。“工作坊”应用量词“个”或“场”，不能用“条”，“条”多用于细长的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13537, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我下个月想参加了一个木工工作坊。", "corrected_sentence": "我下个月想参加一个木工工作坊。", "error_description": "错误在“了”。“想”表示打算，动作还没有发生，“参加”后不能加“了”。正确说法是“我下个月想参加一个木工工作坊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd95e60b8-a54b-4d98-91a0-30a25dd1f4b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
