INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13540, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "使两个物体粘合在一起的物质。", "primary_collocate": null, "pronunciation": "nián hé jì", "ipa": "njɛn˧˥ xɤ˧˥ tɕi˥˩", "syllable_count": 3, "sentences": [{"text": "为保证航空复合材料在高温下不脱层，技术人员选用了耐热性更强的黏合剂。", "target_word": "黏合剂", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "这种黏合剂干得很快，用它修好了杯子。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木工用黏合剂把两块木板粘在一起。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手上沾了黏合剂，要用热水洗干净。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶黏合剂不能放在太热的地方。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做模型时，他买了一管黏合剂。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用黏合剂把纸花贴到了墙上。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种黏合剂没有味道，小孩也能用。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黏合剂太少了，两块砖粘不牢。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用黏合剂把鞋底粘好。", "target_word": "黏合剂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "黏合劑", "label": "繁体"}, {"form": "粘合剂", "label": "异体写法"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "把两个物体粘在一起的胶状物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13540, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "黏合剂", "is_correct": true, "explanation": "正确：黏合剂指使物体粘合在一起的物质，与“耐热”“不脱层”的语境相符。"}, {"text": "公交车", "is_correct": false, "explanation": "语义：公交车是交通工具，不能让复合材料在高温下不脱层。"}, {"text": "红绿灯", "is_correct": false, "explanation": "语义：红绿灯用于指挥交通，与“耐热”“不脱层”的材料语境无关。"}, {"text": "破玩意儿", "is_correct": false, "explanation": "语域：口语色彩很重，与这句书面语的语域不一致。"}], "explanations": {"黏合剂": "正确：黏合剂指使物体粘合在一起的物质，与“耐热”“不脱层”的语境相符。", "公交车": "语义：公交车是交通工具，不能让复合材料在高温下不脱层。", "红绿灯": "语义：红绿灯用于指挥交通，与“耐热”“不脱层”的材料语境无关。", "破玩意儿": "语域：口语色彩很重，与这句书面语的语域不一致。"}, "sentence_index": 0, "correct_answer": "黏合剂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种黏合剂可以用来退烧。", "explanation": "这里应该用〈退烧药〉。黏合剂用于粘合物体，不能用来退烧。"}, {"text": "这种黏合剂可以去除油污。", "explanation": "这里应该用〈清洁剂〉。黏合剂的作用是粘合，去除油污要用清洁剂。"}, {"text": "门轴响了，我往上面加了点黏合剂。", "explanation": "这里应该用〈润滑剂〉。门轴发出响声时要加润滑剂减少摩擦，黏合剂是用来粘合的，不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13540, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "黏合剂", "is_correct": true, "explanation": "正确：黏合剂能把纸花粘在墙上，与“贴到了墙上”的语境相符。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料用于涂色，不能把纸花粘到墙上。"}, {"text": "毛线", "is_correct": false, "explanation": "搭配：“贴”需要粘合材料，毛线不能用来粘纸花。"}, {"text": "剪刀", "is_correct": false, "explanation": "语义：剪刀用于剪切，不能把纸花贴到墙上。"}], "explanations": {"黏合剂": "正确：黏合剂能把纸花粘在墙上，与“贴到了墙上”的语境相符。", "颜料": "语义：颜料用于涂色，不能把纸花粘到墙上。", "毛线": "搭配：“贴”需要粘合材料，毛线不能用来粘纸花。", "剪刀": "语义：剪刀用于剪切，不能把纸花贴到墙上。"}, "sentence_index": 6, "correct_answer": "黏合剂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种黏合剂可以让牛奶变甜。", "explanation": "这里应该用〈糖〉。黏合剂用于粘合，能让牛奶变甜的是〈糖〉。"}, {"text": "他把黏合剂当作调料放进汤里。", "explanation": "这里应该用〈盐〉。黏合剂用于粘合物体，不能当作调料，调味要用〈盐〉。"}, {"text": "晚上他用黏合剂给书架上色。", "explanation": "这里应该用〈油漆〉。黏合剂用于粘合，给书架上色要用〈油漆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13540, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我用一只黏合剂修好了椅子。", "corrected_sentence": "我用一管黏合剂修好了椅子。", "error_description": "量词错误：黏合剂装在管子里，应说“一管黏合剂”。“只”用于动物或成对的东西中的一个，不能用来数黏合剂。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13540, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了两黏合剂。", "corrected_sentence": "我买了两管黏合剂。", "error_description": "量词缺失：数量词“两”后面要加量词，黏合剂装在容器里，应说“两管黏合剂”，不能说“两黏合剂”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
