INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13542, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "指体力劳动或工作，通常指较辛苦的体力活动。", "primary_collocate": null, "pronunciation": "láo zuò", "ipa": "laʊ˧˥ tswɔ˥˩", "syllable_count": 2, "sentences": [{"text": "农民、学生、手工业者在共同劳作中重建了濒临瓦解的邻里纽带，形成了非正式但高效的合作网络。", "target_word": "劳作", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "一天的劳作让他很累。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间的劳作使她的手变粗了。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每天的劳作从早上五点开始。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "辛苦的劳作换来了好收成。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一天的劳作，大家都想早点休息。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人习惯了田间的劳作。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不怕劳作的辛苦。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母亲的劳作养大了我们三个孩子。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "劳作之后，喝一杯茶最舒服。", "target_word": "劳作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "勞作", "label": "繁体"}, {"form": "辛勤劳作", "label": "复合"}], "register": "中性", "sense_fingerprint": "辛苦的体力劳动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13542, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "劳作", "is_correct": true, "explanation": "劳作指体力劳动，与「在共同……中重建纽带」的语境相合，是此处唯一合适的词。"}, {"text": "睡眠", "is_correct": false, "explanation": "语义：睡眠不是能够共同重建邻里纽带的活动，句意不通。"}, {"text": "争吵", "is_correct": false, "explanation": "语义：争吵会破坏邻里关系，与「重建纽带」的语义相反。"}, {"text": "玩意儿", "is_correct": false, "explanation": "语域：「玩意儿」是口语中指代不明的泛称，不宜出现在这句书面语的正式语境中。"}], "explanations": {"劳作": "劳作指体力劳动，与「在共同……中重建纽带」的语境相合，是此处唯一合适的词。", "睡眠": "语义：睡眠不是能够共同重建邻里纽带的活动，句意不通。", "争吵": "语义：争吵会破坏邻里关系，与「重建纽带」的语义相反。", "玩意儿": "语域：「玩意儿」是口语中指代不明的泛称，不宜出现在这句书面语的正式语境中。"}, "sentence_index": 0, "correct_answer": "劳作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的劳作很简单，只要按一下按钮。", "explanation": "这里应该用〈操作〉。劳作指干活，机器的使用要用〈操作〉。"}, {"text": "这次社区的劳作是一场唱歌比赛，大家玩得很开心。", "explanation": "这里应该用〈比赛〉。劳作指辛苦的体力活，唱歌比赛属文娱活动，不能称作劳作。"}, {"text": "他的劳作很有名，画展上挂满了他的画。", "explanation": "这里应该用〈作品〉。劳作指干活，画作这类成果要用〈作品〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13542, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "劳作", "is_correct": true, "explanation": "劳作指田间的体力活，「习惯了田间的劳作」通顺自然，是唯一合适的词。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：「田间」与「书本」不搭配，田间的人不会习惯书本。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：疾病不是可以习惯的日常活动，与田间的生活场景不合。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：「田间」不能修饰「乐器」，二者搭配不当，句意不通。"}], "explanations": {"劳作": "劳作指田间的体力活，「习惯了田间的劳作」通顺自然，是唯一合适的词。", "书本": "搭配：「田间」与「书本」不搭配，田间的人不会习惯书本。", "疾病": "语义：疾病不是可以习惯的日常活动，与田间的生活场景不合。", "乐器": "搭配：「田间」不能修饰「乐器」，二者搭配不当，句意不通。"}, "sentence_index": 6, "correct_answer": "劳作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套系统的劳作很稳定，从没出过问题。", "explanation": "这里应该用〈运行〉。劳作指干活，系统的运行要用〈运行〉。"}, {"text": "他是家里的主要劳作。", "explanation": "这里应该用〈劳力〉。劳作是活动，不能指人，指家里干活的人要用〈劳力〉。"}, {"text": "他每天的劳作是坐在办公室里写程序。", "explanation": "这里应该用〈工作〉。劳作指辛苦的体力劳动，坐在办公室写程序属脑力工作，不能称作劳作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13542, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经过一天辛苦得劳作，大家都累了。", "corrected_sentence": "经过一天辛苦的劳作，大家都累了。", "error_description": "结构助词错误：「劳作」是名词，前面的修饰语「辛苦」要用「的」连接，不能用「得」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13542, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "田间地劳作很辛苦。", "corrected_sentence": "田间的劳作很辛苦。", "error_description": "结构助词错误：「劳作」在这里是名词，修饰它要用「的」，不能用修饰动词的「地」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13543, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
