INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13543, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "接近某种不利的状态或边缘，多指即将陷入困境、灭亡或崩溃。", "primary_collocate": null, "pronunciation": "bīn lín", "ipa": "pin˥ lin˧˥", "syllable_count": 2, "sentences": [{"text": "农民、学生、手工业者在共同劳作中重建了濒临瓦解的邻里纽带，形成了非正式但高效的合作网络。", "target_word": "濒临", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这种鸟已经濒临灭绝，我们要保护它们。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家小公司濒临破产，工人都很着急。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人病得很重，已经濒临死亡。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水越来越少，这条河濒临干涸。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他工作太累，身体濒临崩溃。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济不好，很多商店濒临倒闭。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子的传统已经濒临消失。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国谈了很久，关系濒临破裂。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她哭了一夜，情绪濒临失控。", "target_word": "濒临", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濒临着", "label": "体标"}], "register": "书面", "sense_fingerprint": "濒临：接近某种不好的状态或边缘", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13543, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "濒临", "is_correct": true, "explanation": "濒临指快要陷入某种状态的边缘，修饰「瓦解」恰合句意。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝瓦解与「重建纽带」的语义相反，句意矛盾。"}, {"text": "诞生", "is_correct": false, "explanation": "语义：「诞生」指新事物出现，不能用来修饰瓦解的纽带。"}, {"text": "指挥", "is_correct": false, "explanation": "配价：「指挥」需要明确的被支配对象，「指挥瓦解的纽带」结构不成立。"}], "explanations": {"濒临": "濒临指快要陷入某种状态的边缘，修饰「瓦解」恰合句意。", "庆祝": "语义：庆祝瓦解与「重建纽带」的语义相反，句意矛盾。", "诞生": "语义：「诞生」指新事物出现，不能用来修饰瓦解的纽带。", "指挥": "配价：「指挥」需要明确的被支配对象，「指挥瓦解的纽带」结构不成立。"}, "sentence_index": 0, "correct_answer": "濒临"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他努力学习，成绩濒临优秀。", "explanation": "这里应该用〈接近〉。濒临只用于接近不好的状态，如灭绝、破产；接近好的结果要用〈接近〉。"}, {"text": "比赛濒临开始，大家很激动。", "explanation": "这里应该用〈即将〉。濒临侧重于接近某种状态或边缘，多用于不利情况；比赛即将开始要用〈即将〉。"}, {"text": "他们濒临新的机会。", "explanation": "这里应该用〈面临〉。濒临指接近某种状态的边缘，不用于面对机会，面对新机会要用〈面临〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13543, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "濒临", "is_correct": true, "explanation": "濒临表示快要陷入不好的状况，「很多商店濒临倒闭」意思完整，是唯一合适的词。"}, {"text": "开张", "is_correct": false, "explanation": "语义：开张与倒闭的语义相反，「开张倒闭」句意矛盾。"}, {"text": "盼望", "is_correct": false, "explanation": "语义：商店不会盼望自己倒闭，这一搭配不合常理。"}, {"text": "修理", "is_correct": false, "explanation": "配价：「修理」需要具体的被修理对象，「修理倒闭」没有合理的宾语。"}], "explanations": {"濒临": "濒临表示快要陷入不好的状况，「很多商店濒临倒闭」意思完整，是唯一合适的词。", "开张": "语义：开张与倒闭的语义相反，「开张倒闭」句意矛盾。", "盼望": "语义：商店不会盼望自己倒闭，这一搭配不合常理。", "修理": "配价：「修理」需要具体的被修理对象，「修理倒闭」没有合理的宾语。"}, "sentence_index": 6, "correct_answer": "濒临"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "经过多年努力，他终于濒临成功。", "explanation": "这里应该用〈接近〉。濒临多指接近灭亡、崩溃等不利状态，不能用于成功这样的好结果。"}, {"text": "我濒临老师，老师很高兴。", "explanation": "这里应该用〈靠近〉。濒临要接近的是某种状态或边缘，人与人之间的接近要用〈靠近〉。"}, {"text": "春天来了，花园濒临美丽。", "explanation": "这里应该用〈变得〉。濒临只表示接近不利的状态或边缘，不能用于美丽这样的好状态。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13543, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座老房子已经濒临了倒塌。", "corrected_sentence": "这座老房子已经濒临倒塌。", "error_description": "「了」不能插在「濒临」与「倒塌」之间，正确形式为「已经濒临倒塌」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13543, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家餐厅的生意濒临在亏损，老板很着急。", "corrected_sentence": "这家餐厅的生意濒临亏损，老板很着急。", "error_description": "「濒临」后直接接动词性成分，不能加「在」，正确形式为「濒临亏损」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
