INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13545, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13545, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "许多人为了共同目标一起行动。", "primary_collocate": null, "pronunciation": "jí tǐ xíng dòng", "ipa": "tɕi˧˥ tʰi˨˩˦ ɕiŋ˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "集体行动", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "这次集体行动需要大家一起参加。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民发起了一次集体行动，保护河水。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集体行动比一个人做更有力量。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师带学生参加集体行动，打扫公园。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司组织了一次集体行动，去山区送书。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要参加集体行动，就要听从安排。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场集体行动让邻居们更团结。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "集体行动的目的是解决小区的停车问题。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有计划的集体行动很容易失败。", "target_word": "集体行动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "书面", "sense_fingerprint": "集体行动：许多人为共同目标而一起采取的行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '295ce1da-7676-4f3c-bb25-0288a4081964') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13545, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "集体行动", "is_correct": true, "explanation": "正确。“集体行动”指许多人为共同目标一起行动，与“基于共识”“村民代表”的语境相合。"}, {"text": "个人行动", "is_correct": false, "explanation": "语义：“基于共识”和“村民代表”都指向群体，“个人行动”与句意相矛盾。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：“雨水”不能作为“基于共识”的事物，也无法“催生”治理雏形，句意不通。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“基于……的”后接可以由共识产生的行动或制度，“树木”不能如此搭配。"}], "explanations": {"集体行动": "正确。“集体行动”指许多人为共同目标一起行动，与“基于共识”“村民代表”的语境相合。", "个人行动": "语义：“基于共识”和“村民代表”都指向群体，“个人行动”与句意相矛盾。", "雨水": "语义：“雨水”不能作为“基于共识”的事物，也无法“催生”治理雏形，句意不通。", "树木": "搭配：“基于……的”后接可以由共识产生的行动或制度，“树木”不能如此搭配。"}, "sentence_index": 0, "correct_answer": "集体行动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个集体行动成立于二〇〇五年。", "explanation": "这里应该用〈团体〉。〈集体行动〉是一次一起做的事，不是有组织的群体，不能说“成立”。"}, {"text": "这个集体行动有两百名会员。", "explanation": "这里应该用〈协会〉。〈集体行动〉指一起做的事，没有会员，说会员要用〈协会〉。"}, {"text": "我们一起参加了一座集体行动。", "explanation": "这里应该用〈次〉。〈集体行动〉是一次行动，应按次计，用〈次〉，不能用大型固定物类量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13545, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "集体行动", "is_correct": true, "explanation": "正确。“要参加集体行动”指加入一起做的事，与“就要听从安排”相合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“参加”的对象须是活动或组织，“天气”不能被参加，句意不通。"}, {"text": "秩序", "is_correct": false, "explanation": "搭配：“参加”可以接活动、会议，“秩序”不能被“参加”，搭配不成立。"}, {"text": "空气", "is_correct": false, "explanation": "语义：“空气”是自然物，不能被参加，也无法“听从安排”，句意不通。"}], "explanations": {"集体行动": "正确。“要参加集体行动”指加入一起做的事，与“就要听从安排”相合。", "天气": "语义：“参加”的对象须是活动或组织，“天气”不能被参加，句意不通。", "秩序": "搭配：“参加”可以接活动、会议，“秩序”不能被“参加”，搭配不成立。", "空气": "语义：“空气”是自然物，不能被参加，也无法“听从安排”，句意不通。"}, "sentence_index": 6, "correct_answer": "集体行动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他参加了一位集体行动。", "explanation": "这里的量词〈位〉用错了。〈位〉用于人，〈集体行动〉是一次行动，应用〈次〉。"}, {"text": "我们策划了一张集体行动。", "explanation": "这里应该用〈次〉。〈集体行动〉是一次行动，应按次计，用〈次〉。"}, {"text": "这只集体行动很成功。", "explanation": "这里应该用〈次〉。〈集体行动〉是一次行动，应按次计，用〈次〉，不能用动物类量词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13545, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班这首集体行动很成功。", "corrected_sentence": "我们班这次集体行动很成功。", "error_description": "“集体行动”计数用“次”或“场”，“首”用于诗歌、歌曲，不能修饰它。应改为“这次集体行动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13545, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这把集体行动很成功。", "corrected_sentence": "这场集体行动很成功。", "error_description": "“集体行动”计数时用“场”或“次”，“把”用于有柄的器具，不能修饰它。应改为“这场集体行动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a98be8f-bd81-478b-80c8-4e753998323d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
