INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13547, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "为防风固沙、保持水土等而种植的树林。", "primary_collocate": null, "pronunciation": "fáng hù lín", "ipa": "faŋ˧˥ xu˥˩ lin˧˥", "syllable_count": 3, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "防护林", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "沙漠边上种了一片防护林。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "防护林可以挡住大风和沙子。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片防护林保护着河边的农田。", "target_word": "防护林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民每年春天都去防护林里种树。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "有了防护林，村子里的沙尘少多了。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北方建了很多防护林来防止沙漠扩大。", "target_word": "防护林", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片防护林已经长了二十多年了。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "防护林里的树木很高，风吹不进去。", "target_word": "防护林", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府在海边种防护林，是为了挡住大风。", "target_word": "防护林", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "防護林", "label": "繁体"}], "register": "中性", "sense_fingerprint": "为防风固沙、保持水土而种的树林", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13547, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "防护林", "is_correct": true, "explanation": "正确。防护林是成片的树林，可以因规划争议被砍伐，与“砍伐”相合。"}, {"text": "农田", "is_correct": false, "explanation": "语义：农田是种植庄稼的田地，不是树木，不会被砍伐。"}, {"text": "海滩", "is_correct": false, "explanation": "语义：海滩是沙质岸地，不是树林，与“砍伐”的对象不符。"}, {"text": "广场", "is_correct": false, "explanation": "搭配：“砍伐”的对象是树木，不能说广场面临砍伐。"}], "explanations": {"防护林": "正确。防护林是成片的树林，可以因规划争议被砍伐，与“砍伐”相合。", "农田": "语义：农田是种植庄稼的田地，不是树木，不会被砍伐。", "海滩": "语义：海滩是沙质岸地，不是树林，与“砍伐”的对象不符。", "广场": "搭配：“砍伐”的对象是树木，不能说广场面临砍伐。"}, "sentence_index": 0, "correct_answer": "防护林"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片防护林是专门为卖木材而种的，每年都有很多收入。", "explanation": "这里应该用〈用材林〉。防护林是为防风固沙而种，为卖木材而种的树林要说用材林。"}, {"text": "这个防护林里有很多游乐设施，孩子们每天都来玩。", "explanation": "这里应该用〈游乐场〉。防护林是为防风固沙而种的树林，供孩子玩耍、设有游乐设施的地方要说游乐场。"}, {"text": "这片防护林每天生产很多机器，附近的人都在这里上班。", "explanation": "这里应该用〈工厂〉。防护林是种树挡风沙的树林，生产机器、让人上班的地方要说工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13547, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "防护林", "is_correct": true, "explanation": "正确。防护林能挡风固沙，与“防止沙漠扩大”的目的相合。"}, {"text": "商店", "is_correct": false, "explanation": "语义：商店不能阻挡沙漠扩大，与句意不合。"}, {"text": "歌曲", "is_correct": false, "explanation": "搭配：“建”说建造建筑或设施，不能说建歌曲。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：路灯的作用是照明，与阻挡沙漠扩大无关。"}], "explanations": {"防护林": "正确。防护林能挡风固沙，与“防止沙漠扩大”的目的相合。", "商店": "语义：商店不能阻挡沙漠扩大，与句意不合。", "歌曲": "搭配：“建”说建造建筑或设施，不能说建歌曲。", "路灯": "语义：路灯的作用是照明，与阻挡沙漠扩大无关。"}, "sentence_index": 6, "correct_answer": "防护林"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这片防护林是政府为了供人游玩而建的。", "explanation": "这里应该用〈公园〉。防护林是为挡风固沙而建的，供人游玩的地方要说公园。"}, {"text": "这片防护林是专门用来种粮食的。", "explanation": "这里应该用〈农田〉。防护林用来挡风固沙，专门种粮食的地方要说农田。"}, {"text": "这片防护林是专门用来安葬去世的人的。", "explanation": "这里应该用〈墓园〉。防护林是为防风固沙而种，安葬去世的人的地方要说墓园。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13547, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这棵防护林终于长成了。", "corrected_sentence": "这片防护林终于长成了。", "error_description": "量词错误：防护林是成片的树林，应该用“片”；“棵”用于单独的树，不能说“这棵防护林”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13547, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙漠边上有一只防护林，已经很高了。", "corrected_sentence": "沙漠边上有一片防护林，已经很高了。", "error_description": "量词错误：防护林是成片的树林，应该用“片”；“只”用于动物或成对的东西，不能说“一只防护林”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
