INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13548, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用斧、锯等把树木等砍倒。", "primary_collocate": null, "pronunciation": "kǎn fá", "ipa": "kʰan˨˩ fa˧˥", "syllable_count": 2, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "砍伐", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "森林里不能随便砍伐树木。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们昨天砍伐了山上的老树。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们砍伐过很多树，现在后悔了。", "target_word": "砍伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "砍伐太多树木，会让山变得很干。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府不让人们在河边砍伐树木。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了盖房子，村民砍伐了一片小树林。", "target_word": "砍伐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用电锯砍伐大树，声音很大。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过度砍伐森林会破坏环境。", "target_word": "砍伐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些木头是工人在北山砍伐的。", "target_word": "砍伐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "砍伐了", "label": "体标"}, {"form": "砍伐过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用斧、锯等把树木砍倒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13548, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "砍伐", "is_correct": true, "explanation": "正确答案。砍伐 kǎn fá：用斧、锯等把树木砍倒。"}, {"text": "看法", "is_correct": false, "explanation": "看法 kàn fǎ 两个音节的声调都与 kǎn fá 不同（第四声、第三声），意思是对事物的见解。"}, {"text": "砍法", "is_correct": false, "explanation": "砍法 kǎn fǎ 第二音节为第三声，与 fá（第二声）声调不同，意思是砍的方法。"}, {"text": "刊发", "is_correct": false, "explanation": "刊发 kān fā 第一音节 kān（第一声）与 kǎn（第三声）声调不同，第二音节 fā 与 fá 声调也不同，意思是刊登发表。"}], "explanations": {"砍伐": "正确答案。砍伐 kǎn fá：用斧、锯等把树木砍倒。", "看法": "看法 kàn fǎ 两个音节的声调都与 kǎn fá 不同（第四声、第三声），意思是对事物的见解。", "砍法": "砍法 kǎn fǎ 第二音节为第三声，与 fá（第二声）声调不同，意思是砍的方法。", "刊发": "刊发 kān fā 第一音节 kān（第一声）与 kǎn（第三声）声调不同，第二音节 fā 与 fá 声调也不同，意思是刊登发表。"}, "sentence_index": null, "correct_answer": "砍伐"}, "level_3": {"options": [{"text": "砍伐", "is_correct": true, "explanation": "正确：“面临砍伐”指防护林将被砍伐，与规划争议的语境相合。"}, {"text": "培育", "is_correct": false, "explanation": "语义：“面临”引出的是威胁，培育是促进生长，与防护林受威胁的语境相反。"}, {"text": "保护", "is_correct": false, "explanation": "语义：“面临”后接威胁，“保护”表示维护，两者相互矛盾。"}, {"text": "修复", "is_correct": false, "explanation": "搭配：“修复”针对受损的对象，防护林尚未受损时不能说“面临修复”。"}], "explanations": {"砍伐": "正确：“面临砍伐”指防护林将被砍伐，与规划争议的语境相合。", "培育": "语义：“面临”引出的是威胁，培育是促进生长，与防护林受威胁的语境相反。", "保护": "语义：“面临”后接威胁，“保护”表示维护，两者相互矛盾。", "修复": "搭配：“修复”针对受损的对象，防护林尚未受损时不能说“面临修复”。"}, "sentence_index": 0, "correct_answer": "砍伐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "园丁每周都砍伐院子里的草坪。", "explanation": "这里应该用〈修剪〉。砍伐专指把树木砍倒，草坪应当修剪，不能说砍伐。"}, {"text": "他用剪刀砍伐了那根绳子。", "explanation": "这里应该用〈剪断〉。砍伐的对象是树木，不能用剪刀去砍伐绳子。"}, {"text": "他用菜刀砍伐了一下鸡骨头。", "explanation": "这里应该用〈砍〉。砍伐专指把树木砍倒，不用于用菜刀砍鸡骨头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13548, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "砍伐", "is_correct": true, "explanation": "正确：砍伐树林是为了腾出地方盖房子，与句中的目的相合。"}, {"text": "种植", "is_correct": false, "explanation": "语义：为了盖房子而去种植一片树林，目的与行为相悖。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪的对象多是枝叶，不说“修剪一片小树林”。"}, {"text": "栽培", "is_correct": false, "explanation": "语义：栽培是为了让植物生长，与为盖房子而清出土地的目的不合。"}], "explanations": {"砍伐": "正确：砍伐树林是为了腾出地方盖房子，与句中的目的相合。", "种植": "语义：为了盖房子而去种植一片树林，目的与行为相悖。", "修剪": "搭配：修剪的对象多是枝叶，不说“修剪一片小树林”。", "栽培": "语义：栽培是为了让植物生长，与为盖房子而清出土地的目的不合。"}, "sentence_index": 6, "correct_answer": "砍伐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里砍伐麦子。", "explanation": "这里应该用〈收割〉。收割指割下成熟的庄稼；砍伐专用于树木。"}, {"text": "他在树上砍伐了几个苹果。", "explanation": "这里应该用〈摘〉。摘指把果实从树上取下；砍伐指把树砍倒。"}, {"text": "工人在地下砍伐煤。", "explanation": "这里应该用〈挖〉。挖用于开采矿物；砍伐只用于把树木砍倒。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13548, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们砍伐倒了三棵树。", "corrected_sentence": "我们砍伐了三棵树。", "error_description": "补语错误：“砍伐”已是完整动词，后面不能再接结果补语“倒”。错误形式为“砍伐倒了”，正确形式为“砍伐了”；若要表达“砍倒”，应直接说“砍倒”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13548, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我父亲年轻时砍伐了过一棵老松树。", "corrected_sentence": "我父亲年轻时砍伐过一棵老松树。", "error_description": "体标错误：“了”与“过”不能同用，“过”应紧接动词。错误形式为“砍伐了过”，正确形式为“砍伐过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
