INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "村民代表是指由村民选举产生，代表村民参与村务管理、表达村民意愿的人。", "primary_collocate": null, "pronunciation": "cūn mín dài biǎo", "ipa": "tsʰwən˥ min˧˥ taɪ̯˥˩ piɑʊ̯˨˩˦", "syllable_count": 4, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "村民代表", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "村民代表由全村人投票选出来。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表在会上说出了大家的想法。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位村民代表每个月都去村委会开会。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里要修路，村民代表先去看了地方。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表把大家的意见交给了村长。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全村人投票选出了新的村民代表。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她当了三年村民代表，帮村里解决了不少问题。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会前，村民代表先听了邻居们的意见。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民代表要向村民说明村里的钱怎么用。", "target_word": "村民代表", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位村民代表", "label": "量词"}, {"form": "村民代表大会", "label": "复合"}], "register": "中性", "sense_fingerprint": "由村民选举产生、参与村务管理并表达村民意愿的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "村民代表", "is_correct": true, "explanation": "正确：村民代表能依据本村的生态数据与法律条文，在听证会上代表村民提出意见。"}, {"text": "伐木公司", "is_correct": false, "explanation": "语义：伐木公司是砍伐方，不会在听证会上反对自己的砍伐计划。"}, {"text": "小孩子", "is_correct": false, "explanation": "语义：小孩子没有长期积累的生态数据，也不能在听证会上代表村民发言。"}, {"text": "外地商人", "is_correct": false, "explanation": "语义：外地商人没有本村长期积累的生态数据，也不代表村民的意愿。"}], "explanations": {"村民代表": "正确：村民代表能依据本村的生态数据与法律条文，在听证会上代表村民提出意见。", "伐木公司": "语义：伐木公司是砍伐方，不会在听证会上反对自己的砍伐计划。", "小孩子": "语义：小孩子没有长期积累的生态数据，也不能在听证会上代表村民发言。", "外地商人": "语义：外地商人没有本村长期积累的生态数据，也不代表村民的意愿。"}, "sentence_index": 0, "correct_answer": "村民代表"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "村民代表代表公司回答记者的问题。", "explanation": "这里应该用〈发言人〉。发言人代表机构对外发言；村民代表代表的是村民的意愿，不代表公司。"}, {"text": "村民代表负责管理全班的同学。", "explanation": "这里应该用〈班长〉。班长管理班级事务；村民代表是村民选出来表达意愿的人，不管理班级。"}, {"text": "村民代表负责把包裹送到家门口。", "explanation": "这里应该用〈快递员〉。快递员负责送件；村民代表的职责是表达村民意愿，不负责送包裹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "村民代表", "is_correct": true, "explanation": "正确：全村人投票选出的是担任村务代表的人，村民代表与句意相合。"}, {"text": "庄稼", "is_correct": false, "explanation": "语义：庄稼是地里种的作物，不能通过投票选出来。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“选出”的对象应是人或职务，不说“选出木头”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能经投票选出来担任职务。"}], "explanations": {"村民代表": "正确：全村人投票选出的是担任村务代表的人，村民代表与句意相合。", "庄稼": "语义：庄稼是地里种的作物，不能通过投票选出来。", "木头": "搭配：“选出”的对象应是人或职务，不说“选出木头”。", "桌子": "语义：桌子不能经投票选出来担任职务。"}, "sentence_index": 6, "correct_answer": "村民代表"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "村民代表负责治疗病人。", "explanation": "这里应该用〈医生〉。医生负责诊治病人；村民代表是表达村民意愿的人，不负责治疗。"}, {"text": "村民代表负责做饭。", "explanation": "这里应该用〈厨师〉。厨师负责烹饪；村民代表的职责是表达村民意愿，不负责做饭。"}, {"text": "村民代表负责教学生。", "explanation": "这里应该用〈老师〉。老师负责教学；村民代表不负责教育学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村推选了两只村民代表。", "corrected_sentence": "我们村推选了两位村民代表。", "error_description": "量词错误：村民代表指人，应用“位”或“个”，“只”用于动物或小物件。错误形式为“两只村民代表”，正确形式为“两位村民代表”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13549, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里推选了三村民代表。", "corrected_sentence": "村里推选了三位村民代表。", "error_description": "量词缺失：数词“三”后面必须加量词，指人的“村民代表”应用“位”。错误形式为“三村民代表”，正确形式为“三位村民代表”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
