INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "为听取公众意见或进行法律程序而召开的正式会议。", "primary_collocate": null, "pronunciation": "tīng zhèng huì", "ipa": "tʰiŋ˥ ʈʂɤŋ˥˩ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "这种基于共识的集体行动，催生出一种新型的公共治理雏形：当某片防护林因规划争议面临砍伐时，村民代表能依据长期积累的生态数据与法律条文，在听证会上提出有理有据的反对意见，并最终促成替代方案的出台。", "target_word": "听证会", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "市政府将召开听证会，听取居民的意见。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水价要涨，先要开一场听证会。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听证会上，专家和居民都发了言。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场听证会有三十多位市民参加。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院明天公开举行听证会，听双方说明理由。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在听证会上回答了议员的问题。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听证会结束后，政府会公布结果。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想建新工厂，居民要求召开听证会。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者坐在听证会的后排，认真地做记录。", "target_word": "听证会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场听证会", "label": "量词"}, {"form": "价格听证会", "label": "复合"}, {"form": "聽證會", "label": "繁体"}], "register": "正式", "sense_fingerprint": "为听取公众意见或进行法律程序而召开的正式会议", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c922d040-007a-4bf8-8a2a-fa6171f2be5c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听证会", "is_correct": true, "explanation": "“听证会”是为听取公众意见而召开的正式会议，可以“在听证会上提出反对意见”，与“依据法律条文”“规划争议”的语境相符。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：婚礼是喜庆的私人仪式，不是为听取公众意见设立的程序，与防护林砍伐的规划争议不符。"}, {"text": "运动场", "is_correct": false, "explanation": "搭配：“提出有理有据的反对意见”需要议事的场合，“运动场”是体育场地，两者搭配不通。"}, {"text": "演唱会", "is_correct": false, "explanation": "语义：演唱会是娱乐表演，与依据法律条文提出反对意见的语境不符。"}], "explanations": {"听证会": "“听证会”是为听取公众意见而召开的正式会议，可以“在听证会上提出反对意见”，与“依据法律条文”“规划争议”的语境相符。", "婚礼": "语义：婚礼是喜庆的私人仪式，不是为听取公众意见设立的程序，与防护林砍伐的规划争议不符。", "运动场": "搭配：“提出有理有据的反对意见”需要议事的场合，“运动场”是体育场地，两者搭配不通。", "演唱会": "语义：演唱会是娱乐表演，与依据法律条文提出反对意见的语境不符。"}, "sentence_index": 0, "correct_answer": "听证会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们开听证会，大家随便聊聊工作。", "explanation": "这里应该用〈座谈会〉。座谈会可以随意交流，听证会是为听取公众意见、依法召开的正式会议，不能用于随便聊天。"}, {"text": "公司在听证会上表彰了三位优秀员工。", "explanation": "这里应该用〈颁奖典礼〉。颁奖典礼用于授奖、表彰先进，听证会是听取公众意见、依法召开的正式会议，不用于表彰员工。"}, {"text": "听证会上，老师和同学一起讨论论文。", "explanation": "这里应该用〈研讨会〉。研讨会是共同讨论学术问题的场合，听证会是听取公众意见的正式程序，不用于师生讨论论文。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听证会", "is_correct": true, "explanation": "“听证会”是正式的听证场合，议员可以在此提出问题，与“回答议员的问题”相符。"}, {"text": "球场", "is_correct": false, "explanation": "搭配：“回答议员的问题”需要议事或质询的场合，“球场”是体育场地，两者搭配不通。"}, {"text": "菜场", "is_correct": false, "explanation": "语义：菜场是买卖蔬菜的地方，与议员质询的语境毫不相干。"}, {"text": "操场", "is_correct": false, "explanation": "搭配：“操场”是学校的运动场地，与“回答议员的问题”的正式场合不符。"}], "explanations": {"听证会": "“听证会”是正式的听证场合，议员可以在此提出问题，与“回答议员的问题”相符。", "球场": "搭配：“回答议员的问题”需要议事或质询的场合，“球场”是体育场地，两者搭配不通。", "菜场": "语义：菜场是买卖蔬菜的地方，与议员质询的语境毫不相干。", "操场": "搭配：“操场”是学校的运动场地，与“回答议员的问题”的正式场合不符。"}, "sentence_index": 6, "correct_answer": "听证会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司召开听证会，向员工介绍新的福利政策。", "explanation": "这里应该用〈说明会〉。说明会是单向介绍信息的场合，听证会是听取意见的正式程序，不用于向员工介绍政策。"}, {"text": "听证会上，老师讲解了古代历史。", "explanation": "这里应该用〈讲座〉。讲座由讲者单向讲授，听证会是听取公众意见、依法进行的会议，不能用于老师讲课。"}, {"text": "听证会上，网友们自由讨论热门话题。", "explanation": "这里应该用〈论坛〉。论坛供人自由发表看法，听证会有法定议题和程序，不用于随意讨论。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "居民们听证会上提出了反对意见。", "corrected_sentence": "居民们在听证会上提出了反对意见。", "error_description": "介词错误：“听证会”作处所时要用介词“在”引出，应说“在听证会上”，漏掉“在”句子不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13550, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他参加了一杯听证会，很有收获。", "corrected_sentence": "他参加了一场听证会，很有收获。", "error_description": "量词错误：听证会是会议，应该用“场”；“杯”多用于饮品，不能说“一杯听证会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '600bfefa-898b-4c8c-b8e7-cdac8f9711a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
