INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指各种组织中最直接与群众接触、开展具体工作的一层，如基层单位、基层干部。", "primary_collocate": null, "pronunciation": "jī céng", "ipa": "tɕi⁵⁵ tsʰəŋ³⁵", "syllable_count": 2, "sentences": [{"text": "这表明，基层环保实践正逐步演进为公民参与社会治理的有效路径。", "target_word": "基层", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他毕业后去基层工作了两年。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位医生一直在基层为农民看病。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基层干部每天都要和村民打交道。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府要多听基层的声音。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "很多年轻人愿意到基层去锻炼。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "基层单位的工作很忙，但很有意义。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从基层做起，一步一步当上了经理。", "target_word": "基层", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些政策要真正落实到基层。", "target_word": "基层", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在基层待过十年，很了解老百姓的生活。", "target_word": "基层", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "基層", "label": "繁体"}, {"form": "基层干部", "label": "复合"}, {"form": "基层单位", "label": "复合"}, {"form": "基层组织", "label": "复合"}], "register": "中性", "sense_fingerprint": "组织中直接接触群众、做具体工作的一层", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b05fab6d-52c3-4f0b-9cb0-3e12924a3383') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”指组织中直接接触群众、开展具体工作的一层。"}, {"text": "几层", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，意思是几个楼层、几层。"}, {"text": "集成", "is_correct": false, "explanation": "jí（第二声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是把各部分合在一起。"}, {"text": "几成", "is_correct": false, "explanation": "jǐ（第三声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是几成、几分之几。"}], "explanations": {"基层": "“基层”指组织中直接接触群众、开展具体工作的一层。", "几层": "jǐ（第三声）与 jī（第一声）声调不同，意思是几个楼层、几层。", "集成": "jí（第二声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是把各部分合在一起。", "几成": "jǐ（第三声）与 jī 声调不同；chéng 与 céng 声母不同（ch/c），意思是几成、几分之几。"}, "sentence_index": null, "correct_answer": "基层"}, "level_3": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”修饰“环保实践”，指在最基层直接开展的实践，与句意相符。"}, {"text": "理论", "is_correct": false, "explanation": "语义：“理论”指抽象学说，与“实践”相对，不能修饰“环保实践”。"}, {"text": "足球", "is_correct": false, "explanation": "语义：足球与环保实践无关，不能修饰“实践”。"}, {"text": "书本", "is_correct": false, "explanation": "搭配：“书本”不能修饰“实践”，说“书本环保实践”搭配不当。"}], "explanations": {"基层": "“基层”修饰“环保实践”，指在最基层直接开展的实践，与句意相符。", "理论": "语义：“理论”指抽象学说，与“实践”相对，不能修饰“环保实践”。", "足球": "语义：足球与环保实践无关，不能修饰“实践”。", "书本": "搭配：“书本”不能修饰“实践”，说“书本环保实践”搭配不当。"}, "sentence_index": 0, "correct_answer": "基层"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的英语基层很好。", "explanation": "这里应该用〈基础〉。基础指事物的根基，基层指组织中直接接触群众的一层。"}, {"text": "他明白了做人的基层道理。", "explanation": "这里应该用〈基本〉。基本指根本、主要，基层指组织中直接接触群众的一层。"}, {"text": "我们的训练基层在山里，条件很好。", "explanation": "这里应该用〈基地〉。基地指进行某项活动的场所，基层指组织中的一层，不能表示训练场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基层", "is_correct": true, "explanation": "“基层”指组织中直接接触群众的一层，修饰“单位”符合句意。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不是组织机构，不能作为“单位”的修饰语，句意不通。"}, {"text": "植物", "is_correct": false, "explanation": "搭配：“植物”不能修饰“单位”（指机构），搭配不当。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不是组织机构，“动物单位”无法指代工作单位，句意不通。"}], "explanations": {"基层": "“基层”指组织中直接接触群众的一层，修饰“单位”符合句意。", "水果": "语义：水果不是组织机构，不能作为“单位”的修饰语，句意不通。", "植物": "搭配：“植物”不能修饰“单位”（指机构），搭配不当。", "动物": "语义：动物不是组织机构，“动物单位”无法指代工作单位，句意不通。"}, "sentence_index": 6, "correct_answer": "基层"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们成立了一个教育基层，帮助贫困学生。", "explanation": "这里应该用〈基金〉。基金指为某种用途聚集的资金，基层指组织中直接接触群众的一层。"}, {"text": "这个基层决定了孩子的眼睛颜色。", "explanation": "这里应该用〈基因〉。基因指决定生物遗传性状的单位，基层指组织中的一层。"}, {"text": "诚信是做人的基层。", "explanation": "这里应该用〈基石〉。基石指建筑的基础，比喻根本，基层指组织中直接接触群众的一层。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她毕业后先基层锻炼了三年。", "corrected_sentence": "她毕业后先在基层锻炼了三年。", "error_description": "“基层”作处所时要用介词“在”引出，应说“在基层锻炼”，不能省略“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13555, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个县的每个村都有一把基层组织。", "corrected_sentence": "这个县的每个村都有一个基层组织。", "error_description": "量词“把”用于有柄的器具，不能用于组织，应说“一个基层组织”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
