INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "物种是生物分类的基本单位，指一群形态相似、能相互交配并产生可育后代的生物个体。", "primary_collocate": null, "pronunciation": "wù zhǒng", "ipa": "u˥˩ ʈʂʊŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "从生态学视角审视，该项目尤为重视物种配置的科学性。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "栖息地碎片化、农药滥用、气候变化以及外来物种入侵，正在协同加速蜜蜂种群的衰退，进而威胁整个陆地生态系统的功能完整性。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "生物多样性的维系并非仅关乎物种数量的多寡，更在于物种间相互依存关系的稳健性。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "然而，当前全球平均每三年就有一种野生蜂类被列为濒危物种，这一速度是自然灭绝率的数百倍。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这个岛上有许多珍贵的物种。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新物种的发现让科学家很高兴。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外来物种可能会伤害本地的动物。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个物种都有自己的生活方式。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护濒危物种需要大家一起努力。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家给这个新物种起了名字。", "target_word": "物种", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "物種", "label": "繁体"}], "register": "书面", "sense_fingerprint": "物种：生物学中分类的基本单位，能相互交配并产生可育后代的一群生物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71266d48-abd2-408d-ab3d-49d9cf61150e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。物种读作 wù zhǒng，指生物分类的基本单位。"}, {"text": "五种", "is_correct": false, "explanation": "wǔ（第三声）与 wù（第四声）声调不同，“五种”意思是五类，不是物种。"}, {"text": "物证", "is_correct": false, "explanation": "zhèng（第四声）与 zhǒng（第三声）韵母和声调都不同，“物证”指可作证据的实物。"}, {"text": "物重", "is_correct": false, "explanation": "zhòng（第四声）与 zhǒng（第三声）声调不同，“物重”指物体的重量，不是物种。"}], "explanations": {"物种": "正确。物种读作 wù zhǒng，指生物分类的基本单位。", "五种": "wǔ（第三声）与 wù（第四声）声调不同，“五种”意思是五类，不是物种。", "物证": "zhèng（第四声）与 zhǒng（第三声）韵母和声调都不同，“物证”指可作证据的实物。", "物重": "zhòng（第四声）与 zhǒng（第三声）声调不同，“物重”指物体的重量，不是物种。"}, "sentence_index": null, "correct_answer": "物种"}, "level_3": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。“物种配置”指生物物种的安排，与“生态学视角”相合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑配置”指计算机硬件，与句中的“生态学视角”不符。"}, {"text": "东西", "is_correct": false, "explanation": "语域：“东西”是口语泛称，与句中的书面语体不合。"}, {"text": "单词", "is_correct": false, "explanation": "搭配：“配置”多用于人员、资源、设备，不说“单词配置”。"}], "explanations": {"物种": "正确。“物种配置”指生物物种的安排，与“生态学视角”相合。", "电脑": "语义：“电脑配置”指计算机硬件，与句中的“生态学视角”不符。", "东西": "语域：“东西”是口语泛称，与句中的书面语体不合。", "单词": "搭配：“配置”多用于人员、资源、设备，不说“单词配置”。"}, "sentence_index": 0, "correct_answer": "物种"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只狗是一个很纯的物种。", "explanation": "这里应该用〈品种〉。物种是生物学分类单位，同一物种内不同类型叫品种，狗的纯不纯指品种。"}, {"text": "这家商店的商品物种很多。", "explanation": "这里应该用〈种类〉。物种只用于生物学分类，不能用来说商品的种类。"}, {"text": "超市里摆满了各种物种。", "explanation": "这里应该用〈物品〉。物种只用于生物分类，不能指超市里摆的商品，应说物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物种", "is_correct": true, "explanation": "正确。“外来物种”指从外地或外国引入的生物，能伤害本地动物。"}, {"text": "资金", "is_correct": false, "explanation": "语义：资金是金钱，不会伤害动物，与句意不符。"}, {"text": "语言", "is_correct": false, "explanation": "语义：语言是交流工具，不会伤害动物，与句意不符。"}, {"text": "书籍", "is_correct": false, "explanation": "语义：书籍是文字载体，不会伤害动物，“外来书籍伤害本地动物”与句意不符。"}], "explanations": {"物种": "正确。“外来物种”指从外地或外国引入的生物，能伤害本地动物。", "资金": "语义：资金是金钱，不会伤害动物，与句意不符。", "语言": "语义：语言是交流工具，不会伤害动物，与句意不符。", "书籍": "语义：书籍是文字载体，不会伤害动物，“外来书籍伤害本地动物”与句意不符。"}, "sentence_index": 6, "correct_answer": "物种"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影属于喜剧物种。", "explanation": "这里应该用〈类型〉。物种只用于生物分类，不能指电影的类型。"}, {"text": "最近物种上涨了很多。", "explanation": "这里应该用〈物价〉。物种是生物分类单位，不能说价格上涨，应说物价。"}, {"text": "这种金属是一种稀有的物种。", "explanation": "这里应该用〈物质〉。物种只指生物的分类，金属等非生物不属于物种。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这片森林里发现了三只新物种。", "corrected_sentence": "这片森林里发现了三个新物种。", "error_description": "量词错误：“物种”应搭配“个”或“种”，“只”用于单个动物，不能用来数物种类别。正确说法：三个新物种。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13556, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在书里读到了一条新物种。", "corrected_sentence": "我在书里读到了一个新物种。", "error_description": "量词错误：“物种”应搭配“个”或“种”，“条”用于细长的东西，不能修饰物种。正确说法：一个新物种。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '028b14c4-f1a5-4baa-a2a4-afa5d77dbcb9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
