INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13558, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指事物符合科学原理或具有科学特征的性质。", "primary_collocate": null, "pronunciation": "kē xué xìng", "ipa": "kʰɤ˥ ɕɥœ˧˥ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "从生态学视角审视，该项目尤为重视物种配置的科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "这篇文章的科学性很强，数据也很准确。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这种方法缺乏科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们先检查一下实验设计的科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师要求我们注意计划的科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书既有趣又有科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为这个说法没有科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种树时选择树种要考虑科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究报告最重要的是科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他问了很多问题，想了解这个办法的科学性。", "target_word": "科学性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "科學性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物符合科学原理、具有科学特征的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b05fab6d-52c3-4f0b-9cb0-3e12924a3383') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13558, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "科学性", "is_correct": true, "explanation": "正确答案。“科学性”指物种配置符合科学原理的性质，与语境相合。"}, {"text": "甜味", "is_correct": false, "explanation": "语义：“甜味”是味觉属性，不能说“物种配置的甜味”。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：“歌词”指歌曲的文字，与物种配置无关。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：“名片”是联系方式的卡片，与“物种配置”不搭配。"}], "explanations": {"科学性": "正确答案。“科学性”指物种配置符合科学原理的性质，与语境相合。", "甜味": "语义：“甜味”是味觉属性，不能说“物种配置的甜味”。", "歌词": "语义：“歌词”指歌曲的文字，与物种配置无关。", "名片": "搭配：“名片”是联系方式的卡片，与“物种配置”不搭配。"}, "sentence_index": 0, "correct_answer": "科学性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的科学性很高兴。", "explanation": "这里应该用〈心情〉。科学性指事物的性质，不能用来形容人的心情。"}, {"text": "她对宠物有深厚的科学性。", "explanation": "这里应该用〈感情〉。科学性指事物的性质，不能表示人对动物的情感。"}, {"text": "他心中有远大的科学性。", "explanation": "这里应该用〈梦想〉。科学性指事物的性质，不表示人的志向。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13558, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "科学性", "is_correct": true, "explanation": "正确答案。“没有科学性”指说法不符合科学原理，与语境相合。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能用来评价一个说法的性质。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是人的身体属性，与说法无关。"}, {"text": "名片", "is_correct": false, "explanation": "搭配：“名片”不能用来说明说法的性质。"}], "explanations": {"科学性": "正确答案。“没有科学性”指说法不符合科学原理，与语境相合。", "价格": "语义：“价格”指钱数，不能用来评价一个说法的性质。", "身高": "语义：“身高”是人的身体属性，与说法无关。", "名片": "搭配：“名片”不能用来说明说法的性质。"}, "sentence_index": 6, "correct_answer": "科学性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这幅画的科学性很鲜艳。", "explanation": "这里应该用〈艺术性〉。科学性指事物符合科学原理的性质，画作的审美效果要说艺术性。"}, {"text": "这辆车的科学性很快。", "explanation": "这里应该用〈速度〉。科学性指事物符合科学原理的性质，车的快慢要说速度。"}, {"text": "这条绳子的科学性很合适。", "explanation": "这里应该用〈长度〉。科学性指事物符合科学原理的性质，绳子的尺寸要说长度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13558, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套方法很科学性。", "corrected_sentence": "这套方法很有科学性。", "error_description": "“科学性”是名词，需要动词“有”来带宾语，应说“很有科学性”；“很科学性”不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13558, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个实验的科学性强很。", "corrected_sentence": "这个实验的科学性很强。", "error_description": "程度副词“很”应放在形容词“强”之前，说“科学性很强”；“强很”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9ca0e5-f9e8-4814-b24e-a738c24aed83') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
