INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13561, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "礼貌地请人到自己这里来或参加某个活动。", "primary_collocate": null, "pronunciation": "yāo qǐng", "ipa": "iau˥ tɕʰiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想邀请你来我家吃饭。", "target_word": "邀请", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他邀请全班同学参加生日聚会。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司邀请了三位专家来做报告。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校邀请过很多作家来演讲。", "target_word": "邀请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们邀请我周末去爬山，我很高兴。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "王经理邀请客人到办公室喝茶。", "target_word": "邀请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友邀请我去他的婚礼，我一定去。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市长邀请各国的客人参观这座城市。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她笑着邀请大家一起唱歌。", "target_word": "邀请", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师邀请家长来学校开会。", "target_word": "邀请", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "邀请了", "label": "体标"}, {"form": "邀请过", "label": "体标"}, {"form": "邀请函", "label": "复合"}, {"form": "邀请赛", "label": "复合"}, {"form": "邀請", "label": "繁体"}], "register": "中性", "sense_fingerprint": "礼貌地请人来或参加活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13561, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "邀请", "is_correct": true, "explanation": "正确：“邀请”表示礼貌地请人来，与“请你来我家吃饭”相符。"}, {"text": "告别", "is_correct": false, "explanation": "语义：“告别”是离开时道别，与“来我家吃饭”的方向相反。"}, {"text": "挽留", "is_correct": false, "explanation": "语义：“挽留”是劝人留下，与“来我家吃饭”的意思相反。"}, {"text": "欢送", "is_correct": false, "explanation": "搭配：“欢送”用于送别离开的人，不能接“来我家吃饭”这类动作。"}], "explanations": {"邀请": "正确：“邀请”表示礼貌地请人来，与“请你来我家吃饭”相符。", "告别": "语义：“告别”是离开时道别，与“来我家吃饭”的方向相反。", "挽留": "语义：“挽留”是劝人留下，与“来我家吃饭”的意思相反。", "欢送": "搭配：“欢送”用于送别离开的人，不能接“来我家吃饭”这类动作。"}, "sentence_index": 0, "correct_answer": "邀请"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司邀请了一座仓库，每月付它三千元。", "explanation": "这里应该用〈租用〉。租用是借用场地或物品并付费，邀请只用于请人来做客或参加活动，不能用于物品。"}, {"text": "他邀请老师原谅他。", "explanation": "这里应该用〈请求〉。请求是恳切地要求对方做某事，邀请只用于请人来参加活动或到某处。"}, {"text": "校长邀请全体学生立即回教室。", "explanation": "这里应该用〈命令〉。命令是强制对方立即执行，邀请是礼貌地请人来或参加活动，不能用于指令式地要求回教室。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13561, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "邀请", "is_correct": true, "explanation": "正确：“邀请”表示礼貌地请人来参加活动，与“我一定去”的语境相符。"}, {"text": "祝贺", "is_correct": false, "explanation": "搭配：“祝贺”的对象是喜事或成就，不能说“祝贺我去他的婚礼”。"}, {"text": "主持", "is_correct": false, "explanation": "语义：“主持”指主办或掌管，朋友不能“主持”我去参加婚礼。"}, {"text": "送别", "is_correct": false, "explanation": "语义：“送别”是为离开的人送行，与“去他的婚礼”不符。"}], "explanations": {"邀请": "正确：“邀请”表示礼貌地请人来参加活动，与“我一定去”的语境相符。", "祝贺": "搭配：“祝贺”的对象是喜事或成就，不能说“祝贺我去他的婚礼”。", "主持": "语义：“主持”指主办或掌管，朋友不能“主持”我去参加婚礼。", "送别": "语义：“送别”是为离开的人送行，与“去他的婚礼”不符。"}, "sentence_index": 6, "correct_answer": "邀请"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师邀请家长尽快交材料。", "explanation": "这里应该用〈催促〉。催促是催人赶快做某事，邀请只用于礼貌地请人来参加活动或到某处。"}, {"text": "老师邀请学生不要在课上说话。", "explanation": "这里应该用〈要求〉或〈请〉。邀请只用于礼貌地请人来参加活动或到某处，不能用来让学生不要说话这类纪律要求。"}, {"text": "老师邀请家长注意孩子的安全。", "explanation": "这里应该用〈提醒〉。提醒是让对方留意某事，不是请人来做事，邀请不能替代。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13561, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我邀请着王老师三次。", "corrected_sentence": "我邀请过王老师三次。", "error_description": "错误在体标：“着”表示动作进行或持续，不能用来计算已经发生的次数。应把“着”改成“过”，说“邀请过王老师三次”，表示已经发生过的经历。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13561, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来不邀请过老师来我家。", "corrected_sentence": "我从来没邀请过老师来我家。", "error_description": "错误在否定词：表示过去从未发生的经历要用“没”，“不”多用于习惯或意愿。应说“从来没邀请过”，不说“从来不邀请过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
