INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13562, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "林业是指培育、保护和管理森林，以获取木材、果实等林产品的产业。", "primary_collocate": null, "pronunciation": "lín yè", "ipa": "lin˧˥ ie˥˩", "syllable_count": 2, "sentences": [{"text": "林业需要大量的工人。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我哥哥在大学学习林业。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个地区的林业很发达。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "林业工作的目的是保护森林。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从事林业工作二十年了。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发展林业可以让山更绿。", "target_word": "林业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府给林业提供了很多帮助。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "林业和农业都跟土地有关系。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家重视林业，每年都种很多树。", "target_word": "林业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的爷爷以前做过林业方面的工作。", "target_word": "林业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "林业局", "label": "复合"}, {"form": "林业工人", "label": "复合"}, {"form": "林業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "培育保护管理森林并获取林产品的产业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13562, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "林业", "is_correct": true, "explanation": "正确：“林业”是行业，可以作主语，需要大量的工人，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是自然现象，不是行业，不会需要工人。"}, {"text": "历史", "is_correct": false, "explanation": "语义：“历史”是过去发生的事，不能需要大量的工人。"}, {"text": "心情", "is_correct": false, "explanation": "搭配：“需要大量的工人”的主语须是行业或单位，“心情”不能与之搭配。"}], "explanations": {"林业": "正确：“林业”是行业，可以作主语，需要大量的工人，与句意相符。", "天气": "语义：“天气”是自然现象，不是行业，不会需要工人。", "历史": "语义：“历史”是过去发生的事，不能需要大量的工人。", "心情": "搭配：“需要大量的工人”的主语须是行业或单位，“心情”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "林业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的爱好是林业，常常在阳台种花。", "explanation": "这里应该用〈园艺〉。园艺指种花草树木的技艺或爱好，林业是产业名称，不能说成个人爱好。"}, {"text": "我爸爸是林业，每天在家里做家具。", "explanation": "这里应该用〈木工〉。木工是职业，林业是行业名称，不能用来说人的职业。"}, {"text": "山上有一大片林业。", "explanation": "这里应该用〈森林〉。林业是产业，不指树林本身，不能用“一大片”来修饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13562, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林业", "is_correct": true, "explanation": "正确：“政府给林业提供帮助”中，“林业”是接受帮助的行业，与句意相符。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是自然景象，不能接受政府的帮助。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“提供帮助”的对象须是人或单位，“数学”不能接受帮助。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的属性，不能成为接受政府帮助的对象。"}], "explanations": {"林业": "正确：“政府给林业提供帮助”中，“林业”是接受帮助的行业，与句意相符。", "天空": "语义：“天空”是自然景象，不能接受政府的帮助。", "数学": "搭配：“提供帮助”的对象须是人或单位，“数学”不能接受帮助。", "颜色": "语义：“颜色”是事物的属性，不能成为接受政府帮助的对象。"}, "sentence_index": 6, "correct_answer": "林业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块林业种了很多树。", "explanation": "这里应该用〈林地〉。林地是树林生长的土地，林业是产业名称，不能用来指一块地。"}, {"text": "工厂用林业做家具。", "explanation": "这里应该用〈木材〉。林业是产业，不是材料，做家具要用木材。"}, {"text": "这里的林业长得很高。", "explanation": "这里应该用〈树木〉。树木会生长，林业是产业，不能说它长得很高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13562, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我姐姐是林业，每天在山上工作。", "corrected_sentence": "我姐姐是林业工人，每天在山上工作。", "error_description": "错误在“林业”后缺少“工人”：“林业”是行业名称，不能直接指人，表示职业要说“林业工人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13562, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我表哥年轻时做着林业工作。", "corrected_sentence": "我表哥年轻时做过林业工作。", "error_description": "错误在“过”与“着”：“年轻时”指过去的经历，应用经历体“过”，说“做过林业工作”；“着”表示持续或进行，与“年轻时”的过去经历不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
