INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "乔木是指树身高大、主干明显、分枝点高的树木，与灌木相对。", "primary_collocate": null, "pronunciation": "qiáo mù", "ipa": "tɕʰjɑʊ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "摒弃了过去单一树种大规模种植的教训，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "公园里最高的乔木有三十米高。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵乔木的树干很粗，两个人才能抱住。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乔木长得高，夏天能给我们遮阴。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有很多乔木，比如松树和杨树。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乔木的主干明显，灌木却没有。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，松树是常见的乔木。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天，路边的乔木叶子都黄了。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林的上层是乔木，下层是小草。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟把窝搭在乔木的高处。", "target_word": "乔木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "落叶乔木", "label": "复合"}, {"form": "喬木", "label": "繁体"}], "register": "中性", "sense_fingerprint": "树身高大、主干明显的树木，与灌木相对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乔木", "is_correct": true, "explanation": "正确：乔木是高大的树木，与灌木、草本植物同属植被层次。"}, {"text": "动物", "is_correct": false, "explanation": "语义：动物不属于植被，与“灌木、草本植物”不是同一类，句子不通。"}, {"text": "矿石", "is_correct": false, "explanation": "语义：矿石不是生物，不能构成植被系统的层次。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：植被系统的组成中列举不能包括汽车，“包含汽车”与语境不搭。"}], "explanations": {"乔木": "正确：乔木是高大的树木，与灌木、草本植物同属植被层次。", "动物": "语义：动物不属于植被，与“灌木、草本植物”不是同一类，句子不通。", "矿石": "语义：矿石不是生物，不能构成植被系统的层次。", "汽车": "搭配：植被系统的组成中列举不能包括汽车，“包含汽车”与语境不搭。"}, "sentence_index": 0, "correct_answer": "乔木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这株乔木只有一尺高，蹲下就能看到它的叶子。", "explanation": "这里应该用〈灌木〉。乔木指树身高大、主干明显的树；只有一尺高、丛生的植物应说灌木。"}, {"text": "这排乔木每天早上都会唱歌。", "explanation": "这里应该用〈鸟〉。乔木是植物，不会唱歌；会唱歌的应说鸟。"}, {"text": "这种乔木会攀着墙向上长。", "explanation": "这里应该用〈藤本植物〉。乔木是直立生长的高大树木，不会攀着墙向上长；攀墙生长的是藤本植物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乔木", "is_correct": true, "explanation": "正确：松树是常见的乔木，乔木指高大的树，与松树同类。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：松树是植物而不是鱼，“常见的鱼”与松树的类别不符，句子不通。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“常见的”后面接的应是事物类别，“颜色”不能作松树所属的类别。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器与松树不属于同一类，“松树是常见的乐器”不成立。"}], "explanations": {"乔木": "正确：松树是常见的乔木，乔木指高大的树，与松树同类。", "鱼": "语义：松树是植物而不是鱼，“常见的鱼”与松树的类别不符，句子不通。", "颜色": "搭配：“常见的”后面接的应是事物类别，“颜色”不能作松树所属的类别。", "乐器": "语义：乐器与松树不属于同一类，“松树是常见的乐器”不成立。"}, "sentence_index": 6, "correct_answer": "乔木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乔木很软，摸上去很舒服。", "explanation": "这里应该用〈棉花〉。乔木是高大的树木，不能柔软得让人摸上去很舒服；柔软、摸上去舒服说的是棉花一类的东西。"}, {"text": "花园里开满了乔木。", "explanation": "这里应该用〈鲜花〉。“开满”说的是花，乔木是树，不能这样说。"}, {"text": "这栋乔木有五十层，在城市里特别显眼。", "explanation": "这里应该用〈高楼〉。乔木只指树木，不能用来指建筑物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山上有一个乔木。", "corrected_sentence": "山上有一棵乔木。", "error_description": "错误：量词“个”不能用于乔木。正确：“一棵乔木”，树木应使用量词“棵”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13564, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个乔木很高。", "corrected_sentence": "这棵乔木很高。", "error_description": "错误：量词“个”不能用于乔木。正确：“这棵乔木很高”，树木要用量词“棵”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "低矮的木本植物，没有明显主干，从地面附近就开始分枝。", "primary_collocate": null, "pronunciation": "guàn mù", "ipa": "kwan˥˩ mu˥˩", "syllable_count": 2, "sentences": [{"text": "摒弃了过去单一树种大规模种植的教训，团队邀请林业专家指导，构建了包含乔木、灌木、草本植物的多层次植被系统。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "路边的灌木只有一米高。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种灌木从地面附近就开始分枝。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园里的灌木每年春天都要修剪。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小兔子躲在灌木后面。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灌木矮矮的，不像乔木那么高。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园用灌木围成了一道绿色的墙。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，这丛灌木开满了小白花。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上长满了灌木，走路很不方便。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在给马路中间的灌木浇水。", "target_word": "灌木", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "丛", "label": "量词"}, {"form": "灌木丛", "label": "复合"}], "register": "中性", "sense_fingerprint": "低矮、无明显主干、近地面分枝的木本植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e67beeef-49bd-4c02-a835-fa2b3ca19b5a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "灌木", "is_correct": true, "explanation": "正确。灌木是低矮、没有明显主干的木本植物，与乔木、草本植物并列为植被层次之一。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是果实，不是植被的层次类型，不能与乔木、草本植物并列。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是植物，不能列入植被系统的组成部分。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：花朵是植物的一部分，不能与乔木、草本植物并列作为植物类型。"}], "explanations": {"灌木": "正确。灌木是低矮、没有明显主干的木本植物，与乔木、草本植物并列为植被层次之一。", "水果": "语义：水果是果实，不是植被的层次类型，不能与乔木、草本植物并列。", "石头": "语义：石头不是植物，不能列入植被系统的组成部分。", "花朵": "搭配：花朵是植物的一部分，不能与乔木、草本植物并列作为植物类型。"}, "sentence_index": 0, "correct_answer": "灌木"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "院子角落里立着一棵灌木，树干笔直，像一根柱子。", "explanation": "这里应该用〈乔木〉。灌木没有明显主干；树干笔直、像柱子一样立着的是乔木。"}, {"text": "灌木的茎很软，冬天容易枯死。", "explanation": "这里应该用〈草本植物〉。灌木的茎木质化、较硬，不会因为一个冬天就枯死；茎柔软、容易枯死是草本植物的特点。"}, {"text": "这棵灌木的树干很粗，要两个人才能抱住。", "explanation": "这里应该用〈乔木〉。灌木没有明显主干，说“树干很粗、要两个人才能抱住”的是有明显主干的乔木。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "灌木", "is_correct": true, "explanation": "正确。灌木矮矮的，可以用来围成一道绿色的墙。"}, {"text": "红砖", "is_correct": false, "explanation": "语义：红砖是红色的，与“绿色的墙”的颜色相矛盾。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能用来围成墙，句子说的是公园里的围墙。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，不能围成一道墙。"}], "explanations": {"灌木": "正确。灌木矮矮的，可以用来围成一道绿色的墙。", "红砖": "语义：红砖是红色的，与“绿色的墙”的颜色相矛盾。", "玩具": "语义：玩具不能用来围成墙，句子说的是公园里的围墙。", "空气": "语义：空气看不见、摸不着，不能围成一道墙。"}, "sentence_index": 6, "correct_answer": "灌木"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里的灌木一节一节的，又直又高，一根分枝也没有。", "explanation": "这里应该用〈竹子〉。竹子有节、直立、不分枝；灌木矮矮的，从地面附近就开始分枝，不能说“一节一节、一根分枝也没有”。"}, {"text": "河里漂着一丛灌木，顺着水流轻轻摇摆。", "explanation": "这里应该用〈水草〉。灌木长在陆地上，不会漂在河里随水摇摆；随水漂动的是水草。"}, {"text": "墙边的灌木中间是空的，细长的茎风一吹就弯下腰。", "explanation": "这里应该用〈芦苇〉。灌木的茎是木质的，不是中空的；中空、细长、风一吹就弯腰的是芦苇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人在马路中间种了几丛灌木们。", "corrected_sentence": "工人在马路中间种了几丛灌木。", "error_description": "错在“灌木”后面加了“们”。灌木是植物名词，不能表示复数，应直接说“几丛灌木”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13565, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "春天，山坡上长出了一支灌木。", "corrected_sentence": "春天，山坡上长出了一丛灌木。", "error_description": "错在量词。“灌木”应用量词“丛”，“支”用于细长的杆状物，不能修饰灌木。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8350ae68-9acc-4103-b9dd-764ca1e3d2d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
