INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13570, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "红外是波长比可见光长的电磁波，常用于遥控、热成像等。", "primary_collocate": null, "pronunciation": "hóng wài", "ipa": "xʊŋ˧˥ waɪ˥˩", "syllable_count": 2, "sentences": [{"text": "电视遥控器靠红外把信号传给电视。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院用红外测体温，又快又方便。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红外的波长比可见光长。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台热成像仪是靠红外看到热量的。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的旧手机能发出红外，当遥控器用。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里没有灯，监控靠红外拍下了小偷。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红外会被墙挡住，所以遥控器要对着电视。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，红外和可见光都是电磁波。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种相机能接收红外，所以夜里也能拍照。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调的遥控器发射的是红外，不是声音。", "target_word": "红外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "红外线", "label": "复合"}, {"form": "紅外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "红外：波长比可见光长的电磁波，用于遥控、热成像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13570, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "红外", "is_correct": true, "explanation": "正确：红外线是遥控器传递信号的媒介，与“靠红外把信号传给电视”一致。"}, {"text": "紫外", "is_correct": false, "explanation": "语义：紫外线同样看不见，但用于杀菌、验钞，遥控器并不用它传信号。"}, {"text": "声音", "is_correct": false, "explanation": "语义：遥控器不靠声音传信号，而是靠看不见的红外。"}, {"text": "红光", "is_correct": false, "explanation": "语义：红光是人眼能看见的可见光，遥控器用的是看不见的红外。"}], "explanations": {"红外": "正确：红外线是遥控器传递信号的媒介，与“靠红外把信号传给电视”一致。", "紫外": "语义：紫外线同样看不见，但用于杀菌、验钞，遥控器并不用它传信号。", "声音": "语义：遥控器不靠声音传信号，而是靠看不见的红外。", "红光": "语义：红光是人眼能看见的可见光，遥控器用的是看不见的红外。"}, "sentence_index": 0, "correct_answer": "红外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的新裙子是红外的，很漂亮。", "explanation": "这里应该用〈红色〉。红外是人眼看不见的光，不是颜色，不能用来说裙子的颜色；红色才是可见的颜色。"}, {"text": "这束红外很刺眼，大家都不敢看。", "explanation": "这里应该用〈红光〉。红外是人眼看不见的光，不会刺眼；刺眼的是可见的红光。"}, {"text": "我用红外听到了远处的音乐。", "explanation": "这里应该用〈耳朵〉。红外是看不见的光，不能用来听声音；听音乐要用耳朵。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13570, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "红外", "is_correct": true, "explanation": "正确：红外是光，会被墙挡住，所以遥控器要对着电视。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不会被墙挡住，也不需要“对着电视”，与句意不符。"}, {"text": "时间", "is_correct": false, "explanation": "语义：时间不是物体或光，不会被墙挡住，遥控器也不靠时间传信号。"}, {"text": "生日", "is_correct": false, "explanation": "语义：生日是日子，不能被墙挡住，与遥控器无关。"}], "explanations": {"红外": "正确：红外是光，会被墙挡住，所以遥控器要对着电视。", "空气": "语义：空气不会被墙挡住，也不需要“对着电视”，与句意不符。", "时间": "语义：时间不是物体或光，不会被墙挡住，遥控器也不靠时间传信号。", "生日": "语义：生日是日子，不能被墙挡住，与遥控器无关。"}, "sentence_index": 6, "correct_answer": "红外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生用红外看胎儿的心跳。", "explanation": "这里应该用〈超声波〉。超声波用于B超、测心跳；红外是光，不能用来测心跳。"}, {"text": "收音机靠红外接收广播。", "explanation": "这里应该用〈无线电〉。广播靠无线电波传送；红外是光，传输距离很短，不能用来接收广播。"}, {"text": "夜里有了红外，人就能看见东西。", "explanation": "这里应该用〈可见光〉。人眼看不见红外，夜里要看清东西需要可见光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13570, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台仪器能发出一个红外。", "corrected_sentence": "这台仪器能发出一束红外。", "error_description": "量词错误：红外是光线，应说“一束红外”；“个”不能计量光线。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13570, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "遥控器发出了一块红外。", "corrected_sentence": "遥控器发出了一束红外。", "error_description": "量词错误：红外是光线，应说“一束红外”；“块”用于块状实物。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
