INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13571, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "相机是一种利用光学成像原理记录影像的设备，用于拍摄照片或视频。", "primary_collocate": null, "pronunciation": "xiàng jī", "ipa": "ɕjɑŋ˥˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我新买了一台相机。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机能拍照，也能拍视频。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，他每天都带着相机。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机的镜头很干净，拍出来的照片很清楚。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机没电了，我们先去充电。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把相机放在桌子上，开始拍照。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台相机的价格不便宜。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用相机给全家人拍了一张照片。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你帮我们用相机拍一张合影。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "相机里的照片太多，存不下了。", "target_word": "相机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "数码相机", "label": "复合"}, {"form": "相机包", "label": "复合"}, {"form": "相機", "label": "繁体"}], "register": "中性", "sense_fingerprint": "相机：利用光学成像记录影像的拍摄设备", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13571, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "相机", "is_correct": true, "explanation": "正确：xiàng jī，指利用光学成像拍摄照片或视频的设备。"}, {"text": "香几", "is_correct": false, "explanation": "xiāng jī 与 xiàng jī 只有第一音节声调不同，意思是放香炉的小桌。"}, {"text": "向西", "is_correct": false, "explanation": "xiàng xī 与 xiàng jī 第二音节声母不同（x 与 j），声调相同，意思是朝西方。"}, {"text": "相继", "is_correct": false, "explanation": "xiāng jì 与 xiàng jī 两个音节声调都不同，意思是接连不断。"}], "explanations": {"相机": "正确：xiàng jī，指利用光学成像拍摄照片或视频的设备。", "香几": "xiāng jī 与 xiàng jī 只有第一音节声调不同，意思是放香炉的小桌。", "向西": "xiàng xī 与 xiàng jī 第二音节声母不同（x 与 j），声调相同，意思是朝西方。", "相继": "xiāng jì 与 xiàng jī 两个音节声调都不同，意思是接连不断。"}, "sentence_index": null, "correct_answer": "相机"}, "level_3": {"options": [{"text": "相机", "is_correct": true, "explanation": "正确：“相机”是机器，可以用“台”计量，与“我新买了一台”搭配。"}, {"text": "书", "is_correct": false, "explanation": "搭配：量词“台”用于机器，书应说“一本”，不说“一台书”。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不是可以买来拍摄的设备。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是拍摄设备，与句意不符。"}], "explanations": {"相机": "正确：“相机”是机器，可以用“台”计量，与“我新买了一台”搭配。", "书": "搭配：量词“台”用于机器，书应说“一本”，不说“一台书”。", "小狗": "语义：小狗是动物，不是可以买来拍摄的设备。", "面包": "语义：面包是食物，不是拍摄设备，与句意不符。"}, "sentence_index": 0, "correct_answer": "相机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用相机打给妈妈，告诉她我到了。", "explanation": "这里应该用〈电话〉。相机只能拍摄，不能打电话；打电话要用电话或手机。"}, {"text": "科学家用相机看细胞，看得很清楚。", "explanation": "这里应该用〈显微镜〉。看细胞要用显微镜，相机是拍摄设备。"}, {"text": "我用相机煮了一锅粥。", "explanation": "这里应该用〈锅〉。煮粥要用锅或电饭煲，相机是拍摄设备，不能用来煮东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13571, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "相机", "is_correct": true, "explanation": "正确：相机是有价格的设备，与“这台相机的价格”搭配。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：椅子用“把”或“张”计量，不说“这台椅子”。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是天然矿物，不是可以定价出售的机器，与句意不符。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气没有“价格”可言，与“价格不便宜”的说法矛盾。"}], "explanations": {"相机": "正确：相机是有价格的设备，与“这台相机的价格”搭配。", "椅子": "搭配：椅子用“把”或“张”计量，不说“这台椅子”。", "石头": "语义：石头是天然矿物，不是可以定价出售的机器，与句意不符。", "空气": "语义：空气没有“价格”可言，与“价格不便宜”的说法矛盾。"}, "sentence_index": 6, "correct_answer": "相机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "相机里放着几瓶牛奶。", "explanation": "这里应该用〈冰箱〉。相机用来拍摄，不能储存牛奶；冷藏食物要用冰箱。"}, {"text": "天热了，我打开相机吹吹风。", "explanation": "这里应该用〈电扇〉。相机是拍摄设备，不能吹风；吹风要用电扇。"}, {"text": "我每天都用相机看新闻。", "explanation": "这里应该用〈手机〉。相机是拍摄设备，看新闻要用手机或电脑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13571, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们买了三只相机。", "corrected_sentence": "我们买了三台相机。", "error_description": "量词错误：相机是机器，应说“三台相机”；“只”用于动物等，不用于机器。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13571, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了台两相机。", "corrected_sentence": "我买了两台相机。", "error_description": "语序错误：数量短语应说「两台」，「台两」语序颠倒，正确为「我买了两台相机。」", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
