INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13573, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或器具捉住正在移动的物体，常用于捕捉动物或昆虫。", "primary_collocate": null, "pronunciation": "bǔ zhuō dào", "ipa": "pu˨˩˦ ʈʂwo˥ taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "这种仿自然群落的种植模式，显著提升了栖息地质量，红外相机陆续捕捉到包括豹猫、斑羚在内的十余种野生哺乳动物踪迹，鸟类种类较十年前增加了近两倍。", "target_word": "捕捉到", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他用网捕捉到了一只蝴蝶。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在草地上捕捉到几只蚂蚱。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用杯子捕捉到一只小虫。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "猫终于捕捉到了那只老鼠。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在河边，捕捉到几条小鱼。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用网兜捕捉到一只青蛙。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "青蛙伸出舌头，捕捉到一只虫子。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边捕捉到几只小螃蟹。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明花了很久才捕捉到那只蟋蟀。", "target_word": "捕捉到", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "捕捉", "label": "原形"}, {"form": "捕捉不到", "label": "可能补语否定式"}], "register": "中性", "sense_fingerprint": "动词，用手或工具捉住移动的动物或昆虫并且成功", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13573, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "驱赶走", "is_correct": false, "explanation": "语义：“驱赶走”与“提升栖息地质量、相机记录动物踪迹”的语境相反，相机是为了记录而非驱赶。"}, {"text": "捕捉到", "is_correct": true, "explanation": "正确：红外相机捉住并记录到野生动物的踪迹，符合语境。"}, {"text": "购买到", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能说购买动物的踪迹。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：“丢失”与栖息地质量提升、动物种类增加的语境相反。"}], "explanations": {"驱赶走": "语义：“驱赶走”与“提升栖息地质量、相机记录动物踪迹”的语境相反，相机是为了记录而非驱赶。", "捕捉到": "正确：红外相机捉住并记录到野生动物的踪迹，符合语境。", "购买到": "搭配：“购买”的对象是商品，不能说购买动物的踪迹。", "丢失": "语义：“丢失”与栖息地质量提升、动物种类增加的语境相反。"}, "sentence_index": 0, "correct_answer": "捕捉到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在山上捕捉到一棵大树。", "explanation": "这里应该用〈看到〉。树木不会移动，也不能被捉住，应说看到或望见。"}, {"text": "我在桌上捕捉到一把钥匙。", "explanation": "这里应该用〈拿起〉。钥匙静止地放在桌上，不是正在移动的物体，应说拿起。"}, {"text": "他在地上捕捉到一枚硬币。", "explanation": "这里应该用〈捡起〉。硬币静止地落在地上，不是正在移动的物体，应说捡起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13573, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抚摸到", "is_correct": false, "explanation": "搭配：“网兜”是捕捞工具，不能用它来抚摸青蛙。"}, {"text": "捕捉到", "is_correct": true, "explanation": "正确：用网兜捉住移动的青蛙，符合语境。"}, {"text": "吞下", "is_correct": false, "explanation": "语义：句子说的是用网兜捉青蛙，不是吞下青蛙。"}, {"text": "卖掉", "is_correct": false, "explanation": "搭配：网兜是捕捉工具，不能“用网兜卖掉”青蛙。"}], "explanations": {"抚摸到": "搭配：“网兜”是捕捞工具，不能用它来抚摸青蛙。", "捕捉到": "正确：用网兜捉住移动的青蛙，符合语境。", "吞下": "语义：句子说的是用网兜捉青蛙，不是吞下青蛙。", "卖掉": "搭配：网兜是捕捉工具，不能“用网兜卖掉”青蛙。"}, "sentence_index": 6, "correct_answer": "捕捉到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他跑了几步，终于捕捉到了那班公交车。", "explanation": "这里应该用〈赶上〉。捕捉到指用手或器具捉住移动的小动物或昆虫，不能用来说赶上一辆车。"}, {"text": "他在路上捕捉到多年不见的朋友。", "explanation": "这里应该用〈遇见〉。捕捉用于追捉移动的目标，偶然相遇的老朋友应说遇见。"}, {"text": "我刚出门，就捕捉到了一场大雨。", "explanation": "这里应该用〈遇上〉。捕捉到指用手或器具捉住移动的小动物或昆虫，雨不能被捉住，应说遇上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13573, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在水边捕捉到的一条游动的小鱼。", "corrected_sentence": "她在水边捕捉到了一条游动的小鱼。", "error_description": "助词错误：「捕捉到了」的「了」误写成「的」，「捕捉到的一条游动的小鱼」只是名词短语，缺少谓语，应说「她在水边捕捉到了一条游动的小鱼」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13573, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在溪边捕捉了到一条小鱼。", "corrected_sentence": "他在溪边捕捉到了一条小鱼。", "error_description": "补语位置错误：结果补语「到」须紧跟动词「捕捉」，应说「捕捉到了」；「捕捉了到」中「了」的位置是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
