INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "豹猫是一种体型较小的猫科动物，身上有类似豹子的斑点，生活在森林中。", "primary_collocate": null, "pronunciation": "bào māo", "ipa": "pɑu˥˩ mɑu˥", "syllable_count": 2, "sentences": [{"text": "这种仿自然群落的种植模式，显著提升了栖息地质量，红外相机陆续捕捉到包括豹猫、斑羚在内的十余种野生哺乳动物踪迹，鸟类种类较十年前增加了近两倍。", "target_word": "豹猫", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "豹猫身上有斑点，像一只小豹子。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里有一只豹猫，它的眼睛很亮。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豹猫比家猫大一点，身上的斑点像豹子。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物园里的豹猫身上有圆圆的斑点。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "豹猫是猫科动物，常常在树林里捉老鼠。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红外相机拍到了一只在夜里走路的豹猫。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护森林，也就是保护豹猫的家。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说，豹猫的尾巴上有一圈一圈的黑色。", "target_word": "豹猫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豹猫白天睡觉，晚上在森林里找吃的。", "target_word": "豹猫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}, {"form": "豹貓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体型较小、有豹纹斑点、生活在森林里的猫科动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c14fd65d-7562-43e3-b9a1-66b88150ec98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "豹猫", "is_correct": true, "explanation": "豹猫是野生哺乳动物，与斑羚并列，符合句意。"}, {"text": "家猫", "is_correct": false, "explanation": "语义：家猫是家养宠物，不是野生哺乳动物，与“野生”的语境不符。"}, {"text": "金鱼", "is_correct": false, "explanation": "语义：金鱼不是哺乳动物，生活在水中，与“哺乳动物”不符。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "体貌：蝴蝶是昆虫，有翅膀，身体结构与哺乳动物不同。"}], "explanations": {"豹猫": "豹猫是野生哺乳动物，与斑羚并列，符合句意。", "家猫": "语义：家猫是家养宠物，不是野生哺乳动物，与“野生”的语境不符。", "金鱼": "语义：金鱼不是哺乳动物，生活在水中，与“哺乳动物”不符。", "蝴蝶": "体貌：蝴蝶是昆虫，有翅膀，身体结构与哺乳动物不同。"}, "sentence_index": 0, "correct_answer": "豹猫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家养了一只豹猫，它每天在沙发上睡觉，吃猫粮。", "explanation": "这里应该用〈家猫〉。家猫是人养在家里的宠物；豹猫是生活在森林里的野生动物。"}, {"text": "豹猫是一种很大很凶的猫科动物，能捕食野牛。", "explanation": "这里应该用〈老虎〉。老虎体型很大，能捕食野牛；豹猫体型较小，只捉老鼠、小鸟等。"}, {"text": "豹猫的脖子很长，能吃到大树顶上的叶子。", "explanation": "这里应该用〈长颈鹿〉。长颈鹿脖子很长，吃树叶；豹猫是有斑点的小型猫科动物，脖子不长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "豹猫", "is_correct": true, "explanation": "豹猫是会在夜里活动的小型猫科动物，能够走路，符合句意。"}, {"text": "鞋", "is_correct": false, "explanation": "语义：鞋不会自己走路，与“红外相机拍到的动物”不符。"}, {"text": "手", "is_correct": false, "explanation": "搭配：“走路”的主语应是人或动物，不能说“一只手走路”。"}, {"text": "船", "is_correct": false, "explanation": "体貌：船没有腿，外形上无法在夜里走路。"}], "explanations": {"豹猫": "豹猫是会在夜里活动的小型猫科动物，能够走路，符合句意。", "鞋": "语义：鞋不会自己走路，与“红外相机拍到的动物”不符。", "手": "搭配：“走路”的主语应是人或动物，不能说“一只手走路”。", "船": "体貌：船没有腿，外形上无法在夜里走路。"}, "sentence_index": 6, "correct_answer": "豹猫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她今天穿了一件豹猫的裙子。", "explanation": "这里应该用〈豹纹〉。“豹纹”指身上的斑纹图案，“豹猫”是动物名，不能用来指花纹。"}, {"text": "他真是个豹猫胆，什么危险都敢闯。", "explanation": "这里应该用〈豹子〉。“豹子胆”是固定说法，形容胆子大，不能把“豹子”换成“豹猫”。"}, {"text": "豹猫身上有黑白条纹，常常成群在草原上吃草。", "explanation": "这里应该用〈斑马〉。斑马有黑白条纹，在草原上吃草；豹猫身上是斑点，吃肉，生活在森林里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在山里看到一条豹猫。", "corrected_sentence": "我在山里看到一只豹猫。", "error_description": "量词错误：“豹猫”是动物，应用量词“只”。“条”多用于蛇、鱼等细长的东西，不用于豹猫，应改为“一只豹猫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13574, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "红外相机拍到了一只豹猫们。", "corrected_sentence": "红外相机拍到了一只豹猫。", "error_description": "量词与复数错误：“一只”表示单个，与表示复数的“们”不能同时用于“豹猫”，且“们”一般只用于人。应去掉“们”，写成“一只豹猫”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '039c40f7-075a-413f-97af-51810b361236') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "斑羚，又称青羊，是一种生活在高山地区的哺乳动物，体型像山羊，毛色灰褐，善于在悬崖峭壁上跳跃。", "primary_collocate": null, "pronunciation": "bān líng", "ipa": "pan˥ liŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这种仿自然群落的种植模式，显著提升了栖息地质量，红外相机陆续捕捉到包括豹猫、斑羚在内的十余种野生哺乳动物踪迹，鸟类种类较十年前增加了近两倍。", "target_word": "斑羚", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "斑羚住在高高的山上。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的斑羚跳得很高。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在动物园看见了一只斑羚。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚的毛是灰褐色的。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "斑羚善于在悬崖上跳来跳去。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只斑羚长得像山羊。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山坡上有一群斑羚在吃草。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到我们，斑羚很快跑进了树林。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护区里还有不少斑羚。", "target_word": "斑羚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "只", "label": "量词"}], "register": "中性", "sense_fingerprint": "名词，生活在高山悬崖地带、像山羊的灰褐色哺乳动物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e1e1bb1b-df41-4c43-a922-40e41116d20b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "蚂蚁", "is_correct": false, "explanation": "语义：蚂蚁是昆虫，不是哺乳动物，与后文“野生哺乳动物”矛盾。"}, {"text": "斑羚", "is_correct": true, "explanation": "斑羚是哺乳动物，与前面的豹猫同属野生哺乳动物，符合语境。"}, {"text": "树木", "is_correct": false, "explanation": "搭配：“树木”是植物，不能与豹猫并列，作为“哺乳动物”的成员。"}, {"text": "鲨鱼", "is_correct": false, "explanation": "语义：鲨鱼是鱼类，不是哺乳动物，不能列入“野生哺乳动物”。"}], "explanations": {"蚂蚁": "语义：蚂蚁是昆虫，不是哺乳动物，与后文“野生哺乳动物”矛盾。", "斑羚": "斑羚是哺乳动物，与前面的豹猫同属野生哺乳动物，符合语境。", "树木": "搭配：“树木”是植物，不能与豹猫并列，作为“哺乳动物”的成员。", "鲨鱼": "语义：鲨鱼是鱼类，不是哺乳动物，不能列入“野生哺乳动物”。"}, "sentence_index": 0, "correct_answer": "斑羚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在动物园看见了一条斑羚。", "explanation": "这里应该用〈只〉。斑羚是动物，用“只”；“条”多用于鱼、蛇等细长的东西。"}, {"text": "我在动物园看见了一棵斑羚。", "explanation": "这里应该用〈只〉。“棵”用于树木、植物，不用于动物。"}, {"text": "我在动物园看见了一根斑羚。", "explanation": "这里应该用〈只〉。“根”用于细长的条状物，不用于动物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大象", "is_correct": false, "explanation": "体貌：大象体型庞大、长着长鼻子，与“长得像山羊”的外形不符。"}, {"text": "斑羚", "is_correct": true, "explanation": "斑羚的外形像山羊，与“长得像山羊”的描述相符。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼生活在水中，没有四条腿，与“长得像山羊”不协调。"}, {"text": "蝴蝶", "is_correct": false, "explanation": "体貌：蝴蝶有翅膀、体形细小，与“长得像山羊”的外形不符。"}], "explanations": {"大象": "体貌：大象体型庞大、长着长鼻子，与“长得像山羊”的外形不符。", "斑羚": "斑羚的外形像山羊，与“长得像山羊”的描述相符。", "鱼": "语义：鱼生活在水中，没有四条腿，与“长得像山羊”不协调。", "蝴蝶": "体貌：蝴蝶有翅膀、体形细小，与“长得像山羊”的外形不符。"}, "sentence_index": 6, "correct_answer": "斑羚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他留着一撮斑羚胡子。", "explanation": "这里应该用〈山羊〉。“山羊胡子”是固定说法，斑羚不能这样搭配。"}, {"text": "我们每天在草场上给一群斑羚剪羊毛。", "explanation": "这里应该用〈羊〉。剪羊毛针对绵羊等家畜，斑羚是野生动物，没有可剪的羊毛。"}, {"text": "这只斑羚每天早上都会下蛋。", "explanation": "这里应该用〈鸡〉。斑羚是哺乳动物，不会下蛋，下蛋的是鸡等禽类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条斑羚在悬崖上跳了起来。", "corrected_sentence": "那只斑羚在悬崖上跳了起来。", "error_description": "量词错误：“斑羚”是动物，应使用量词“只”；“条”多用于鱼、蛇等细长的东西，不能用于斑羚。正确说法是“那只斑羚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13575, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这群斑羚的都从悬崖上跳了下去。", "corrected_sentence": "这群斑羚都从悬崖上跳了下去。", "error_description": "助词错误：「斑羚」后多出「的」，「斑羚的」变成所属关系，「都」失去所修饰的主语；应说「这群斑羚都从悬崖上跳了下去」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3360082c-63a4-4f48-b3ae-77653f1ad566') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
