INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13581, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13581, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指个体或系统自动调整自身状态以适应环境变化或达到某种平衡的过程。", "primary_collocate": null, "pronunciation": "zì wǒ tiáo jié", "ipa": "tsɨ˥˩ wɔ˨˩˦ tʰjɑʊ˧˥ tɕjɛ˧˥", "syllable_count": 4, "sentences": [{"text": "生物多样性的恢复，反过来强化了生态系统的自我调节能力，使得林区在面对极端干旱或病虫害时展现出更强的韧性。", "target_word": "自我调节", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "人体在天气变冷时会自我调节体温。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "森林能自我调节，少量虫害不会毁掉它。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里的植物会自我调节，减少水分的流失。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体出汗是一种自我调节的方式。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片湿地有很强的自我调节能力。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器温度太高时，系统会自我调节。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物到了冬天会自我调节睡眠和食量。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河流受到污染后，会慢慢自我调节，恢复平衡。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海洋可以自我调节二氧化碳的多少。", "target_word": "自我调节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "自我調節", "label": "繁体"}, {"form": "自我调节能力", "label": "复合"}], "register": "书面", "sense_fingerprint": "生物或系统自动调整自身状态以适应环境、保持平衡", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c74c4ae1-9515-4459-b540-8770b8d0940f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13581, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "自我毁灭", "is_correct": false, "explanation": "语义：“自我毁灭”与“强化能力、展现韧性”的正面语境相反，不能说明生态系统的调节能力。"}, {"text": "自我封闭", "is_correct": false, "explanation": "搭配：“自我封闭”多指与外界隔绝，不能修饰“能力”来说明生态系统的调节。"}, {"text": "自我调节", "is_correct": true, "explanation": "自我调节指系统自动调整自身状态以适应环境变化，正对应句中的“能力”。"}, {"text": "自我约束", "is_correct": false, "explanation": "语义：“约束”指限制，若强化的是约束能力，反而会压制生态系统的自动调节，与句中“展现更强韧性”的语境相反。"}], "explanations": {"自我毁灭": "语义：“自我毁灭”与“强化能力、展现韧性”的正面语境相反，不能说明生态系统的调节能力。", "自我封闭": "搭配：“自我封闭”多指与外界隔绝，不能修饰“能力”来说明生态系统的调节。", "自我调节": "自我调节指系统自动调整自身状态以适应环境变化，正对应句中的“能力”。", "自我约束": "语义：“约束”指限制，若强化的是约束能力，反而会压制生态系统的自动调节，与句中“展现更强韧性”的语境相反。"}, "sentence_index": 0, "correct_answer": "自我调节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把闹钟自我调节了一下。", "explanation": "这里应该用〈调整〉。自我调节指生物或系统自动调节自身，闹钟需要人手动调整，不能说自我调节。"}, {"text": "我把室内温度自我调节到二十度。", "explanation": "这里应该去掉〈自我〉，用〈调节〉。自我调节的动作由对象自身完成，室内温度要由人来调，应说“我把室内温度调节到二十度”。"}, {"text": "妈妈自我调节了我的作息时间。", "explanation": "这里应该用〈安排〉。自我调节的动作主体是自身，不能用来替别人调整作息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13581, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "自我生长", "is_correct": false, "explanation": "语义：“生长”是生物的成长，机器不能生长，与“温度太高”的语境无关。"}, {"text": "自我表扬", "is_correct": false, "explanation": "搭配：“表扬”的对象多为人，不能说“系统自我表扬”。"}, {"text": "自我调节", "is_correct": true, "explanation": "自我调节指系统自动调整自身状态以应对变化，正对应“温度太高”后的自动应对。"}, {"text": "自我繁殖", "is_correct": false, "explanation": "语义：“繁殖”指生物的生殖，与机器系统无关。"}], "explanations": {"自我生长": "语义：“生长”是生物的成长，机器不能生长，与“温度太高”的语境无关。", "自我表扬": "搭配：“表扬”的对象多为人，不能说“系统自我表扬”。", "自我调节": "自我调节指系统自动调整自身状态以应对变化，正对应“温度太高”后的自动应对。", "自我繁殖": "语义：“繁殖”指生物的生殖，与机器系统无关。"}, "sentence_index": 6, "correct_answer": "自我调节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人自我调节了机器的转速。", "explanation": "这里应该用〈调整〉。转速是工人从外部去调，不是机器自身自动调整，不能说工人自我调节。"}, {"text": "政府自我调节了物价。", "explanation": "这里应该用〈调控〉。物价的调控来自外部政策，不是自身自动调节，不能用自我调节。"}, {"text": "经理自我调节了人手。", "explanation": "这里应该用〈调配〉。调配是由外部决定安排人手，自我调节指自身自动调整状态，不能用于替别人分配人手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13581, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个湖泊能被自我调节水质。", "corrected_sentence": "这个湖泊能自我调节水质。", "error_description": "错误：“自我调节”是主动动词，不能加“被”构成被动式。应说“这个湖泊能自我调节水质”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13581, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "设备过热时会把自我调节。", "corrected_sentence": "设备过热时会自我调节。", "error_description": "错误：“把”字句必须有处置对象和后续的动词或补语，“会把自我调节”结构残缺，“把”不能直接加在“自我调节”前面。应说“设备过热时会自我调节。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '402b7011-48ce-46ac-b585-033ca6f8c9c9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
