INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13583, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13583, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "林区指的是有大片树木生长的区域，通常包括森林和周边自然地带。", "primary_collocate": null, "pronunciation": "lín qū", "ipa": "lin˧˥ tɕʰy˥˥", "syllable_count": 2, "sentences": [{"text": "这片林区能抵抗干旱和病虫害。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片林区的空气非常好。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，我们去林区玩了两天。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区里有很多高大的树。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在林区工作了十年。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区的冬天又冷又长。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去林区的路不太好走。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林区禁止带火种进去。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个林区住着很多小动物。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护林员每天在林区走很多路。", "target_word": "林区", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "林區", "label": "繁体"}], "register": "通用", "sense_fingerprint": "有大片树木生长的区域，包括森林和周边自然地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6a1fb72f-7f26-46aa-b253-c34484e0d5e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13583, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "林区", "is_correct": true, "explanation": "正确：林区是大片有树木的区域，能抵抗干旱和病虫害。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不是自然地带，不能抵抗干旱或病虫害。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，不能抵抗干旱或病虫害。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“抵抗”的主语应是地区或生态单位，书包不能与“抵抗干旱和病虫害”搭配。"}], "explanations": {"林区": "正确：林区是大片有树木的区域，能抵抗干旱和病虫害。", "冰箱": "语义：冰箱是家用电器，不是自然地带，不能抵抗干旱或病虫害。", "钢琴": "语义：钢琴是乐器，不能抵抗干旱或病虫害。", "书包": "搭配：“抵抗”的主语应是地区或生态单位，书包不能与“抵抗干旱和病虫害”搭配。"}, "sentence_index": 0, "correct_answer": "林区"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把林区装进了口袋。", "explanation": "这里应该用〈手帕〉。手帕能装进口袋；林区是大片有树木生长的地区，装不进口袋。"}, {"text": "他背着林区走进了教室。", "explanation": "这里应该用〈书包〉。书包可以背着走进教室；林区是大片地区，无法背着走。"}, {"text": "他把一束玫瑰插进了林区里。", "explanation": "这里应该用〈花瓶〉。花瓶用来插花；林区是大片有树木生长的地区，不能用来插花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13583, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "林区", "is_correct": true, "explanation": "正确：林区是一个地方，“去……的路”需要表示地点的词，语义通顺。"}, {"text": "闹钟", "is_correct": false, "explanation": "语义：闹钟是计时器具，不是可以前往的地方，与“去……的路”不符。"}, {"text": "雨伞", "is_correct": false, "explanation": "语义：雨伞是随身物品，不能作为前往的目的地。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“去”后面的宾语要能成为可以前往的地方，电脑不能与“去……的路”搭配。"}], "explanations": {"林区": "正确：林区是一个地方，“去……的路”需要表示地点的词，语义通顺。", "闹钟": "语义：闹钟是计时器具，不是可以前往的地方，与“去……的路”不符。", "雨伞": "语义：雨伞是随身物品，不能作为前往的目的地。", "电脑": "搭配：“去”后面的宾语要能成为可以前往的地方，电脑不能与“去……的路”搭配。"}, "sentence_index": 6, "correct_answer": "林区"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我低头看林区，能照见自己的脸。", "explanation": "这里应该用〈镜子〉。镜子能照见人影；林区是大片有树木生长的地区，不能用来照见自己。"}, {"text": "奶奶坐在林区上织毛衣。", "explanation": "这里应该用〈沙发〉。沙发可以坐人；林区是大片有树木生长的地区，不能坐在上面织毛衣。"}, {"text": "他用林区写了一封信。", "explanation": "这里应该用〈钢笔〉。钢笔用来写字；林区是大片有树木生长的地区，不能用来写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13583, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在林区上搭了一个帐篷。", "corrected_sentence": "我们在林区里搭了一个帐篷。", "error_description": "方位词用错：林区是大片地区，表示在其范围之内应用“里”，不能用“上”。正确说法是“在林区里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13583, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那张林区在山的北边。", "corrected_sentence": "那片林区在山的北边。", "error_description": "量词用错：林区指大片地区，应用“片”，“张”用于纸张、桌子等扁平物，应说“那片林区”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '69f4ea35-59be-4a4b-a754-c6218d71bbb6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
