INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13584, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "植物在生长过程中受到的病菌侵害或虫类危害。", "primary_collocate": null, "pronunciation": "bìng chóng hài", "ipa": "piŋ˥˩ ʈʂʰʊŋ˧˥ xaɪ˥˩", "syllable_count": 3, "sentences": [{"text": "生物多样性的恢复，反过来强化了生态系统的自我调节能力，使得林区在面对极端干旱或病虫害时展现出更强的韧性。", "target_word": "病虫害", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "今年雨水多，果树的病虫害比去年严重。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天去地里检查病虫害。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药可以防治苹果树的病虫害。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家来村里教大家预防病虫害。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为发生了病虫害，今年的茶叶少了很多。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "病虫害让这片菜地的白菜都枯黄了。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大棚里种菜，最怕遇到病虫害。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业部门提前发布了病虫害的预警。", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减少农药后，病虫害的问题怎么解决？", "target_word": "病虫害", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "病蟲害", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植物受病菌和害虫侵害造成的灾害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13584, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病虫害", "is_correct": true, "explanation": "“病虫害”指病菌或害虫对植物的侵害，与“极端干旱”并列，正是林区面对的威胁。"}, {"text": "人口", "is_correct": false, "explanation": "语义：“人口”指人群数量，不是对林区的自然威胁，“面对人口时”说不通。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，与干旱、灾害无关，不能填入“面对……或……时”。"}, {"text": "投资", "is_correct": false, "explanation": "搭配：“面对”后接的应是需要应对的灾害，不能说“面对投资”。"}], "explanations": {"病虫害": "“病虫害”指病菌或害虫对植物的侵害，与“极端干旱”并列，正是林区面对的威胁。", "人口": "语义：“人口”指人群数量，不是对林区的自然威胁，“面对人口时”说不通。", "工资": "语义：“工资”是劳动报酬，与干旱、灾害无关，不能填入“面对……或……时”。", "投资": "搭配：“面对”后接的应是需要应对的灾害，不能说“面对投资”。"}, "sentence_index": 0, "correct_answer": "病虫害"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我奶奶去年得了病虫害，在医院住了一个月。", "explanation": "这里应该用〈疾病〉。病虫害只指植物受病菌或害虫的侵害，不用于人。"}, {"text": "我的电脑中了病虫害，只好重新安装系统。", "explanation": "这里应该用〈病毒〉。病虫害只用于植物，不能指电脑中的病毒。"}, {"text": "这辆汽车的病虫害很严重，已经开不动了。", "explanation": "这里应该用〈故障〉。病虫害只指植物受病菌或害虫的侵害，不用于机器。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13584, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病虫害", "is_correct": true, "explanation": "这里指使白菜枯黄的侵害，是句子中造成损害的主语。"}, {"text": "礼物", "is_correct": false, "explanation": "语义：礼物不会使白菜枯黄，句子说的是造成损害的原因。"}, {"text": "歌声", "is_correct": false, "explanation": "搭配：“让……枯黄”需要致害的施事，“歌声”不能作这种致害主语。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视与白菜枯黄没有因果关系，不能作为致害原因。"}], "explanations": {"病虫害": "这里指使白菜枯黄的侵害，是句子中造成损害的主语。", "礼物": "语义：礼物不会使白菜枯黄，句子说的是造成损害的原因。", "歌声": "搭配：“让……枯黄”需要致害的施事，“歌声”不能作这种致害主语。", "电视": "语义：电视与白菜枯黄没有因果关系，不能作为致害原因。"}, "sentence_index": 6, "correct_answer": "病虫害"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场洪水是一次严重的病虫害，淹没了很多农田。", "explanation": "这里应该用〈灾害〉。病虫害只指病菌、害虫对植物的危害，洪水不属于这一类。"}, {"text": "这箱牛奶里有病虫害，大家都不能喝。", "explanation": "这里应该用〈细菌〉。病虫害只用于植物，不用于牛奶等食品。"}, {"text": "他最近工作太累，身上出现了很多病虫害。", "explanation": "这里应该用〈毛病〉。病虫害只指植物受病菌或害虫的侵害，不能用来说人的身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13584, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "去年秋天，这片果园发生了一根严重的病虫害。", "corrected_sentence": "去年秋天，这片果园发生了一场严重的病虫害。", "error_description": "量词错误：“病虫害”指一次灾害事件，应用量词“场”；“根”多用于细长的物件，不能用来计量“病虫害”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13584, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要向病虫害进行防治。", "corrected_sentence": "我们要对病虫害进行防治。", "error_description": "介词错误：“防治”的对象要用介词“对”引出，应说“对病虫害进行防治”，不能用“向”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "“弱”与“强”是反义词，都指力量或能力的大小，符合本义。"}, {"text": "慢", "is_correct": false, "explanation": "“慢”说速度，与力量、能力的大小没有反义关系。"}, {"text": "淡", "is_correct": false, "explanation": "“淡”说味道或颜色的浅，与“力量大”无关，不构成反义。"}, {"text": "矮", "is_correct": false, "explanation": "“矮”说高度，与力量、能力无关。"}], "correct_answer": "弱", "explanations": {"弱": "“弱”与“强”是反义词，都指力量或能力的大小，符合本义。", "慢": "“慢”说速度，与力量、能力的大小没有反义关系。", "淡": "“淡”说味道或颜色的浅，与“力量大”无关，不构成反义。", "矮": "“矮”说高度，与力量、能力无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "弱", "is_correct": true, "explanation": "“弱”与“强”是反义词，都指力量或能力的大小，符合本义。"}, {"text": "冷", "is_correct": false, "explanation": "“冷”指温度，与力量、能力无反义关系。"}, {"text": "远", "is_correct": false, "explanation": "“远”指距离，与力量、能力无反义关系。"}, {"text": "甜", "is_correct": false, "explanation": "“甜”描述味道，与力量、能力无反义关系。"}], "correct_answer": "弱", "explanations": {"弱": "“弱”与“强”是反义词，都指力量或能力的大小，符合本义。", "冷": "“冷”指温度，与力量、能力无反义关系。", "远": "“远”指距离，与力量、能力无反义关系。", "甜": "“甜”描述味道，与力量、能力无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量大，表示身体强壮或能力突出。", "primary_collocate": null, "pronunciation": "qiáng", "ipa": "tɕʰjaŋ˧˥", "syllable_count": 1, "sentences": [{"text": "他的工作能力很强。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子比同学强得多。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学习能力强，一看就会。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，对手比我们强。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的记忆力特别强，什么都忘不了。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理的组织能力很强，大家都服他。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我们班，数学最强的是小李。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的适应能力强，很快习惯了新学校。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支球队很强，已经赢了五场。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的修车技术很强，附近的人都找他。", "target_word": "强", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "強", "label": "繁体"}, {"form": "强大", "label": "复合词"}, {"form": "强壮", "label": "复合词"}], "register": "中性", "sense_fingerprint": "能力突出，比别人厉害", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "强", "is_correct": true, "explanation": "这是目标词本身，读 qiáng，指力量大、能力突出。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng（第三声）与 qiáng（第二声）声调不同，意思是抢夺。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是枪。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiáng（第二声）声调不同，意思是呛住。"}, {"text": "腔", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是腔调。"}], "explanations": {"强": "这是目标词本身，读 qiáng，指力量大、能力突出。", "抢": "qiǎng（第三声）与 qiáng（第二声）声调不同，意思是抢夺。", "枪": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是枪。", "呛": "qiàng（第四声）与 qiáng（第二声）声调不同，意思是呛住。", "腔": "qiāng（第一声）与 qiáng（第二声）声调不同，意思是腔调。"}, "sentence_index": null, "correct_answer": "强"}, "level_3": {"options": [{"text": "强", "is_correct": true, "explanation": "“很”后接形容能力突出的形容词，“强”与“工作能力”搭配。"}, {"text": "甜", "is_correct": false, "explanation": "语义：“甜”描述味道，不能用来形容工作能力。"}, {"text": "湿", "is_correct": false, "explanation": "搭配：“能力很湿”不成立，“湿”不能修饰“能力”。"}, {"text": "圆", "is_correct": false, "explanation": "语义：“圆”指形状，不能用来形容能力。"}], "explanations": {"强": "“很”后接形容能力突出的形容词，“强”与“工作能力”搭配。", "甜": "语义：“甜”描述味道，不能用来形容工作能力。", "湿": "搭配：“能力很湿”不成立，“湿”不能修饰“能力”。", "圆": "语义：“圆”指形状，不能用来形容能力。"}, "sentence_index": 0, "correct_answer": "强"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的价格很强，我买不起。", "explanation": "这里应该用〈贵〉。强形容力量和能力，不形容价格的高低。"}, {"text": "这座山很强，爬起来真累。", "explanation": "这里应该用〈高〉。强不用于描述山的高度，山高要说“高”。"}, {"text": "这个房间的面积很强，住三个人很宽敞。", "explanation": "这里应该用〈大〉。强用于力量与能力，面积的大小要说“大”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "强", "is_correct": true, "explanation": "这是目标词本身，读 qiáng，指力量大、能力突出。"}, {"text": "详", "is_correct": false, "explanation": "xiáng 与 qiáng 声母不同（x/q），意思是详细。"}, {"text": "前", "is_correct": false, "explanation": "qián 与 qiáng 韵母不同（an/ang），意思是前面。"}, {"text": "情", "is_correct": false, "explanation": "qíng 与 qiáng 韵母不同（ing/ang），意思是感情。"}], "explanations": {"强": "这是目标词本身，读 qiáng，指力量大、能力突出。", "详": "xiáng 与 qiáng 声母不同（x/q），意思是详细。", "前": "qián 与 qiáng 韵母不同（an/ang），意思是前面。", "情": "qíng 与 qiáng 韵母不同（ing/ang），意思是感情。"}, "sentence_index": null, "correct_answer": "强"}, "level_3": {"options": [{"text": "强", "is_correct": true, "explanation": "“最”后接形容词，“数学最强”指该科能力最突出。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”描述人的身材，不能用来形容科目成绩。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”指颜色，“数学最红”不成立。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”不能用于评价学科能力，“数学最重”说不通。"}], "explanations": {"强": "“最”后接形容词，“数学最强”指该科能力最突出。", "胖": "体貌：“胖”描述人的身材，不能用来形容科目成绩。", "红": "语义：“红”指颜色，“数学最红”不成立。", "重": "搭配：“重”不能用于评价学科能力，“数学最重”说不通。"}, "sentence_index": 6, "correct_answer": "强"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天的脸色很强，看起来精神不错。", "explanation": "这里应该用〈好〉。强不形容脸色，脸色好要说“好”。"}, {"text": "这篇文章的字数很强，老师让他删掉一半。", "explanation": "这里应该用〈多〉。强不用于字数的多少，字数多要说“多”。"}, {"text": "我的书包很强，里面装满了书。", "explanation": "这里应该用〈重〉。强不形容物体的轻重，书包沉要说“重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的记忆力越来越很强。", "corrected_sentence": "他的记忆力越来越强。", "error_description": "程度词错误：“越来越”后面不能再加“很”，应说“越来越强”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13585, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一个能力很强人。", "corrected_sentence": "她是一个能力很强的人。", "error_description": "结构错误：“能力很强”修饰名词“人”时要加“的”，应说“能力很强的人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
