INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13586, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指年龄较小的那代人，通常指年轻人群体。", "primary_collocate": null, "pronunciation": "nián qīng yí dài", "ipa": "njɛn˧˥ tɕʰiŋ˥˥ i˧˥ taɪ˥˩", "syllable_count": 4, "sentences": [{"text": "年轻一代在参与过程中重新建立了对乡土的认同感，他们拍摄纪录片，整理地方植物志，将传统农耕智慧与现代环境科学相融合。", "target_word": "年轻一代", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "年轻一代更愿意用手机买东西。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷常说，年轻一代的生活比他们那时好。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年轻一代应该爱护环境。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻一代不太喜欢住在农村了。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望年轻一代多读书，多思考。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻一代大多喜欢在网上听音乐。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻一代对新技术特别感兴趣。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司希望吸引年轻一代来工作。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老一辈的习惯，年轻一代不一定喜欢。", "target_word": "年轻一代", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年輕一代", "label": "繁体"}], "register": "中性", "sense_fingerprint": "与老一辈相对的年轻人这一代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13586, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年轻一代", "is_correct": true, "explanation": "正确。年轻一代作主语，指年轻的一代人，与「参与过程」「拍摄纪录片」的语境相符。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能参与活动、建立认同感或拍摄纪录片。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能参与过程、建立认同感或拍摄纪录片。"}, {"text": "太阳", "is_correct": false, "explanation": "配价：「参与」「建立认同感」要求有意识的施事，太阳无法充当这些动词的主语。"}], "explanations": {"年轻一代": "正确。年轻一代作主语，指年轻的一代人，与「参与过程」「拍摄纪录片」的语境相符。", "桌子": "语义：桌子是家具，不能参与活动、建立认同感或拍摄纪录片。", "石头": "语义：石头不能参与过程、建立认同感或拍摄纪录片。", "太阳": "配价：「参与」「建立认同感」要求有意识的施事，太阳无法充当这些动词的主语。"}, "sentence_index": 0, "correct_answer": "年轻一代"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班有一个年轻一代很会画画。", "explanation": "这里应该用〈年轻人〉。年轻一代指整个年轻的一代人，是集体概念，不能用「一个」指班里的某一个人。"}, {"text": "个别年轻一代不遵守规则。", "explanation": "这里应该用〈年轻人〉。年轻一代指整个一代人的集体概念，不能和表示少数个体的「个别」搭配；说少数人应用〈年轻人〉。"}, {"text": "我父亲年轻一代时期在农村工作过。", "explanation": "这里应该用〈年轻时期〉。年轻一代指一代人，不表示人生的阶段；说某人年轻时做过某事，要用〈年轻时期〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13586, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年轻一代", "is_correct": true, "explanation": "正确。年轻一代作主语，指年轻人群，与「大多喜欢在网上听音乐」相符。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥是建筑材料，不会喜欢听音乐，也不会在网上活动。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是照明用品，不会有喜好，也不能在网上听音乐。"}, {"text": "桌椅", "is_correct": false, "explanation": "语义：桌椅是家具，没有喜好，也不能听音乐。"}], "explanations": {"年轻一代": "正确。年轻一代作主语，指年轻人群，与「大多喜欢在网上听音乐」相符。", "水泥": "语义：水泥是建筑材料，不会喜欢听音乐，也不会在网上活动。", "蜡烛": "语义：蜡烛是照明用品，不会有喜好，也不能在网上听音乐。", "桌椅": "语义：桌椅是家具，没有喜好，也不能听音乐。"}, "sentence_index": 6, "correct_answer": "年轻一代"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家养了两只年轻一代，都很可爱。", "explanation": "这里应该用〈年轻人〉。年轻一代指人群，量词「只」用于动物或成对的东西，不能用来计量人群。"}, {"text": "周末我去年轻一代玩。", "explanation": "这里应该用〈公园〉。年轻一代指人群，不指地方；表示去玩的场所要说〈公园〉。"}, {"text": "这款年轻一代手机性能很好。", "explanation": "这里应该用〈新一代〉。年轻一代只指人群，不能用来修饰产品；说新款产品应用〈新一代〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13586, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "现在的一个年轻一代很关心环境。", "corrected_sentence": "现在的年轻一代很关心环境。", "error_description": "错误在于「一个」：年轻一代是泛指一代人的集体名词，前面不能加数量词「一个」计量。正确说法是「现在的年轻一代」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13586, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市的年轻一代们喜欢喝奶茶。", "corrected_sentence": "这个城市的年轻一代喜欢喝奶茶。", "error_description": "错误在于「们」：年轻一代本身是泛指一代人的集体名词，后面不能再加表示复数的「们」。正确说法是「这个城市的年轻一代」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
