INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13590, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用影像记录真实事件或人物，不加虚构的影视作品。", "primary_collocate": null, "pronunciation": "jì lù piàn", "ipa": "tɕi˥˩ lu˥˩ pʰiɛn˥˩", "syllable_count": 3, "sentences": [{"text": "年轻一代在参与过程中重新建立了对乡土的认同感，他们拍摄纪录片，整理地方植物志，将传统农耕智慧与现代环境科学相融合。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "我昨晚看了一部关于大熊猫的纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片拍了三年才完成。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想拍一部关于老街的纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在课上给我们放了一部纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "纪录片里的故事都是真实的。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片讲了一位老渔民的生活。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我们去电影院看纪录片。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看完纪录片，决定去西藏旅行。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部纪录片获得了很多人的好评。", "target_word": "纪录片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "紀錄片", "label": "繁体"}, {"form": "纪录片导演", "label": "复合"}], "register": "中性", "sense_fingerprint": "真实记录事件或人物的影视作品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a60a7be6-0797-43ec-a9b8-273314716fe4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13590, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "纪录片", "is_correct": true, "explanation": "正确。“拍摄……整理地方植物志”的并列语境中，“纪录片”是他们拍摄的影视作品。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“拍摄”用于影像、照片，不说“拍摄小说”。"}, {"text": "诗歌", "is_correct": false, "explanation": "搭配：“拍摄”针对的是影像，诗歌不能拍摄。"}, {"text": "语法", "is_correct": false, "explanation": "语义：“语法”是语言规则，不能被拍摄，与前后的影像记录不符。"}], "explanations": {"纪录片": "正确。“拍摄……整理地方植物志”的并列语境中，“纪录片”是他们拍摄的影视作品。", "小说": "搭配：“拍摄”用于影像、照片，不说“拍摄小说”。", "诗歌": "搭配：“拍摄”针对的是影像，诗歌不能拍摄。", "语法": "语义：“语法”是语言规则，不能被拍摄，与前后的影像记录不符。"}, "sentence_index": 0, "correct_answer": "纪录片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部纪录片讲了一只会说话的小猫。", "explanation": "这里应该用〈动画片〉。纪录片记录真实的人和事，不能讲会说话的小猫。"}, {"text": "这部纪录片里有飞船穿越银河。", "explanation": "这里应该用〈科幻片〉。纪录片记录真实的人和事，穿越银河的飞船属于虚构的科幻题材。"}, {"text": "这部纪录片的主角是一个会隐身的侠客。", "explanation": "这里应该用〈武侠片〉。纪录片记录真实的人和事，会隐身的侠客属于虚构的武侠题材。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13590, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纪录片", "is_correct": true, "explanation": "正确。“讲了一位老渔民的生活”说明它记录真实的人，“这部纪录片”与之相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”是通讯工具，不能讲述人的生活。"}, {"text": "菜谱", "is_correct": false, "explanation": "语义：“菜谱”记录做菜的方法，不讲人物的生活。"}, {"text": "相机", "is_correct": false, "explanation": "配价：“讲”需要能讲述的主语，“相机”不能作讲述者。"}], "explanations": {"纪录片": "正确。“讲了一位老渔民的生活”说明它记录真实的人，“这部纪录片”与之相符。", "手机": "语义：“手机”是通讯工具，不能讲述人的生活。", "菜谱": "语义：“菜谱”记录做菜的方法，不讲人物的生活。", "相机": "配价：“讲”需要能讲述的主语，“相机”不能作讲述者。"}, "sentence_index": 6, "correct_answer": "纪录片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部纪录片让玩家在虚拟世界里探险。", "explanation": "这里应该用〈游戏〉。纪录片是记录真实人和事的影视作品，让玩家在虚拟世界里探险的是游戏。"}, {"text": "这部纪录片的主角是一个会变身的超人。", "explanation": "这里应该用〈超级英雄片〉。纪录片记录真实的人和事，会变身的超人属于虚构的超级英雄题材。"}, {"text": "这部纪录片的第三集讲了一个富翁穿越时空的爱情故事。", "explanation": "这里应该用〈言情剧〉。纪录片记录真实的人和事，穿越时空的爱情故事属于虚构的言情剧。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13590, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天晚上看了一首很感人的纪录片。", "corrected_sentence": "我昨天晚上看了一部很感人的纪录片。", "error_description": "量词错误：“纪录片”是影视作品，应用量词“部”；“首”只用于歌曲、诗歌。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13590, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一部关于老渔民纪录片。", "corrected_sentence": "这是一部关于老渔民的纪录片。", "error_description": "结构错误：修饰名词“纪录片”的“关于老渔民”后面要加“的”，漏掉“的”就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c586336a-cac0-4b5e-8a88-e916975593fd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
