INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13596, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个人说的话或表达的意思。", "primary_collocate": null, "pronunciation": "huà yǔ", "ipa": "xwa˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的话语看似雄辩，内里却空洞得经不起推敲。", "target_word": "话语", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "他的话语让我很感动。", "target_word": "话语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈温暖的话语，我一直记得。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师的话语里有很多鼓励。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板的话语里有一点不满。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人的话语很简单，却很有道理。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用温和的话语安慰了孩子。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请不要用难听的话语伤害别人。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话语虽然简单，但很有力量。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电话里传来爸爸熟悉的话语。", "target_word": "话语", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "话语权", "label": "复合"}, {"form": "話語", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一个人所说的话及其表达的意思", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T3: 4 words above tier T3 (max 3): 雄辩 (Zipf 3.04), 内里 (Zipf 3.25), 经不起 (Zipf 3.26), 推敲 (Zipf 3.23)']::text[], '13188d60-d15b-49e9-baa3-e9e2c11c9219') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13596, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "话语", "is_correct": true, "explanation": "话语指人说的话或表达的意思。"}, {"text": "华语", "is_correct": false, "explanation": "huà（第四声）与 huá（第二声）声调不同，华语指华人使用的汉语。"}, {"text": "花语", "is_correct": false, "explanation": "huà（第四声）与 huā（第一声）声调不同，花语指花所代表的寓意。"}, {"text": "化育", "is_correct": false, "explanation": "huà 相同，第二音节 yǔ（三声）与 yù（四声）只差声调；化育指培养、教化。"}], "explanations": {"话语": "话语指人说的话或表达的意思。", "华语": "huà（第四声）与 huá（第二声）声调不同，华语指华人使用的汉语。", "花语": "huà（第四声）与 huā（第一声）声调不同，花语指花所代表的寓意。", "化育": "huà 相同，第二音节 yǔ（三声）与 yù（四声）只差声调；化育指培养、教化。"}, "sentence_index": null, "correct_answer": "话语"}, "level_3": {"options": [{"text": "话语", "is_correct": true, "explanation": "话语指人说的话，「看似雄辩」「空洞」都可用来形容言辞，与句意相合。"}, {"text": "食物", "is_correct": false, "explanation": "搭配：「雄辩」「空洞」形容言辞，不能修饰「食物」。"}, {"text": "建筑", "is_correct": false, "explanation": "搭配：「看似雄辩」只能用于言辞，不能修饰「建筑」。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：句中讲的是言辞的说服力，与颜料无关。"}], "explanations": {"话语": "话语指人说的话，「看似雄辩」「空洞」都可用来形容言辞，与句意相合。", "食物": "搭配：「雄辩」「空洞」形容言辞，不能修饰「食物」。", "建筑": "搭配：「看似雄辩」只能用于言辞，不能修饰「建筑」。", "颜料": "语义：句中讲的是言辞的说服力，与颜料无关。"}, "sentence_index": 0, "correct_answer": "话语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "英语是世界上使用最广的话语。", "explanation": "这里应该用〈语言〉。话语指一个人说的话，不指语言体系；英语这类语言要用语言。"}, {"text": "这件毛衣的话语正好。", "explanation": "这里应该用〈厚度〉。话语指说出的话，不指物体的厚薄；毛衣的厚薄要用厚度。"}, {"text": "这把伞的话语很便宜。", "explanation": "这里应该用〈价格〉。话语指说出的话，不指物品的价钱；伞的价钱要用价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13596, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "话语", "is_correct": true, "explanation": "话语指人说的话，「温和的话语」可以用来安慰人，与句意相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能用来安慰孩子，句中讲的是言语上的安慰。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不具备「温和」的性质，也不能安慰孩子。"}, {"text": "颜料", "is_correct": false, "explanation": "语义：颜料不能用来安慰孩子，「温和」也不修饰颜料。"}], "explanations": {"话语": "话语指人说的话，「温和的话语」可以用来安慰人，与句意相合。", "石头": "语义：石头不能用来安慰孩子，句中讲的是言语上的安慰。", "电脑": "语义：电脑不具备「温和」的性质，也不能安慰孩子。", "颜料": "语义：颜料不能用来安慰孩子，「温和」也不修饰颜料。"}, "sentence_index": 6, "correct_answer": "话语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只鸟的话语很好听。", "explanation": "这里应该用〈声音〉。话语指人说的话或表达的意思，鸟的叫声要用声音。"}, {"text": "这杯茶的话语很香。", "explanation": "这里应该用〈味道〉。话语指说出的话，不能用来形容饮品的气味和滋味。"}, {"text": "这幅画的话语很鲜艳。", "explanation": "这里应该用〈颜色〉。话语不指物体的颜色，形容颜色要用颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13596, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用一朵温暖的话语安慰了我。", "corrected_sentence": "他用温暖的话语安慰了我。", "error_description": "「话语」是集合性名词，不能用「朵」这类个体量词修饰（「朵」用于花）；应去掉「一朵」，说「温暖的话语」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13596, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他话语总是很有道理。", "corrected_sentence": "他的话语总是很有道理。", "error_description": "「话语」前的领属「他」后要加「的」，应说「他的话语」；漏掉「的」是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa21c3ca-db0c-4672-952f-90452429b298') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
