INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13601, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "话，指人用声音表达出来的言语或思想内容。", "primary_collocate": null, "pronunciation": "huà", "ipa": "xwa˥˩", "syllable_count": 1, "sentences": [{"text": "老师说的话，我都记住了。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话很少，但每一句都很重要。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把这句话再说一遍。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的话让我心里很暖。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些话我只对你一个人说过。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话我一点儿也听不懂。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的一句话，让我下了决心。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你刚才的话是什么意思？", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的话不多，却很有道理。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你要把我的话听完再回答。", "target_word": "话", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一句话", "label": "量词"}, {"form": "话语", "label": "复合"}, {"form": "对话", "label": "复合"}], "register": "中性", "sense_fingerprint": "人说出来的言语内容", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b44a80eb-78df-43d2-b3b5-0ae745060986') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13601, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "话", "is_correct": true, "explanation": "正确答案。话（huà）指人用声音表达出来的言语或思想内容。"}, {"text": "华", "is_correct": false, "explanation": "huá（第二声）与 huà（第四声）声调不同，意思是中华、华丽。"}, {"text": "花", "is_correct": false, "explanation": "huā（第一声）与 huà（第四声）声调不同，意思是花朵。"}, {"text": "活", "is_correct": false, "explanation": "huó（第二声）与 huà（第四声）声调不同，意思是活动、生存。"}, {"text": "换", "is_correct": false, "explanation": "huàn（第四声）与 huà 只差韵尾（-n 与零韵尾），意思是交换、更换。"}, {"text": "坏", "is_correct": false, "explanation": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}], "explanations": {"话": "正确答案。话（huà）指人用声音表达出来的言语或思想内容。", "华": "huá（第二声）与 huà（第四声）声调不同，意思是中华、华丽。", "花": "huā（第一声）与 huà（第四声）声调不同，意思是花朵。", "活": "huó（第二声）与 huà（第四声）声调不同，意思是活动、生存。", "换": "huàn（第四声）与 huà 只差韵尾（-n 与零韵尾），意思是交换、更换。", "坏": "huài 与 huà 韵母不同（-ai 与 -a），意思是坏、不好。"}, "sentence_index": null, "correct_answer": "话"}, "level_3": {"options": [{"text": "话", "is_correct": true, "explanation": "正确。“老师说的话”指老师说出的言语，与“我都记住了”相符。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“说”不能和“饭”搭配，老师说的是内容，不是饭。"}, {"text": "跑", "is_correct": false, "explanation": "语法：“说的”后面要接名词，“跑”是动词，“老师说的跑”不成立。"}, {"text": "很", "is_correct": false, "explanation": "语法：“很”是副词，不能放在“说的”后面作名词，句子不通。"}], "explanations": {"话": "正确。“老师说的话”指老师说出的言语，与“我都记住了”相符。", "饭": "搭配：“说”不能和“饭”搭配，老师说的是内容，不是饭。", "跑": "语法：“说的”后面要接名词，“跑”是动词，“老师说的跑”不成立。", "很": "语法：“很”是副词，不能放在“说的”后面作名词，句子不通。"}, "sentence_index": 0, "correct_answer": "话"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈唱的话让我心里很暖。", "explanation": "这里应该用〈歌〉。唱的对象是歌曲，话是说出来的言语，不能唱。"}, {"text": "他把妈妈的话放进了冰箱。", "explanation": "这里应该用〈菜〉。话是说出来的言语，不是能放进冰箱的东西。"}, {"text": "妈妈的一个话让我心里很暖。", "explanation": "量词错误：话用〈句〉计量（一句话），这里不能用〈个〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13601, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "话", "is_correct": true, "explanation": "正确答案。话（huà）指人用声音表达出来的言语或思想内容。"}, {"text": "货", "is_correct": false, "explanation": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。"}, {"text": "晃", "is_correct": false, "explanation": "huàng 与 huà 韵母不同（-ang 与 -a），意思是晃动、闪光。"}, {"text": "滑", "is_correct": false, "explanation": "huá（第二声）与 huà（第四声）声调不同，意思是光滑、滑动。"}, {"text": "换", "is_correct": false, "explanation": "huàn（第四声）与 huà 只差韵尾（-n 与零韵尾），意思是交换、更换。"}, {"text": "会", "is_correct": false, "explanation": "huì 与 huà 韵母不同（-i 与 -a），声调相同，意思是会议、会面。"}], "explanations": {"话": "正确答案。话（huà）指人用声音表达出来的言语或思想内容。", "货": "huò 与 huà 韵母不同（-o 与 -a），声调相同，意思是货物。", "晃": "huàng 与 huà 韵母不同（-ang 与 -a），意思是晃动、闪光。", "滑": "huá（第二声）与 huà（第四声）声调不同，意思是光滑、滑动。", "换": "huàn（第四声）与 huà 只差韵尾（-n 与零韵尾），意思是交换、更换。", "会": "huì 与 huà 韵母不同（-i 与 -a），声调相同，意思是会议、会面。"}, "sentence_index": null, "correct_answer": "话"}, "level_3": {"options": [{"text": "话", "is_correct": true, "explanation": "正确。“一句话”是言语的量词搭配，“让我下了决心”也说明它是话语。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：量词“句”只计量言语，不能说“一句礼物”。"}, {"text": "眼神", "is_correct": false, "explanation": "语义：眼神是视线，不是说出的话，不能用“一句”计量。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“一句书包”不成立，“句”不能计量书包。"}], "explanations": {"话": "正确。“一句话”是言语的量词搭配，“让我下了决心”也说明它是话语。", "礼物": "搭配：量词“句”只计量言语，不能说“一句礼物”。", "眼神": "语义：眼神是视线，不是说出的话，不能用“一句”计量。", "书包": "搭配：“一句书包”不成立，“句”不能计量书包。"}, "sentence_index": 6, "correct_answer": "话"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你要把我的一首话听完再回答。", "explanation": "量词错误：“首”用于诗歌、歌曲，话应用“句”计量，这里不能用“首”。"}, {"text": "你要把我的一幅话听完再回答。", "explanation": "量词错误：“幅”用于画作，话不能用“幅”计量。"}, {"text": "你要把我的一篇话听完再回答。", "explanation": "量词错误：“篇”用于文章，这里的言语应用“句”或“段”计量，不能用“篇”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13601, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请这句话写下来。", "corrected_sentence": "请把这句话写下来。", "error_description": "漏掉介词“把”：处置式“把+宾语+动词补语”要求加“把”，应说“请把这句话写下来”，不能说“请这句话写下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13601, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一句很重要话。", "corrected_sentence": "这是一句很重要的话。", "error_description": "漏掉“的”：“很重要”作“话”的定语，中间要加“的”，应说“很重要的话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f663f642-d9f3-44a7-bcfa-db27a8ed1eed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
