INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13606, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "肯定地说出判断，常指坚信某件事是真的。", "primary_collocate": null, "pronunciation": "duàn yán", "ipa": "tuan˥˩ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "可以断言，此类植根于社区自主性的实践，或将成为生态文明转型中最富生命力的基因单元。", "target_word": "断言", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "他断言明天一定会下雨。", "target_word": "断言", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "专家断言，这种病不会传染。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有证据，谁也不能断言他有罪。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生断言他三天后就能出院。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在还很难断言这个办法是否有效。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者断言这次比赛的结果已经确定。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我敢断言，他一定会回来的。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师断言这道题的答案是错的。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有看过那份报告，不能随便断言。", "target_word": "断言", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "断言了", "label": "体标"}, {"form": "断言过", "label": "体标"}], "register": "书面", "sense_fingerprint": "很有把握地对某事做出肯定的判断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc273de9-6dff-4982-aa1e-b39faa6f353a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13606, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "断言", "is_correct": true, "explanation": "正确。“可以断言”：断言指肯定地作出判断，与“可以”搭配自然。"}, {"text": "忽略", "is_correct": false, "explanation": "语义：“忽略”与后文“将成为……基因单元”的肯定判断相悖。"}, {"text": "询问", "is_correct": false, "explanation": "搭配：“询问”不接“此类实践……将成为……”这样的判断句。"}, {"text": "宣读", "is_correct": false, "explanation": "搭配：“宣读”针对文字材料，不用于作出判断。"}], "explanations": {"断言": "正确。“可以断言”：断言指肯定地作出判断，与“可以”搭配自然。", "忽略": "语义：“忽略”与后文“将成为……基因单元”的肯定判断相悖。", "询问": "搭配：“询问”不接“此类实践……将成为……”这样的判断句。", "宣读": "搭配：“宣读”针对文字材料，不用于作出判断。"}, "sentence_index": 0, "correct_answer": "断言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他断言这个问题怎么解决。", "explanation": "这里应该用〈询问〉。断言用于肯定地说出判断，不能接“怎么解决”这种疑问内容。"}, {"text": "他断言了自己的错误。", "explanation": "这里应该用〈承认〉。断言的宾语是判断或结论，不能接“错误”这类具体事实。"}, {"text": "他断言了大家的好意。", "explanation": "这里应该用〈领会〉。断言的宾语是判断或结论，不能接“好意”这类情感内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13606, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "断言", "is_correct": true, "explanation": "正确。“记者断言……已经确定”：断言指肯定地说出判断。"}, {"text": "拒绝", "is_correct": false, "explanation": "搭配：“拒绝”接请求或意见，不接“结果已经确定”这类判断。"}, {"text": "乞求", "is_correct": false, "explanation": "语义：“乞求”与“已经确定”的陈述语气相悖。"}, {"text": "翻译", "is_correct": false, "explanation": "搭配：“翻译”针对语言文字，不表示作出判断，与“已经确定”不搭。"}], "explanations": {"断言": "正确。“记者断言……已经确定”：断言指肯定地说出判断。", "拒绝": "搭配：“拒绝”接请求或意见，不接“结果已经确定”这类判断。", "乞求": "语义：“乞求”与“已经确定”的陈述语气相悖。", "翻译": "搭配：“翻译”针对语言文字，不表示作出判断，与“已经确定”不搭。"}, "sentence_index": 6, "correct_answer": "断言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家在会上断言这份方案的细节。", "explanation": "这里应该用〈讨论〉。断言的宾语是判断，不能接“细节”这类具体事项。"}, {"text": "她断言了这座城市的历史。", "explanation": "这里应该用〈介绍〉。断言表示作出判断，不用于讲述历史这类内容。"}, {"text": "老师断言：‘别再玩了！’", "explanation": "这里应该用〈要求〉。断言是肯定地说出判断，不能用于下达禁令或提出要求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13606, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不能断言了他是否来过。", "corrected_sentence": "我不能断言他是否来过。", "error_description": "错误：“不能断言了”。“了”表示动作已完成，与“不能”的否定语境冲突，应去掉“了”，说“不能断言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13606, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他从来没很断言过谁会赢。", "corrected_sentence": "他从来没断言过谁会赢。", "error_description": "错误：“很断言”。“很”修饰形容词或心理动词，“断言”是动作动词，不能被“很”修饰；应去掉“很”，说“他从来没断言过谁会赢”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17764293-4c0b-4945-83f3-d72c3766871b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
