INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13615, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变方向或位置，也指改变成另一种样子。", "primary_collocate": null, "pronunciation": "zhuǎn", "ipa": "ʈʂwan˨˩˦", "syllable_count": 1, "sentences": [{"text": "到了路口，请向左转。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气转冷了，多穿点衣服。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "走到前面的超市，再往右转。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过治疗，他的病已经转好了。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下午天气由雨转晴了。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车向北转，开上了大桥。", "target_word": "转", "complexity_tier": "T3", "furigana": "zhuǎn", "sentence_source": "generated"}, {"text": "天色由暗转亮，我们开始出发。", "target_word": "转", "complexity_tier": "T3", "furigana": "zhuǎn", "sentence_source": "generated"}, {"text": "过了红绿灯，你就往左转。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听了这话，他的脸色由白转红。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的生意开始转好了。", "target_word": "转", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转了", "label": "体标"}, {"form": "转过", "label": "体标"}, {"form": "轉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "改变方向、位置或状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f5780da-c6e6-4d29-93fe-0d7e321c3e1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13615, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转", "is_correct": true, "explanation": "转（zhuǎn）：改变方向、位置或状态，是本词条的义项。"}, {"text": "赚", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuǎn（第三声）声调不同，意思是赚钱。"}, {"text": "撰", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuǎn 声调不同，意思是撰写。"}, {"text": "砖", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn 声调不同，意思是砖头。"}, {"text": "专", "is_correct": false, "explanation": "zhuān（第一声）与 zhuǎn 声调不同，意思是专门。"}], "explanations": {"转": "转（zhuǎn）：改变方向、位置或状态，是本词条的义项。", "赚": "zhuàn（第四声）与 zhuǎn（第三声）声调不同，意思是赚钱。", "撰": "zhuàn（第四声）与 zhuǎn 声调不同，意思是撰写。", "砖": "zhuān（第一声）与 zhuǎn 声调不同，意思是砖头。", "专": "zhuān（第一声）与 zhuǎn 声调不同，意思是专门。"}, "sentence_index": null, "correct_answer": "转"}, "level_3": {"options": [{"text": "转", "is_correct": true, "explanation": "「请向左转」指车辆或人改变方向，符合路口的语境。"}, {"text": "喝", "is_correct": false, "explanation": "语义：「喝」指饮用液体，不表示方向变化，「请向左喝」与路口语境不合。"}, {"text": "笑", "is_correct": false, "explanation": "语义：「笑」不表示方向，「请向左笑」与路口的语境不合。"}, {"text": "闭", "is_correct": false, "explanation": "配价：「闭」需带宾语（闭眼），「请向左闭」缺少对象。"}], "explanations": {"转": "「请向左转」指车辆或人改变方向，符合路口的语境。", "喝": "语义：「喝」指饮用液体，不表示方向变化，「请向左喝」与路口语境不合。", "笑": "语义：「笑」不表示方向，「请向左笑」与路口的语境不合。", "闭": "配价：「闭」需带宾语（闭眼），「请向左闭」缺少对象。"}, "sentence_index": 0, "correct_answer": "转"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把牛奶转进了杯子里。", "explanation": "这里应该用〈倒〉。把液体注入容器要用“倒”，“转”表示改变方向或位置，不能用来指倒牛奶。"}, {"text": "电视台正在转放晚间新闻。", "explanation": "这里应该用〈播放〉。新闻、节目的播送要用“播放”，“转”表示改变方向或状态，不能用于播送。"}, {"text": "他把垃圾转进了垃圾桶。", "explanation": "这里应该用〈扔〉。把东西丢进容器要用“扔”，“转”不能表示丢弃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13615, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "转", "is_correct": true, "explanation": "转（zhuǎn）：改变方向、位置或状态，是本词条的义项。"}, {"text": "篆", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuǎn 声调不同，指篆书字体。"}, {"text": "传", "is_correct": false, "explanation": "zhuàn（第四声）与 zhuǎn 声调不同，指传记。"}, {"text": "装", "is_correct": false, "explanation": "zhuāng（第一声）与 zhuǎn 声调和韵尾都不同，意思是安装、装东西。"}, {"text": "庄", "is_correct": false, "explanation": "zhuāng（第一声）与 zhuǎn 声调和韵尾都不同，意思是村庄。"}], "explanations": {"转": "转（zhuǎn）：改变方向、位置或状态，是本词条的义项。", "篆": "zhuàn（第四声）与 zhuǎn 声调不同，指篆书字体。", "传": "zhuàn（第四声）与 zhuǎn 声调不同，指传记。", "装": "zhuāng（第一声）与 zhuǎn 声调和韵尾都不同，意思是安装、装东西。", "庄": "zhuāng（第一声）与 zhuǎn 声调和韵尾都不同，意思是村庄。"}, "sentence_index": null, "correct_answer": "转"}, "level_3": {"options": [{"text": "转", "is_correct": true, "explanation": "「天色由暗转亮」指天色逐渐变化，符合题干语境。"}, {"text": "跑", "is_correct": false, "explanation": "语义：「天色」不会「跑」，「由暗跑亮」不是描述变化的说法。"}, {"text": "吃", "is_correct": false, "explanation": "语义：「吃」与天色的变化无关，「由暗吃亮」不成立。"}, {"text": "推", "is_correct": false, "explanation": "配价：「推」需带宾语（推门），「由暗推亮」缺少对象。"}], "explanations": {"转": "「天色由暗转亮」指天色逐渐变化，符合题干语境。", "跑": "语义：「天色」不会「跑」，「由暗跑亮」不是描述变化的说法。", "吃": "语义：「吃」与天色的变化无关，「由暗吃亮」不成立。", "推": "配价：「推」需带宾语（推门），「由暗推亮」缺少对象。"}, "sentence_index": 6, "correct_answer": "转"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天晚上转两遍牙。", "explanation": "这里应该用〈刷〉。刷牙要用“刷”，“转”不能表示清洁牙齿的动作。"}, {"text": "他在本子上转了一行字。", "explanation": "这里应该用〈写〉。在纸上写字要用“写”，“转”不能用于书写。"}, {"text": "我每天早上转步。", "explanation": "这里应该用〈跑〉。快速移动双腿锻炼要用“跑”，“转”不能表示跑步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13615, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "到了下一个路口，你再左向转。", "corrected_sentence": "到了下一个路口，你再向左转。", "error_description": "介词“向”应放在方向词前，说“向左转”，不说“左向转”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13615, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "天气终于转了好。", "corrected_sentence": "天气终于转好了。", "error_description": "结果补语“好”应紧跟“转”，“了”放在句末，说“转好了”，不说“转了好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0bd86450-962e-4140-9952-3018e82309e9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
