INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13625, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13625, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指距离现在非常久远的过去。", "primary_collocate": null, "pronunciation": "hěn zǎo yǐ qián", "ipa": "xən²¹⁴ tsɑʊ²¹⁴ i²¹⁴ tɕʰjɛn³⁵", "syllable_count": 4, "sentences": [{"text": "很早以前，人们用风吹动风车来工作。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "很早以前，这里只有一条小河。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我很早以前就认识他了。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，爷爷住在山里。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店很早以前就关门了。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，没有电，人们晚上用蜡烛。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很早以前学过画画，现在还会。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事是很早以前奶奶讲给我听的。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很早以前，这座城市还没有地铁。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很早以前就搬到国外去了。", "target_word": "很早以前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "距离现在非常久远的过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '307c6c66-553a-4fd1-84cf-1f43674cbdfa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13625, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "很早以前", "is_correct": true, "explanation": "正确。“很早以前”指很久远的过去，与“风车”这种古老工具相合，句意通顺。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与句中描述的过去时代不符。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指近期，与“很早以前”所指的久远时间不符。"}, {"text": "今晚", "is_correct": false, "explanation": "搭配：“今晚”指当天夜里，不能用来概括这种长时段的历史情况。"}], "explanations": {"很早以前": "正确。“很早以前”指很久远的过去，与“风车”这种古老工具相合，句意通顺。", "明天": "语义：“明天”指将来，与句中描述的过去时代不符。", "上周": "语义：“上周”指近期，与“很早以前”所指的久远时间不符。", "今晚": "搭配：“今晚”指当天夜里，不能用来概括这种长时段的历史情况。"}, "sentence_index": 0, "correct_answer": "很早以前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天很早以前就到学校了。", "explanation": "这里应该用〈一大早〉。“很早以前”指久远的过去，不能和“今天”连用；说今天的早，要用“一大早”。"}, {"text": "这次考试我很早以前就交了卷。", "explanation": "这里应该用〈刚才〉。“很早以前”指久远的过去，不能用来说刚结束的考试；说不久前的事，要用“刚才”。"}, {"text": "我明天很早以前出发去机场。", "explanation": "这里应该用〈清晨〉。“很早以前”指过去，不能用于明天；说明天的早晨，要用“清晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13625, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "很早以前", "is_correct": true, "explanation": "正确。“学过”表示过去的经历，“很早以前”指久远的过去，与“现在还会”相呼应。"}, {"text": "明天", "is_correct": false, "explanation": "语义：“明天”指将来，与“学过”所表示的过去经历矛盾。"}, {"text": "下个月", "is_correct": false, "explanation": "语义：“下个月”指将来，与“学过”的过去时态不符。"}, {"text": "以后", "is_correct": false, "explanation": "搭配：“以后”指今后的时间，与“学过”这种已完成的动作不搭。"}], "explanations": {"很早以前": "正确。“学过”表示过去的经历，“很早以前”指久远的过去，与“现在还会”相呼应。", "明天": "语义：“明天”指将来，与“学过”所表示的过去经历矛盾。", "下个月": "语义：“下个月”指将来，与“学过”的过去时态不符。", "以后": "搭配：“以后”指今后的时间，与“学过”这种已完成的动作不搭。"}, "sentence_index": 6, "correct_answer": "很早以前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很早以前下午就到了那家公司。", "explanation": "这里应该用〈今天〉。“很早以前”指久远的过去，不能和“下午”这样的当天时间连用；说今天，要用“今天”。"}, {"text": "我很早以前给你发了短信，你快看看手机吧。", "explanation": "这里应该用〈刚才〉。“很早以前”指久远的过去，而“快看看手机”说明是不久前的事；说不久前，要用“刚才”。"}, {"text": "我很早以前要去北京旅行，现在正在买票。", "explanation": "这里应该用〈下个月〉。“很早以前”指久远的过去，不能用来说将要做的事；说将来，要用“下个月”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13625, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很早以前的学会了游泳。", "corrected_sentence": "他很早以前学会了游泳。", "error_description": "错误形式：“很早以前”后面不能直接加“的”再接动词；正确形式：“很早以前学会了游泳”。“很早以前”是时间状语，直接修饰动词，不能加“的”变成定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13625, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很早以前将搬到国外了。", "corrected_sentence": "他很早以前搬到国外了。", "error_description": "错误形式：“将”表示将来，不能与“很早以前”这样的过去时间连用；正确形式：去掉“将”，即“他很早以前搬到国外了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '503fd71d-248c-491d-8c92-75285f88227a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
