INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13629, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过摩擦使物体表面变得光滑或锋利。", "primary_collocate": null, "pronunciation": "mó", "ipa": "mwɔ˧˥", "syllable_count": 1, "sentences": [{"text": "他用细砂纸磨木板，让表面变得光滑。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用石头磨刀，刀变得很快。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸每天早上磨刀，然后做饭。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把刀不快了，需要磨一下。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用机器磨这块铁，让它变得光滑。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把剪刀磨得很快。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在河边磨镰刀，准备明天割草。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把木头磨光了，才开始刷漆。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块玉要慢慢磨，才会变得亮。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅正在磨斧子，斧子要用来砍树。", "target_word": "磨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "磨了", "label": "体标"}, {"form": "磨着", "label": "体标"}, {"form": "磨过", "label": "体标"}, {"form": "磨刀", "label": "复合"}, {"form": "磨光", "label": "复合"}], "register": "中性", "sense_fingerprint": "摩擦物体使其光滑或锋利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13629, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确答案：磨（mó），指通过摩擦使物体表面光滑或锋利。"}, {"text": "摸", "is_correct": false, "explanation": "mō（第一声）与 mó（第二声）声调不同，意思是用手轻触。"}, {"text": "墨", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是墨汁。"}, {"text": "婆", "is_correct": false, "explanation": "pó 与 mó 声母不同（p 与 m），意思是老年妇女。"}, {"text": "麻", "is_correct": false, "explanation": "má 与 mó 韵母不同（a 与 o），意思是麻类植物或麻木。"}, {"text": "抹", "is_correct": false, "explanation": "mǒ（第三声）与 mó（第二声）声调不同，意思是涂抹或擦去。"}], "explanations": {"磨": "正确答案：磨（mó），指通过摩擦使物体表面光滑或锋利。", "摸": "mō（第一声）与 mó（第二声）声调不同，意思是用手轻触。", "墨": "mò（第四声）与 mó（第二声）声调不同，意思是墨汁。", "婆": "pó 与 mó 声母不同（p 与 m），意思是老年妇女。", "麻": "má 与 mó 韵母不同（a 与 o），意思是麻类植物或麻木。", "抹": "mǒ（第三声）与 mó（第二声）声调不同，意思是涂抹或擦去。"}, "sentence_index": null, "correct_answer": "磨"}, "level_3": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确：磨表示用细砂纸摩擦木板，使表面变得光滑，符合句意。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”指用刀分开，不能用来使木板表面光滑。"}, {"text": "染", "is_correct": false, "explanation": "语义：“染”改变颜色，不能使木板表面变光滑。"}, {"text": "点燃", "is_correct": false, "explanation": "语义：“点燃”是使东西着火，木板被点燃后表面不会变光滑。"}], "explanations": {"磨": "正确：磨表示用细砂纸摩擦木板，使表面变得光滑，符合句意。", "切": "搭配：“切”指用刀分开，不能用来使木板表面光滑。", "染": "语义：“染”改变颜色，不能使木板表面变光滑。", "点燃": "语义：“点燃”是使东西着火，木板被点燃后表面不会变光滑。"}, "sentence_index": 0, "correct_answer": "磨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器坏了，需要磨一下。", "explanation": "这里应该用〈修理〉。磨是靠摩擦使物体光滑或锋利，机器坏了要修理。"}, {"text": "工人用尺子磨了木板的长度。", "explanation": "这里应该用〈测量〉。磨是靠摩擦使物体光滑或锋利，量长度要用测量。"}, {"text": "他拿起笔，磨了一封信。", "explanation": "这里应该用〈写〉。磨是靠摩擦使物体光滑或锋利，写信要用写。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13629, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确答案：磨（mó），指通过摩擦使物体表面光滑或锋利。"}, {"text": "默", "is_correct": false, "explanation": "mò（第四声）与 mó（第二声）声调不同，意思是不出声。"}, {"text": "伯", "is_correct": false, "explanation": "bó 与 mó 声母不同（b 与 m），意思是伯父或父亲的哥哥。"}, {"text": "佛", "is_correct": false, "explanation": "fó 与 mó 声母不同（f 与 m），意思是佛陀。"}], "explanations": {"磨": "正确答案：磨（mó），指通过摩擦使物体表面光滑或锋利。", "默": "mò（第四声）与 mó（第二声）声调不同，意思是不出声。", "伯": "bó 与 mó 声母不同（b 与 m），意思是伯父或父亲的哥哥。", "佛": "fó 与 mó 声母不同（f 与 m），意思是佛陀。"}, "sentence_index": null, "correct_answer": "磨"}, "level_3": {"options": [{"text": "磨", "is_correct": true, "explanation": "正确：磨表示用摩擦使镰刀锋利，符合准备割草的语境。"}, {"text": "撕", "is_correct": false, "explanation": "搭配：“撕”一般接纸、布等软物，不能说撕镰刀。"}, {"text": "染红", "is_correct": false, "explanation": "体貌：“染红”会改变镰刀的颜色，与准备割草的目的无关。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的对象应是人或动物，镰刀不能被喂。"}], "explanations": {"磨": "正确：磨表示用摩擦使镰刀锋利，符合准备割草的语境。", "撕": "搭配：“撕”一般接纸、布等软物，不能说撕镰刀。", "染红": "体貌：“染红”会改变镰刀的颜色，与准备割草的目的无关。", "喂": "配价：“喂”的对象应是人或动物，镰刀不能被喂。"}, "sentence_index": 6, "correct_answer": "磨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他正在磨漏水的屋顶。", "explanation": "这里应该用〈修补〉。磨是靠摩擦使物体光滑或锋利，修补漏水的屋顶要用修补。"}, {"text": "妈妈在锅里磨鱼。", "explanation": "这里应该用〈煎〉。磨是靠摩擦使物体光滑或锋利，煎鱼要用煎。"}, {"text": "她在纸上磨了一幅画。", "explanation": "这里应该用〈画〉。磨是靠摩擦使物体光滑或锋利，画画要用画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13629, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他正在磨了着刀。", "corrected_sentence": "他正在磨着刀。", "error_description": "动态助词错误：表示持续的“着”不能与“了”叠用，应为“他正在磨着刀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13629, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把斧子磨很亮。", "corrected_sentence": "他把斧子磨得很亮。", "error_description": "补语错误：表示结果的“很亮”前必须用“得”引出，漏掉“得”，应为“他把斧子磨得很亮”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
