INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13630, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "面粉是由小麦等谷物磨成的粉末，常用于制作各种面食，如馒头、面条、面包等。", "primary_collocate": null, "pronunciation": "miàn fěn", "ipa": "mjɛn˥˩ fən˨˩˦", "syllable_count": 2, "sentences": [{"text": "风吹动叶片，叶片转动，可以磨面粉或抽水。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "妈妈买了一袋面粉，准备做馒头。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做面包要先把面粉和水放在一起。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面粉洒在桌子上，到处都是白的。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂每天生产很多面粉。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用面粉和水做饺子皮。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面粉用完了，我得去超市再买一些。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小麦磨成面粉以后，才能做面条。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做蛋糕需要面粉、鸡蛋和糖。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不小心把面粉弄到了衣服上。", "target_word": "面粉", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一袋面粉", "label": "量词"}, {"form": "一斤面粉", "label": "量词"}, {"form": "面粉厂", "label": "复合"}, {"form": "麵粉", "label": "繁体"}], "register": "中性", "sense_fingerprint": "小麦磨成的粉末，用来做面食", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b6dab98-14d7-4430-bd0f-b102915e1fde') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13630, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面粉", "is_correct": true, "explanation": "正确：风车磨的是小麦等谷物，磨成的就是面粉。"}, {"text": "馒头", "is_correct": false, "explanation": "语义：馒头是做好的面食，不能再被磨。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不能用来磨，句子说的是风车磨谷物。"}, {"text": "汽油", "is_correct": false, "explanation": "搭配：“磨”不与汽油搭配，风车磨的是谷物。"}], "explanations": {"面粉": "正确：风车磨的是小麦等谷物，磨成的就是面粉。", "馒头": "语义：馒头是做好的面食，不能再被磨。", "电脑": "语义：电脑不能用来磨，句子说的是风车磨谷物。", "汽油": "搭配：“磨”不与汽油搭配，风车磨的是谷物。"}, "sentence_index": 0, "correct_answer": "面粉"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都吃面粉。", "explanation": "这里应该用〈面包〉。面粉是生的粉末，不能直接当早餐吃，吃的是面包。"}, {"text": "这碗面粉很烫，我慢慢吃。", "explanation": "这里应该用〈面条〉。面粉是做面食的原料，不能盛在碗里当热食吃。"}, {"text": "妈妈把面粉揉成了一个圆球。", "explanation": "这里应该用〈面团〉。面粉是干粉，要先加水和成面团才能揉成圆球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13630, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面粉", "is_correct": true, "explanation": "正确：面粉是日常用品，可以去超市再买。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：超市不卖汽油，与“去超市再买”冲突。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能用完后再去超市购买，句中的物品是可以买到的日用品或食品。"}, {"text": "水泥", "is_correct": false, "explanation": "语义：水泥不在超市出售，句中的“去超市”不合理。"}], "explanations": {"面粉": "正确：面粉是日常用品，可以去超市再买。", "汽油": "语义：超市不卖汽油，与“去超市再买”冲突。", "空气": "语义：空气不能用完后再去超市购买，句中的物品是可以买到的日用品或食品。", "水泥": "语义：水泥不在超市出售，句中的“去超市”不合理。"}, "sentence_index": 6, "correct_answer": "面粉"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈买了一朵面粉，准备做馒头。", "explanation": "量词用错。〈朵〉用于花、云等，面粉要用〈袋〉或〈斤〉计量。"}, {"text": "奶奶买了一条面粉，准备做面条。", "explanation": "量词用错。〈条〉用于细长的东西，面粉要用〈袋〉或〈斤〉计量。"}, {"text": "我家厨房里有一只面粉。", "explanation": "量词用错。〈只〉多用于动物或成对物品中的一个，面粉要用〈袋〉或〈斤〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13630, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "家里的面粉都用了完，我们明天去买吧。", "corrected_sentence": "家里的面粉都用完了，我们明天去买吧。", "error_description": "补语位置错误：结果补语“完”要紧跟动词，应说“用完了”，不能说“用了完”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13630, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里有一张白色的面粉。", "corrected_sentence": "厨房里有一袋白色的面粉。", "error_description": "量词错误：面粉要用“袋”计量，“张”多用于纸、桌子等扁平的东西，应为“一袋白色的面粉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'deebcdfc-2623-4b3b-a262-1127910088b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
