INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13631, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "灯是一种发光器具，通过电或燃料等能源发光，用于照明。", "primary_collocate": null, "pronunciation": "dēng", "ipa": "tɤŋ˥", "syllable_count": 1, "sentences": [{"text": "房间里的灯很亮。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，请你开灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，我把灯关了。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上有一盏灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盏灯是爸爸买的。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的灯坏了。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看书的时候开着灯。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上街上的灯都亮了。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把灯换成新的。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹在灯下写作业。", "target_word": "灯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盏", "label": "量词"}, {"form": "台灯", "label": "复合"}, {"form": "电灯", "label": "复合"}, {"form": "燈", "label": "繁体"}], "register": "中性", "sense_fingerprint": "发光照明的器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb066d7-2d45-41ad-9000-ae004e838c44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13631, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "灯", "is_correct": true, "explanation": "这是正确答案：灯（dēng），指发光照明的器具。"}, {"text": "等", "is_correct": false, "explanation": "děng（第三声）与 dēng（第一声）声调不同，意思是等待。"}, {"text": "东", "is_correct": false, "explanation": "dōng（第一声）与 dēng 只差韵母 o/e，意思是东边。"}, {"text": "当", "is_correct": false, "explanation": "dāng（第一声）与 dēng 只差韵母 a/e，意思是担任或当作。"}, {"text": "凳", "is_correct": false, "explanation": "dèng（第四声）与 dēng（第一声）声调不同，意思是板凳。"}], "explanations": {"灯": "这是正确答案：灯（dēng），指发光照明的器具。", "等": "děng（第三声）与 dēng（第一声）声调不同，意思是等待。", "东": "dōng（第一声）与 dēng 只差韵母 o/e，意思是东边。", "当": "dāng（第一声）与 dēng 只差韵母 a/e，意思是担任或当作。", "凳": "dèng（第四声）与 dēng（第一声）声调不同，意思是板凳。"}, "sentence_index": null, "correct_answer": "灯"}, "level_3": {"options": [{"text": "灯", "is_correct": true, "explanation": "正确：“房间里的灯”指发光的器具，可以“很亮”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭不会发光，不能用“很亮”形容。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌不会发光，“房间里的歌很亮”说不通。"}, {"text": "地铁", "is_correct": false, "explanation": "搭配：“房间里的”不能修饰“地铁”，地铁不在房间里。"}], "explanations": {"灯": "正确：“房间里的灯”指发光的器具，可以“很亮”。", "饭": "语义：饭不会发光，不能用“很亮”形容。", "歌": "语义：歌不会发光，“房间里的歌很亮”说不通。", "地铁": "搭配：“房间里的”不能修饰“地铁”，地铁不在房间里。"}, "sentence_index": 0, "correct_answer": "灯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "墙上挂着一条灯。", "explanation": "这里应该用〈盏〉。灯的量词是“盏”，“条”用于细长的东西，不用于灯具。"}, {"text": "我给房间买了一朵灯。", "explanation": "这里应该用〈盏〉。灯的量词是“盏”，“朵”用于花、云等，不用于灯具。"}, {"text": "他用灯洗了洗脸。", "explanation": "这里应该用〈水〉。灯是照明器具，不能用来洗脸。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13631, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "灯", "is_correct": true, "explanation": "这是正确答案：灯（dēng），指发光照明的器具。"}, {"text": "瞪", "is_correct": false, "explanation": "dèng（第四声）与 dēng（第一声）声调不同，意思是瞪眼。"}, {"text": "钉", "is_correct": false, "explanation": "dīng（第一声）与 dēng 只差韵母 i/e，意思是钉子。"}, {"text": "冬", "is_correct": false, "explanation": "dōng（第一声）与 dēng 只差韵母 o/e，意思是冬天。"}], "explanations": {"灯": "这是正确答案：灯（dēng），指发光照明的器具。", "瞪": "dèng（第四声）与 dēng（第一声）声调不同，意思是瞪眼。", "钉": "dīng（第一声）与 dēng 只差韵母 i/e，意思是钉子。", "冬": "dōng（第一声）与 dēng 只差韵母 o/e，意思是冬天。"}, "sentence_index": null, "correct_answer": "灯"}, "level_3": {"options": [{"text": "灯", "is_correct": true, "explanation": "正确：“开着灯”指灯处于亮的状态，符合看书的情境。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能被“开”，“开着猫”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能被“开”，与看书的情境无关。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“开”不能搭配“作业”，“开着作业”不成立。"}], "explanations": {"灯": "正确：“开着灯”指灯处于亮的状态，符合看书的情境。", "猫": "语义：猫不能被“开”，“开着猫”说不通。", "石头": "语义：石头不能被“开”，与看书的情境无关。", "作业": "搭配：“开”不能搭配“作业”，“开着作业”不成立。"}, "sentence_index": 6, "correct_answer": "灯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "太阳的灯很暖和。", "explanation": "这里应该用〈光〉。“太阳的光”指自然光，灯是人造的照明器具，不能说“太阳的灯”。"}, {"text": "妹妹买了一片灯。", "explanation": "这里应该用〈盏〉。灯的量词是“盏”，“片”用于薄片状的东西，不用于灯具。"}, {"text": "妹妹的床边立着一棵灯。", "explanation": "这里应该用〈盏〉。“棵”用于树木，灯不能用“棵”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13631, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一张新灯。", "corrected_sentence": "我昨天买了一盏新灯。", "error_description": "量词错误：“灯”应该用“盏”计量，“张”用于纸、桌子等平面的东西，不能说“一张灯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13631, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "出门以前，我把灯打了开。", "corrected_sentence": "出门以前，我把灯打开了。", "error_description": "了的位置错误：“打开”是动补结构，“了”应放在句末，应为“把灯打开了”，不能在“打”和“开”之间插入“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗", "is_correct": true, "explanation": "暗与“亮”构成反义，指光线不足。"}, {"text": "快", "is_correct": false, "explanation": "快与“亮”不构成反义，二者不在同一意义上对立。"}, {"text": "重", "is_correct": false, "explanation": "重与“亮”不构成反义，重是指分量大，与光线无关。"}, {"text": "软", "is_correct": false, "explanation": "软与“亮”不构成反义，二者分别描述质地和光线。"}], "correct_answer": "暗", "explanations": {"暗": "暗与“亮”构成反义，指光线不足。", "快": "快与“亮”不构成反义，二者不在同一意义上对立。", "重": "重与“亮”不构成反义，重是指分量大，与光线无关。", "软": "软与“亮”不构成反义，二者分别描述质地和光线。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暗", "is_correct": true, "explanation": "暗与“亮”构成反义，指光线不足。"}, {"text": "慢", "is_correct": false, "explanation": "慢与“亮”不构成反义，慢指速度低，与光线无关。"}, {"text": "硬", "is_correct": false, "explanation": "硬与“亮”不构成反义，硬描述质地，与光线无关。"}, {"text": "厚", "is_correct": false, "explanation": "厚与“亮”不构成反义，厚描述物体的厚度，与光线无关。"}], "correct_answer": "暗", "explanations": {"暗": "暗与“亮”构成反义，指光线不足。", "慢": "慢与“亮”不构成反义，慢指速度低，与光线无关。", "硬": "硬与“亮”不构成反义，硬描述质地，与光线无关。", "厚": "厚与“亮”不构成反义，厚描述物体的厚度，与光线无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容光线充足，或物体表面反射光的能力强。", "primary_collocate": null, "pronunciation": "liàng", "ipa": "ljɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "电可以让灯亮，让电视工作。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "天亮了，鸟儿开始叫。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的灯一直亮着。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕太亮，我的眼睛不舒服。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把桌子擦得很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上我家的灯还亮着。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没电了，屏幕不亮了。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户很大，所以屋里很亮。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红灯亮了，车都停下来。", "target_word": "亮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亮了", "label": "体标"}, {"form": "亮着", "label": "体标"}, {"form": "亮过", "label": "体标"}, {"form": "明亮", "label": "复合"}], "register": "中性", "sense_fingerprint": "光线充足、发光或反光", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0cb066d7-2d45-41ad-9000-ae004e838c44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "亮", "is_correct": true, "explanation": "这是正确答案：亮（liàng），指光线充足或物体反光强。"}, {"text": "两", "is_correct": false, "explanation": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。"}, {"text": "凉", "is_correct": false, "explanation": "liáng（第二声）与 liàng（第四声）声调不同，意思是凉。"}, {"text": "练", "is_correct": false, "explanation": "liàn 与 liàng 只差韵尾 n/ng，意思是练习。"}, {"text": "酱", "is_correct": false, "explanation": "jiàng（酱）与 liàng 只差声母 j/l，意思是酱料。"}], "explanations": {"亮": "这是正确答案：亮（liàng），指光线充足或物体反光强。", "两": "liǎng（第三声）与 liàng（第四声）声调不同，意思是两个。", "凉": "liáng（第二声）与 liàng（第四声）声调不同，意思是凉。", "练": "liàn 与 liàng 只差韵尾 n/ng，意思是练习。", "酱": "jiàng（酱）与 liàng 只差声母 j/l，意思是酱料。"}, "sentence_index": null, "correct_answer": "亮"}, "level_3": {"options": [{"text": "亮", "is_correct": true, "explanation": "正确：“让灯亮”表示灯发光，与“让电视工作”相合。"}, {"text": "冷", "is_correct": false, "explanation": "语义：灯不会因为电而变冷，“让灯冷”与句意不合。"}, {"text": "干", "is_correct": false, "explanation": "搭配：“干”形容湿度，不搭配灯，“让灯干”说不通。"}, {"text": "轻", "is_correct": false, "explanation": "语义：电不能让灯变轻，“让灯轻”与句意无关。"}], "explanations": {"亮": "正确：“让灯亮”表示灯发光，与“让电视工作”相合。", "冷": "语义：灯不会因为电而变冷，“让灯冷”与句意不合。", "干": "搭配：“干”形容湿度，不搭配灯，“让灯干”说不通。", "轻": "语义：电不能让灯变轻，“让灯轻”与句意无关。"}, "sentence_index": 0, "correct_answer": "亮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的力气很亮，一下子就扛起了箱子。", "explanation": "这里应该用〈大〉。“亮”形容光，不能形容力气，力气大要用“大”。"}, {"text": "他跑得很亮，大家都追不上他。", "explanation": "这里应该用〈快〉。“亮”不能修饰动作，形容速度要用“快”。"}, {"text": "他走路很亮，老师一直在等他。", "explanation": "这里应该用〈慢〉。“亮”不能形容走路的速度，要用“慢”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "亮", "is_correct": true, "explanation": "这是正确答案：亮（liàng），指光线充足或物体反光强。"}, {"text": "粮", "is_correct": false, "explanation": "liáng（第二声）与 liàng（第四声）声调不同，意思是粮食。"}, {"text": "炼", "is_correct": false, "explanation": "liàn 与 liàng 只差韵尾 n/ng，意思是冶炼或锻炼。"}, {"text": "酿", "is_correct": false, "explanation": "niàng 与 liàng 声母 n/l 不同，意思是酿造。"}], "explanations": {"亮": "这是正确答案：亮（liàng），指光线充足或物体反光强。", "粮": "liáng（第二声）与 liàng（第四声）声调不同，意思是粮食。", "炼": "liàn 与 liàng 只差韵尾 n/ng，意思是冶炼或锻炼。", "酿": "niàng 与 liàng 声母 n/l 不同，意思是酿造。"}, "sentence_index": null, "correct_answer": "亮"}, "level_3": {"options": [{"text": "亮", "is_correct": true, "explanation": "正确：“灯还亮着”表示灯仍在发光，与“晚上”的情境相合。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”用于人或动物的体形，灯不能说“胖”。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”用于人或动物的体形，“灯还瘦着”说不通。"}, {"text": "苦", "is_correct": false, "explanation": "语义：灯不能是苦的，“灯还苦着”与句意不合。"}], "explanations": {"亮": "正确：“灯还亮着”表示灯仍在发光，与“晚上”的情境相合。", "胖": "体貌：“胖”用于人或动物的体形，灯不能说“胖”。", "瘦": "体貌：“瘦”用于人或动物的体形，“灯还瘦着”说不通。", "苦": "语义：灯不能是苦的，“灯还苦着”与句意不合。"}, "sentence_index": 6, "correct_answer": "亮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的个子很亮，同学们都很羡慕。", "explanation": "这里应该用〈高〉。“亮”形容光或反光，不能形容身高。"}, {"text": "这杯水很亮，我现在喝不了。", "explanation": "这里应该用〈烫〉。“亮”形容光或反光，不能形容温度，水太热要用“烫”。"}, {"text": "这条河很亮，小孩子不能下去游泳。", "explanation": "这里应该用〈深〉。“亮”形容光，不能形容水的深浅，要用“深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夜里路灯一直亮了着，街道很安静。", "corrected_sentence": "夜里路灯一直亮着，街道很安静。", "error_description": "体标错误：表示持续状态要用“亮着”，“亮了着”不能说。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13632, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屏幕突然亮起去了。", "corrected_sentence": "屏幕突然亮起来了。", "error_description": "方向补语错误：应为“亮起来”，不能说“亮起去”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77a02c1c-1fe0-454d-9433-88a422d90a34') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
