INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13638, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "植物叶的扁平主体部分，与叶柄相连，是进行光合作用的主要部位。", "primary_collocate": null, "pronunciation": "yè piàn", "ipa": "je⁵¹ pʰjɛn⁵¹", "syllable_count": 2, "sentences": [{"text": "阳光照在叶片上，植物就能制造养分。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶片的表面覆盖着一层薄薄的角质层，可以减少水分流失。", "target_word": "叶片", "complexity_tier": "T5", "sentence_source": "generated"}, {"text": "叶片背面的气孔开合，帮助植物吸入二氧化碳。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶脉分布在叶片里，把水分和养分输送到各个部位。", "target_word": "叶片", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "这棵树的叶片又大又绿。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叶片通过光合作用制造养分。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天到了，叶片慢慢变黄了。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小虫把叶片咬了一个洞。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后，叶片上有很多水珠。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种植物的叶片很厚，能存水。", "target_word": "叶片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片", "label": "量词"}, {"form": "葉片", "label": "繁体"}], "register": "中性", "sense_fingerprint": "植物叶子的主体部分，进行光合作用的器官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13638, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "叶片", "is_correct": true, "explanation": "正确：叶片是植物进行光合作用的主要部位，阳光照在上面才能制造养分。"}, {"text": "树根", "is_correct": false, "explanation": "语义：树根埋在地下，不接受阳光，与光合作用无关，“阳光照在树根上”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能进行光合作用，“阳光照在石头上，植物就能制造养分”说不通。"}, {"text": "轮胎", "is_correct": false, "explanation": "语义：轮胎不是植物器官，与光合作用无关。"}], "explanations": {"叶片": "正确：叶片是植物进行光合作用的主要部位，阳光照在上面才能制造养分。", "树根": "语义：树根埋在地下，不接受阳光，与光合作用无关，“阳光照在树根上”说不通。", "石头": "语义：石头不能进行光合作用，“阳光照在石头上，植物就能制造养分”说不通。", "轮胎": "语义：轮胎不是植物器官，与光合作用无关。"}, "sentence_index": 0, "correct_answer": "叶片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只叶片，放在桌上。", "explanation": "这里应该用〈片〉。叶片的量词是“片”，“只”用于动物等，不用于叶片。"}, {"text": "这朵花的叶片一层层地铺开，香气很浓。", "explanation": "这里应该用〈花瓣〉。一层层铺开、香气浓的是花瓣；叶片指植物叶子的扁平部分，不指花的瓣。"}, {"text": "我的小狗身上长了很多叶片。", "explanation": "语义：叶片是植物叶子的一部分，不能长在动物身上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13638, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "叶片", "is_correct": true, "explanation": "正确：叶片是植物的叶子，秋天会慢慢变黄，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会因秋天慢慢变黄，句子不通。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“变黄”不搭配冰块，冰块不会变成黄色。"}, {"text": "钢笔", "is_correct": false, "explanation": "语义：钢笔是书写工具，不会随秋天变黄，句中指的是植物的变化。"}], "explanations": {"叶片": "正确：叶片是植物的叶子，秋天会慢慢变黄，符合语境。", "石头": "语义：石头不会因秋天慢慢变黄，句子不通。", "冰块": "搭配：“变黄”不搭配冰块，冰块不会变成黄色。", "钢笔": "语义：钢笔是书写工具，不会随秋天变黄，句中指的是植物的变化。"}, "sentence_index": 6, "correct_answer": "叶片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的叶片很多，我翻了一个下午。", "explanation": "这里应该用〈页〉。书的一张纸叫“页”，叶片指植物叶子的扁平部分，不指书页。"}, {"text": "爸爸正在读叶片，看得很认真。", "explanation": "这里应该用〈看〉或〈观察〉。“读”用于文字，叶片不能用来读。"}, {"text": "这根叶片很长，连着茎，把叶子托起来。", "explanation": "这里应该用〈叶柄〉。叶柄连接叶片与茎，叶片指扁平的部分，不指连接茎的细长部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13638, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "露珠挂在一根叶片上，很漂亮。", "corrected_sentence": "露珠挂在一片叶片上，很漂亮。", "error_description": "量词错误：“根”用于细长的东西，叶片应用量词“片”计量，应改为“一片叶片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13638, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "山上的几棵叶片被雪压弯了。", "corrected_sentence": "山上的几片叶片被雪压弯了。", "error_description": "量词错误：叶片应用量词“片”计量，“棵”用于整株植物，不用于叶片，应改为“几片叶片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
