INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "物体围绕一个中心或轴做圆周运动。", "primary_collocate": null, "pronunciation": "zhuàn dòng", "ipa": "ʈʂwan⁵¹ tʊŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "风吹动叶片，叶片转动，可以磨面粉或抽水。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "风吹动叶片，叶片带动机器内部的零件转动，这样就能产生电了。", "target_word": "转动", "complexity_tier": "T4", "sentence_source": "mined"}, {"text": "地球绕着地轴不停地转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电风扇的叶片在快速转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "轮子转动起来，车就走了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "驴拉着磨盘，磨盘慢慢转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "涡轮高速转动，发电机开始工作。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车床上的零件在飞快地转动。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风停了，风车就不再转动了。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "砂轮高速转动，火花四处飞。", "target_word": "转动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "转动了", "label": "体标"}, {"form": "转动着", "label": "体标"}, {"form": "转动过", "label": "体标"}, {"form": "轉動", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物体绕中心或轴做圆周运动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "转动", "is_correct": true, "explanation": "转动：物体围绕中心或轴做圆周运动。"}, {"text": "颤动", "is_correct": false, "explanation": "韵母不同：zhàn 没有 u 介音，颤动表示轻微地抖动，不是转圈。"}, {"text": "钻洞", "is_correct": false, "explanation": "声母和声调都不同：钻 zuān 的声母是 z、读第一声，zhuàn 的声母是 zh；钻洞指在物体上打洞。"}, {"text": "传动", "is_correct": false, "explanation": "声母和声调都不同：chuán 的声母是 ch、读第二声，意思是动力的传递。"}, {"text": "窜动", "is_correct": false, "explanation": "声母不同：窜 cuàn 的声母是 c，不是 zh；窜动指乱跑乱动。"}], "explanations": {"转动": "转动：物体围绕中心或轴做圆周运动。", "颤动": "韵母不同：zhàn 没有 u 介音，颤动表示轻微地抖动，不是转圈。", "钻洞": "声母和声调都不同：钻 zuān 的声母是 z、读第一声，zhuàn 的声母是 zh；钻洞指在物体上打洞。", "传动": "声母和声调都不同：chuán 的声母是 ch、读第二声，意思是动力的传递。", "窜动": "声母不同：窜 cuàn 的声母是 c，不是 zh；窜动指乱跑乱动。"}, "sentence_index": null, "correct_answer": "转动"}, "level_3": {"options": [{"text": "转动", "is_correct": true, "explanation": "正确。转动指叶片绕轴转圈，与“风吹动”和“可以磨面粉或抽水”相符。"}, {"text": "停止", "is_correct": false, "explanation": "语义：“停止”表示不动，与前面的“风吹动叶片”和后面的“可以磨面粉或抽水”矛盾。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物长大，与叶片被风吹动后的运动无关。"}, {"text": "转身", "is_correct": false, "explanation": "搭配：“转身”一般用于人或动物，不说叶片转身。"}], "explanations": {"转动": "正确。转动指叶片绕轴转圈，与“风吹动”和“可以磨面粉或抽水”相符。", "停止": "语义：“停止”表示不动，与前面的“风吹动叶片”和后面的“可以磨面粉或抽水”矛盾。", "生长": "语义：“生长”指生物长大，与叶片被风吹动后的运动无关。", "转身": "搭配：“转身”一般用于人或动物，不说叶片转身。"}, "sentence_index": 0, "correct_answer": "转动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把箱子转动到了门口。", "explanation": "这里应该用〈移动〉。转动指物体绕轴旋转；箱子从一处挪到另一处是平移，要用“移动”。"}, {"text": "妈妈在厨房里转动，忙着做饭。", "explanation": "这里应该用〈走动〉。转动只用于物体绕轴旋转，人在屋里来回走要用“走动”。"}, {"text": "抽屉在轨道上转动，推进去了。", "explanation": "这里应该用〈滑动〉。抽屉沿直线推拉是滑动，不是绕轴旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "转动", "is_correct": true, "explanation": "正确。转动指涡轮绕轴高速运转，能带动发电机工作。"}, {"text": "静止", "is_correct": false, "explanation": "语义：“静止”与“高速”矛盾，涡轮不动，发电机就无法工作。"}, {"text": "倒塌", "is_correct": false, "explanation": "搭配：“倒塌”多指建筑、墙壁等坍塌，不说涡轮倒塌。"}, {"text": "变形", "is_correct": false, "explanation": "语义：“变形”指形状改变，与“高速”的运转状态不符，也带不动发电机。"}], "explanations": {"转动": "正确。转动指涡轮绕轴高速运转，能带动发电机工作。", "静止": "语义：“静止”与“高速”矛盾，涡轮不动，发电机就无法工作。", "倒塌": "搭配：“倒塌”多指建筑、墙壁等坍塌，不说涡轮倒塌。", "变形": "语义：“变形”指形状改变，与“高速”的运转状态不符，也带不动发电机。"}, "sentence_index": 6, "correct_answer": "转动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "钟摆在左右转动。", "explanation": "这里应该用〈摆动〉。钟摆左右来回摆，不是绕轴转圈，要用“摆动”。"}, {"text": "窗帘在风里转动，来回飘。", "explanation": "这里应该用〈飘动〉。窗帘被风吹得来回飘，是左右摇摆，不是绕轴旋转。"}, {"text": "心脏在胸口里转动。", "explanation": "这里应该用〈跳动〉。心脏一起一伏地搏动要用“跳动”，转动指绕轴旋转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "风扇转动的很快。", "corrected_sentence": "风扇转动得很快。", "error_description": "错误：动词后表示程度的补语要用“得”连接，不能用“的”，应说“转动得很快”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13639, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "砂轮转动着很快，火花四处飞。", "corrected_sentence": "砂轮转动得很快，火花四处飞。", "error_description": "错误：“转动”后表示程度的补语要用“得”连接，不能用“着”，应说“转动得很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "注水", "is_correct": true, "explanation": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步与抽水的动作无关，不是它的反义词。"}, {"text": "读书", "is_correct": false, "explanation": "读书与抽水没有相对的关系，二者不是同类动作。"}, {"text": "打扫", "is_correct": false, "explanation": "打扫与抽水没有反义关系，不是相对的动作。"}], "correct_answer": "注水", "explanations": {"注水": "正确答案。注水指把水灌入某处，与抽水的方向相反，构成反义关系。", "跑步": "跑步与抽水的动作无关，不是它的反义词。", "读书": "读书与抽水没有相对的关系，二者不是同类动作。", "打扫": "打扫与抽水没有反义关系，不是相对的动作。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
