INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "通过水泵或类似设备将水从低处或水池中取出并输送到别处。", "primary_collocate": null, "pronunciation": "chōu shuǐ", "ipa": "ʈʂʰoʊ˥ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "风吹动叶片，叶片转动，可以磨面粉或抽水。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "mined"}, {"text": "农民用机器给田地抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨后，工人们在地下室抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这台水泵每小时能抽水五吨。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河里没有水了，村民只好到井边抽水。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在池塘边抽水，想把鱼捉住。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人用大机器抽水，房子很快就干了。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水管坏了，我们没法抽水。", "target_word": "抽水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "暴雨后，消防员在街上抽水，积水很快就退了。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天太干，农民每天都要抽水浇地。", "target_word": "抽水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抽了水", "label": "体标：了"}, {"form": "抽过水", "label": "体标：过"}], "register": "中性", "sense_fingerprint": "离合动词，用机器把水从低处或水池抽出送到别处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。chōu shuǐ 指用水泵把水从低处或水池中取出并送到别处。"}, {"text": "冲水", "is_correct": false, "explanation": "冲水（chōng shuǐ）与抽水的韵母不同（ong 与 ou），意思是用水冲洗，不是取水。"}, {"text": "出水", "is_correct": false, "explanation": "出水（chū shuǐ）与抽水的韵母不同（u 与 ou），意思是水从里面流出，不是用机器取水。"}, {"text": "臭水", "is_correct": false, "explanation": "臭水（chòu shuǐ）与抽水的声调不同（第四声与第一声），意思是难闻的水。"}, {"text": "抽税", "is_correct": false, "explanation": "抽税（chōu shuì）与抽水的第二个音节声调不同（第四声与第三声），意思是征收税款。"}], "explanations": {"抽水": "正确答案。chōu shuǐ 指用水泵把水从低处或水池中取出并送到别处。", "冲水": "冲水（chōng shuǐ）与抽水的韵母不同（ong 与 ou），意思是用水冲洗，不是取水。", "出水": "出水（chū shuǐ）与抽水的韵母不同（u 与 ou），意思是水从里面流出，不是用机器取水。", "臭水": "臭水（chòu shuǐ）与抽水的声调不同（第四声与第一声），意思是难闻的水。", "抽税": "抽税（chōu shuì）与抽水的第二个音节声调不同（第四声与第三声），意思是征收税款。"}, "sentence_index": null, "correct_answer": "抽水"}, "level_3": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。“可以磨面粉或抽水”指风车还能用来把水抽出，与前文风车的用途一致。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：风车靠风力转动，唱歌不是它的功能，与“磨面粉”并列也说不通。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：风车是机器，不会睡觉，与“风吹动叶片，叶片转动”的描述矛盾。"}], "explanations": {"抽水": "正确答案。“可以磨面粉或抽水”指风车还能用来把水抽出，与前文风车的用途一致。", "唱歌": "语义：风车靠风力转动，唱歌不是它的功能，与“磨面粉”并列也说不通。", "说": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。", "睡觉": "语义：风车是机器，不会睡觉，与“风吹动叶片，叶片转动”的描述矛盾。"}, "sentence_index": 0, "correct_answer": "抽水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "水库闸门一开，水就往下游抽水灌溉。", "explanation": "这里应该用〈放水〉。抽水需要水泵把水吸走，闸门打开后水自己流下去，要说放水，不能说抽水。"}, {"text": "护士用针管从病人手臂上抽水，准备化验。", "explanation": "这里应该用〈抽血〉。抽水是用水泵把水输送走，从人体里取血要说抽血，不能说抽水。"}, {"text": "小猫在河边抽水，喝得很开心。", "explanation": "这里应该用〈喝水〉。抽水要借助水泵，小猫是自己低头饮水，不能说抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抽水", "is_correct": true, "explanation": "正确答案。用大机器把积水抽走，房子才很快干了。"}, {"text": "吃", "is_correct": false, "explanation": "语义：机器不吃东西，“吃”与“房子很快就干了”的因果也对不上。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：大机器不会跳舞，与“工人用”的描述不相符。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要宾语，此处缺失，句子不完整。"}], "explanations": {"抽水": "正确答案。用大机器把积水抽走，房子才很快干了。", "吃": "语义：机器不吃东西，“吃”与“房子很快就干了”的因果也对不上。", "跳舞": "语义：大机器不会跳舞，与“工人用”的描述不相符。", "写": "配价：“写”需要宾语，此处缺失，句子不完整。"}, "sentence_index": 6, "correct_answer": "抽水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "干燥的季节，他每天都给皮肤抽水。", "explanation": "这里应该用〈补水〉。抽水是把水取出送走，不能用来给皮肤增加水分。"}, {"text": "屋檐还在一滴一滴地抽水。", "explanation": "这里应该用〈滴水〉。抽水是用机器把水取出，屋檐的水是自己往下滴，不能说抽水。"}, {"text": "纸巾可以抽水，擦干桌子。", "explanation": "这里应该用〈吸水〉。抽水是用水泵把水送到别处，纸巾靠纤维把水吸进去，不能说抽水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在地下室抽了水。", "corrected_sentence": "工人们正在地下室抽水。", "error_description": "错误：“抽了水”。正确：“抽水”。“正在”表示动作进行中，不能和表示完成的“了”一起用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人抽水着，房子慢慢干了。", "corrected_sentence": "工人抽着水，房子慢慢干了。", "error_description": "错误在“着”的位置：“着”表示动作持续，应紧跟动词，写成“抽着水”，不能放在“抽水”后面说“抽水着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
