INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在秘密或违法活动中，安排人警戒、观察周围动静，以防被人发现或打扰。", "primary_collocate": null, "pronunciation": "bǎ fēng", "ipa": "pa˨˩˦ fɤŋ˥", "syllable_count": 2, "sentences": [{"text": "他在巷子口把风，见有人来就咳嗽一声。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷进屋偷东西，另一个人在门外把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在楼下把风，怕有人上来。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你去里面拿，我在门口给你把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察来了，在外面把风的人马上跑了。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们偷偷摘果子，小明负责把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个人在路口把风，看见警察就吹口哨。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们三个人，两个进去，一个在外面把风。", "target_word": "把风", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在门口把风，怕妈妈突然回家。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板不在，你帮我在门口把风。", "target_word": "把风", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "把了风", "label": "体标：了"}, {"form": "把过风", "label": "体标：过"}], "register": "口语", "sense_fingerprint": "离合动词，秘密行动时在外面望风警戒，防止被人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'edc2b444-45c3-4e43-811d-0a9ab0a8e562') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "把风", "is_correct": true, "explanation": "正确答案。“他在巷子口把风，见有人来就咳嗽一声”中的“把风”指望风警戒、提前报信，与句意相符。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：“毕业”指完成学业，不能“在巷子口毕业”，也起不到警戒作用。"}, {"text": "桌子", "is_correct": false, "explanation": "词类：“桌子”是名词，不能作谓语放在“在巷子口”后面。"}, {"text": "说", "is_correct": false, "explanation": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。"}], "explanations": {"把风": "正确答案。“他在巷子口把风，见有人来就咳嗽一声”中的“把风”指望风警戒、提前报信，与句意相符。", "毕业": "语义：“毕业”指完成学业，不能“在巷子口毕业”，也起不到警戒作用。", "桌子": "词类：“桌子”是名词，不能作谓语放在“在巷子口”后面。", "说": "配价：“说”后面要接说的内容，此处缺少宾语，句子不成立。"}, "sentence_index": 0, "correct_answer": "把风"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "监狱里的犯人每天把风半小时。", "explanation": "这里应该用〈放风〉。把风指在外面望风警戒，不是让犯人出来透气活动。"}, {"text": "他每天早上在公园把风，锻炼身体。", "explanation": "这里应该用〈锻炼〉。把风指秘密或违法活动中望风警戒，与体育锻炼无关。"}, {"text": "屋里太闷了，应该赶快把风。", "explanation": "这里应该用〈通风〉。把风是守望警戒，不是让空气流通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "把风", "is_correct": true, "explanation": "正确答案。那个人在路口望风警戒，看见警察就吹口哨报警。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：睡觉时看不见警察，与“看见警察就吹口哨”的描述矛盾。"}, {"text": "写", "is_correct": false, "explanation": "配价：“写”需要宾语，此处缺失，句子不完整。"}, {"text": "骑", "is_correct": false, "explanation": "配价：“骑”后面要接被骑的东西，此处缺少宾语，句子不成立。"}], "explanations": {"把风": "正确答案。那个人在路口望风警戒，看见警察就吹口哨报警。", "睡觉": "语义：睡觉时看不见警察，与“看见警察就吹口哨”的描述矛盾。", "写": "配价：“写”需要宾语，此处缺失，句子不完整。", "骑": "配价：“骑”后面要接被骑的东西，此处缺少宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "把风"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天气很冷，他在窗前把风，身子直发抖。", "explanation": "这里应该用〈挡风〉。把风是守望警戒，不是阻挡风。"}, {"text": "晚上，他喜欢在阳台把风。", "explanation": "这里应该用〈吹风〉。把风是守望警戒，不是让风吹到身上。"}, {"text": "天热得很，他拿着扇子把风。", "explanation": "这里应该用〈扇风〉。把风是守望警戒，不能说用扇子把风。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们正在楼下把了风，怕有人上来。", "corrected_sentence": "他们正在楼下把风，怕有人上来。", "error_description": "错误：“把了风”。正确：“把风”。“正在”表示动作进行中，不能和表示完成的“了”一起用。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13641, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小王在路口把风着，看见车就喊。", "corrected_sentence": "小王在路口把着风，看见车就喊。", "error_description": "错误在体标“着”的位置：“着”应紧跟“把”，写成“把着风”，表示动作持续；不能放在“风”后面写成“把风着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e2a68c4-ed6c-459b-815e-decf2ac36fdf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "风的大小或强度，通常用等级表示。", "primary_collocate": null, "pronunciation": "fēng lì", "ipa": "fɤŋ˥˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "海上风电场的兴起更将发电装置迁移至风力更稳定强劲的大陆架区域。", "target_word": "风力", "complexity_tier": "T5", "sentence_source": "mined"}, {"text": "海边的风力常常比城里大。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风力变小了，我们可以出发了。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风力很小，树叶几乎不动。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天风力只有两级，适合放风筝。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天风力很大，我们不去爬山了。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气预报说明天风力有六级。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风力太强，船不能出海。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风来的时候，风力会变得很大。", "target_word": "风力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山顶的风力比山下大得多。", "target_word": "风力", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "风力发电", "label": "复合"}, {"form": "风力发电机", "label": "复合"}], "register": "中性", "sense_fingerprint": "风的大小或强度，用等级表示", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dd9edb8-eee8-4fd4-bb69-7975075c62e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "风力", "is_correct": true, "explanation": "正确。风力指风的强度，风电场迁移到风力更稳定强劲的区域，语义相符。"}, {"text": "湿度", "is_correct": false, "explanation": "语义：“湿度”指空气的潮湿程度，不能说“更稳定强劲”。"}, {"text": "风向", "is_correct": false, "explanation": "搭配：“风向”指风吹来的方向，不能用“强劲”来形容。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”指冷热程度，不能用“强劲”形容。"}], "explanations": {"风力": "正确。风力指风的强度，风电场迁移到风力更稳定强劲的区域，语义相符。", "湿度": "语义：“湿度”指空气的潮湿程度，不能说“更稳定强劲”。", "风向": "搭配：“风向”指风吹来的方向，不能用“强劲”来形容。", "气温": "语义：“气温”指冷热程度，不能用“强劲”形容。"}, "sentence_index": 0, "correct_answer": "风力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "风力从东边转到了北边。", "explanation": "这里应该用〈风向〉。风力指风的大小或强度，不指风吹来的方向。"}, {"text": "这场台风的风力达到每秒十五米。", "explanation": "这里应该用〈风速〉。风速才用“每秒多少米”计量，风力通常用等级表示。"}, {"text": "他的风力很大，能搬动那块石头。", "explanation": "这里应该用〈力气〉。风力只指风的力量，不能用来说人的力气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "风力", "is_correct": true, "explanation": "正确。风力用等级表示风的强度，“有六级”与之相符。"}, {"text": "气温", "is_correct": false, "explanation": "搭配：“气温”一般用度数表示，不说有几级。"}, {"text": "体温", "is_correct": false, "explanation": "语义：“体温”指人体的温度，与天气预报无关，不说有几级。"}, {"text": "能见度", "is_correct": false, "explanation": "语义：“能见度”指看得多远，与风的等级无关。"}], "explanations": {"风力": "正确。风力用等级表示风的强度，“有六级”与之相符。", "气温": "搭配：“气温”一般用度数表示，不说有几级。", "体温": "语义：“体温”指人体的温度，与天气预报无关，不说有几级。", "能见度": "语义：“能见度”指看得多远，与风的等级无关。"}, "sentence_index": 6, "correct_answer": "风力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他学习很有风力，从不放弃。", "explanation": "这里应该用〈毅力〉。风力只指风的力量，不能用来形容人的意志。"}, {"text": "他的写作风力很独特。", "explanation": "这里应该用〈风格〉。风力指风的力量，不能用来说文章或作品的风格。"}, {"text": "她的风力很迷人。", "explanation": "这里应该用〈魅力〉。风力指风的力量，不能用来形容人的吸引力。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天风力有四个。", "corrected_sentence": "今天风力有四级。", "error_description": "错误：风力的量词用错。风力等级要用“级”，应说“四级”，不说“四个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13642, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明天风力会减弱到三度。", "corrected_sentence": "明天风力会减弱到三级。", "error_description": "错误：风力的单位用错。风力用“级”表示等级，应说“三级”，不说“三度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a0a358-e8a1-4365-9b3f-2864121dc110') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
