INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13644, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "表示程度较轻的相似，常用于口语。", "primary_collocate": null, "pronunciation": "yǒu diǎn xiàng", "ipa": "jou²¹⁴ tjɛn²¹⁴ ɕjaŋ⁵¹", "syllable_count": 3, "sentences": [{"text": "这台机器和风车看起来有点像，但作用不同。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子的笑声有点像他妈妈。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗的样子有点像一只小熊。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话的声音有点像电视里的那个人。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种水果的味道有点像苹果。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的字写得有点像你爸爸的字。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座山的样子有点像一只大象。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜闻起来有点像鱼，可是不是鱼。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和她姐姐长得有点像，但不是双胞胎。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的面有点像我妈妈做的面。", "target_word": "有点像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有点儿像", "label": "儿化"}], "register": "口语", "sense_fingerprint": "口语中表示程度较轻的相似", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbbaefd5-2b40-495b-aa4c-25bf1b57af9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (13644, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有点像", "is_correct": true, "explanation": "正确：本词是「有点像」，表示程度较轻的相似。"}, {"text": "有点香", "is_correct": false, "explanation": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是「有点香」。"}, {"text": "有点亮", "is_correct": false, "explanation": "liàng 与 xiàng 声母不同（l 与 x），意思是「有点亮」。"}, {"text": "有点想", "is_correct": false, "explanation": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是「有点想」。"}], "explanations": {"有点像": "正确：本词是「有点像」，表示程度较轻的相似。", "有点香": "xiāng（第一声）与 xiàng（第四声）声调不同，意思是「有点香」。", "有点亮": "liàng 与 xiàng 声母不同（l 与 x），意思是「有点亮」。", "有点想": "xiǎng（第三声）与 xiàng（第四声）声调不同，意思是「有点想」。"}, "sentence_index": null, "correct_answer": "有点像"}, "level_3": {"options": [{"text": "有点像", "is_correct": true, "explanation": "正确：「有点像」表示程度较轻的相似，与「看起来」和「但作用不同」的语境相符。"}, {"text": "喜欢", "is_correct": false, "explanation": "配价：「喜欢」需要宾语，「看起来喜欢」后面没有要喜欢的对象，句子不完整。"}, {"text": "生气", "is_correct": false, "explanation": "语义：风车不会生气，「看起来生气」与「作用不同」的语境无关。"}, {"text": "认识", "is_correct": false, "explanation": "配价：「认识」要求有认识的对象，「看起来认识」缺少宾语。"}], "explanations": {"有点像": "正确：「有点像」表示程度较轻的相似，与「看起来」和「但作用不同」的语境相符。", "喜欢": "配价：「喜欢」需要宾语，「看起来喜欢」后面没有要喜欢的对象，句子不完整。", "生气": "语义：风车不会生气，「看起来生气」与「作用不同」的语境无关。", "认识": "配价：「认识」要求有认识的对象，「看起来认识」缺少宾语。"}, "sentence_index": 0, "correct_answer": "有点像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这对双胞胎完全一样，有点像。", "explanation": "这里不能用〈有点像〉。它表示轻微相似，这句说的是完全相同，二者矛盾。"}, {"text": "这两台电脑是同一台，有点像。", "explanation": "这里不能用〈有点像〉。它表示轻微相似，这句说的是同一个东西，不存在相似程度。"}, {"text": "这两份报告一模一样，有点像。", "explanation": "这里不能用〈有点像〉。它表示轻微相似，这句说的是完全相同，程度上矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '83167bfe-5c89-4d79-b6ce-37d6fca01128') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
